VRT_L("1re-d-chimie-r01",{"duree":20,"titre":"Les alcanes : structure et nomenclature","accroche":"Le gaz de cuisine est un alcane.","intro":"Les alcanes sont des hydrocarbures saturés : seulement des liaisons simples.","objectifs":["écrire la formule générale","décrire la géométrie","nommer un alcane ramifié"],"parties":[{"t":"Définition","html":"<div class='def'><b>Définition</b>Un <strong>alcane</strong> est un hydrocarbure saturé de formule <strong>CₙH₂ₙ₊₂</strong>. Chaque carbone est tétraédrique, avec des angles d'environ 109°.</div>"},{"t":"Nomenclature","html":"<ol><li>Trouver la chaîne carbonée la plus longue.</li><li>Numéroter pour donner les plus petits indices aux ramifications.</li><li>Nommer les groupes alkyles par ordre alphabétique.</li></ol><p>CH₃−CH(CH₃)−CH₂−CH₃ : 2-méthylbutane.</p>","labo":{"type":"trier","invite":"Choisis un alcane.","items":[["Méthane","CH₄, biogaz."],["Propane","C₃H₈."],["Butane","C₄H₁₀, gaz domestique."]]}},{"t":"Isomérie","html":"<p>Le butane et le 2-méthylpropane ont la même formule brute C₄H₁₀ : ce sont des isomères de chaîne.</p>","retenir":"Chaîne la plus longue, indices les plus petits."},{"t":"Entraînement au format de l'examen","html":"<div class='integ'><h3>Partie A : évaluation des ressources</h3><p><strong>Vérification des savoirs.</strong> La formule générale des alcanes est :</p><ol type='a'><li>CₙH₂ₙ</li><li>CₙH₂ₙ₊₂</li><li>CₙH₂ₙ₋₂</li></ol><details><summary>Voir la réponse</summary><p><strong>CₙH₂ₙ₊₂</strong>. Saturé.</p></details><p><strong>Application directe des savoirs.</strong></p><p>Formule brute de l'alcane à 5 carbones ?</p><details><summary>Voir la réponse</summary><p>(Réponse : C₅H₁₂.)</p></details><h3>Partie B : évaluation des compétences</h3><p><strong>Situation.</strong> Un hydrocarbure A, alcane, a une masse molaire de 72 g/mol. M(C) = 12 g/mol ; M(H) = 1 g/mol.</p><p><strong>Consigne 1.</strong> Détermine sa formule brute.</p><p><strong>Consigne 2.</strong> Écris et nomme les formules semi-développées de ses isomères.</p><details><summary>Voir une réponse attendue</summary><p>14n + 2 = 72, n = 5 : C₅H₁₂. Isomères : pentane CH₃−(CH₂)₃−CH₃ ; 2-méthylbutane CH₃−CH(CH₃)−CH₂−CH₃ ; 2,2-diméthylpropane C(CH₃)₄.</p></details></div>","retenir":"Savoir-être mobilisé : Rigueur dans la démarche expérimentale."}],"revision":["CₙH₂ₙ₊₂.","Tétraèdre.","Nomenclature."],"exo":"<p>Formule brute de l'alcane à 5 carbones ? <em>(Réponse : C₅H₁₂.)</em></p>","quiz":[{"q":"La formule générale des alcanes est :","r":["CₙH₂ₙ","CₙH₂ₙ₊₂","CₙH₂ₙ₋₂"],"b":1,"e":"Saturé."},{"q":"Le carbone d'un alcane est :","r":["tétraédrique","plan","linéaire"],"b":0,"e":"Quatre liaisons simples."},{"q":"CH₃−CH(CH₃)−CH₂−CH₃ s'appelle :","r":["pentane","3-méthylbutane","2-méthylbutane"],"b":2,"e":"Plus petit indice."},{"q":"Le butane du gaz domestique a pour formule :","r":["C₃H₈","C₄H₁₀","CH₄"],"b":1,"e":"n = 4."}],"c":"1re D","m":"chimie","rang":1,"apc":{"module":"Chimie organique : hydrocarbures et composés oxygénés","famille":"Usage des produits pétroliers et des matières plastiques","agir":"Identifier et utiliser de façon sûre les composés organiques","situation":"Une vendeuse de gaz de Bafoussam se demande ce que contient sa bouteille, qui renferme surtout du butane.","tache":"Donne sa formule brute et dessine sa formule semi-développée."},"gratuit":true});
VRT_L("1re-d-chimie-r02",{"duree":20,"titre":"Propriétés des alcanes et préparation du méthane","accroche":"Bien brûler pour ne pas s'intoxiquer.","intro":"Les alcanes brûlent et subissent des substitutions ; le méthane se prépare au laboratoire.","objectifs":["écrire une combustion","décrire une substitution","préparer le méthane"],"parties":[{"t":"Combustion","html":"<div class='def'><b>Définition</b>La <strong>combustion complète</strong> d'un alcane donne du dioxyde de carbone et de l'eau : CH₄ + 2O₂ → CO₂ + 2H₂O. Incomplète, elle produit du monoxyde de carbone, toxique.</div>"},{"t":"Substitution","verrou":true},{"t":"Préparation du méthane","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"chimie","rang":2,"apc":{"module":"Chimie organique : hydrocarbures et composés oxygénés","famille":"Usage des produits pétroliers et des matières plastiques","agir":"Identifier et utiliser de façon sûre les composés organiques","situation":"Une famille de Bamenda cuisine au gaz dans une pièce fermée et ressent des maux de tête.","tache":"Explique le danger et donne un conseil."},"verrou":true,"nq":4,"labo":true});
VRT_L("1re-d-chimie-r03",{"duree":20,"titre":"Alcènes et alcynes : structure et nomenclature","accroche":"Une double ou une triple liaison.","intro":"Les alcènes et les alcynes sont des hydrocarbures insaturés.","objectifs":["écrire leurs formules générales","décrire leur géométrie","les nommer"],"parties":[{"t":"Définitions","html":"<div class='def'><b>Définition</b>Un <strong>alcène</strong> (CₙH₂ₙ) contient une double liaison C=C, plane, angles de 120°. Un <strong>alcyne</strong> (CₙH₂ₙ₋₂) contient une triple liaison C≡C, linéaire.</div>"},{"t":"Nomenclature","verrou":true},{"t":"Isomérie Z/E","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"chimie","rang":3,"apc":{"module":"Chimie organique : hydrocarbures et composés oxygénés","famille":"Usage des produits pétroliers et des matières plastiques","agir":"Identifier et utiliser de façon sûre les composés organiques","situation":"Dans une plantation de Penja, on mûrit les bananes avec de l'éthylène, le plus simple des alcènes.","tache":"Donne sa formule et sa géométrie."},"verrou":true,"nq":4,"labo":true});
VRT_L("1re-d-chimie-r04",{"duree":20,"titre":"Propriétés des alcènes et alcynes ; acétylène","accroche":"Des additions et des plastiques.","intro":"La liaison multiple permet des réactions d'addition et de polymérisation.","objectifs":["écrire des additions","appliquer la règle de Markovnikov","décrire une polymérisation"],"parties":[{"t":"Additions","html":"<div class='def'><b>Définition</b>Les alcènes et alcynes donnent des <strong>additions</strong> : H₂, Br₂ (décoloration de l'eau de brome), HCl, H₂O. <strong>Règle de Markovnikov</strong> : lors de l'addition de HX, H se fixe sur le carbone le plus hydrogéné.</div>"},{"t":"Polymérisation","verrou":true},{"t":"Acétylène","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"chimie","rang":4,"apc":{"module":"Chimie organique : hydrocarbures et composés oxygénés","famille":"Usage des produits pétroliers et des matières plastiques","agir":"Identifier et utiliser de façon sûre les composés organiques","situation":"Une entreprise de Douala doit produire 120 kg d'isolants en polyéthylène.","tache":"Écris l'équation de polymérisation et calcule la masse d'éthylène nécessaire."},"verrou":true,"nq":4,"labo":true});
VRT_L("1re-d-chimie-r05",{"duree":20,"titre":"Composés oxygénés : généralités","accroche":"Alcool, aldéhyde, cétone, acide.","intro":"Un groupe fonctionnel oxygéné donne à la molécule ses propriétés.","objectifs":["reconnaître les groupes fonctionnels","nommer les composés simples","trouver une formule brute"],"parties":[{"t":"Groupes fonctionnels","html":"<div class='def'><b>Définition</b>Un <strong>groupe fonctionnel</strong> est un groupe d'atomes responsable des propriétés : alcool (−OH), aldéhyde (−CHO), cétone (C=O entre deux carbones), acide carboxylique (−COOH), ester (−COO−).</div>"},{"t":"Nomenclature","verrou":true},{"t":"Formule brute","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"chimie","rang":5,"apc":{"module":"Chimie organique : hydrocarbures et composés oxygénés","famille":"Usage des produits pétroliers et des matières plastiques","agir":"Identifier et utiliser de façon sûre les composés organiques","situation":"Le vin de palme de la région de l'Ouest s'aigrit en quelques jours.","tache":"Nomme les composés oxygénés en jeu."},"verrou":true,"nq":4,"labo":true});
VRT_L("1re-d-chimie-r06",{"duree":20,"titre":"Propriétés physiques et tests des aldéhydes et cétones","accroche":"Un précipité, un miroir d'argent.","intro":"Des réactifs simples distinguent aldéhydes et cétones.","objectifs":["utiliser la DNPH","distinguer aldéhyde et cétone","expliquer les températures d'ébullition"],"parties":[{"t":"Tests","html":"<div class='def'><b>Définition</b>La <strong>DNPH</strong> donne un précipité jaune-orangé avec les aldéhydes et les cétones. Seuls les <strong>aldéhydes</strong> réduisent la liqueur de Fehling (précipité rouge brique), le réactif de Tollens (miroir d'argent) et rosissent le réactif de Schiff.</div>"},{"t":"Propriétés physiques","verrou":true},{"t":"Démarche","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"chimie","rang":6,"apc":{"module":"Chimie organique : hydrocarbures et composés oxygénés","famille":"Usage des produits pétroliers et des matières plastiques","agir":"Identifier et utiliser de façon sûre les composés organiques","situation":"Au laboratoire d'un lycée de Bafia, deux flacons sans étiquette contiennent l'un de l'éthanal, l'autre de la propanone.","tache":"Propose un test pour les identifier."},"verrou":true,"nq":4,"labo":true});
VRT_L("1re-d-chimie-r07",{"duree":20,"titre":"Les composés aromatiques : généralités","accroche":"Le benzène, un cycle très stable.","intro":"Les composés aromatiques contiennent le noyau benzénique.","objectifs":["décrire le benzène","expliquer la délocalisation","nommer des dérivés"],"parties":[{"t":"Le benzène","html":"<div class='def'><b>Définition</b>Le <strong>benzène</strong> C₆H₆ est un cycle plan de six carbones. Ses six électrons π sont <strong>délocalisés</strong> sur tout le cycle : toutes les liaisons C−C mesurent 140 pm.</div>"},{"t":"Dérivés","verrou":true},{"t":"Sécurité","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"chimie","rang":7,"apc":{"module":"Chimie organique : hydrocarbures et composés oxygénés","famille":"Usage des produits pétroliers et des matières plastiques","agir":"Identifier et utiliser de façon sûre les composés organiques","situation":"Un vendeur de carburant frelaté à Kousseri manipule l'essence sans gants ni masque.","tache":"Explique le danger."},"verrou":true,"nq":4,"labo":true});
VRT_L("1re-d-chimie-r08",{"duree":20,"titre":"Propriétés chimiques des composés aromatiques","accroche":"Substituer plutôt qu'additionner.","intro":"Le noyau benzénique donne surtout des substitutions, qui le conservent.","objectifs":["écrire une halogénation","écrire une nitration","écrire une addition"],"parties":[{"t":"Substitutions","html":"<div class='def'><b>Définition</b>Le benzène donne principalement des <strong>substitutions</strong> : halogénation (Cl₂ avec AlCl₃), nitration (HNO₃ avec H₂SO₄), alkylation de Friedel-Crafts.</div>"},{"t":"Additions","verrou":true},{"t":"Le TNT","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"chimie","rang":8,"apc":{"module":"Chimie organique : hydrocarbures et composés oxygénés","famille":"Usage des produits pétroliers et des matières plastiques","agir":"Identifier et utiliser de façon sûre les composés organiques","situation":"Une carrière de la région du Centre utilise des explosifs dérivés du toluène.","tache":"Écris la nitration du toluène et calcule la masse de TNT obtenue à partir de 250 g de toluène, avec 80 % de rendement."},"verrou":true,"nq":4,"labo":true});
VRT_L("1re-d-chimie-r09",{"duree":20,"titre":"Action des acides et des ions métalliques sur les métaux","accroche":"Un clou qui se couvre de cuivre.","intro":"Ces réactions mettent en jeu un transfert d'électrons : ce sont des oxydoréductions.","objectifs":["écrire l'action d'un acide sur un métal","écrire une réaction métal-ion","définir oxydant et réducteur"],"parties":[{"t":"Concepts clés","html":"<div class='def'><b>Définition</b>Un <strong>oxydant</strong> capte des électrons ; un <strong>réducteur</strong> en cède. L'<strong>oxydation</strong> est une perte d'électrons, la <strong>réduction</strong> un gain.</div>"},{"t":"Exemples","html":"<p>Zn + 2H₃O⁺ → Zn²⁺ + H₂ + 2H₂O. Un clou de fer dans une solution de sulfate de cuivre : Fe + Cu²⁺ → Fe²⁺ + Cu.</p>","labo":{"type":"calcul","f":"mole","vals":{"m":27,"M":27}}},{"t":"Calcul","html":"<p>2Al + 6H₃O⁺ → 2Al³⁺ + 3H₂ + 6H₂O. 27 g d'aluminium (1 mol) donnent 1,5 mol de H₂, soit 36 L si V_m = 24 L/mol.</p>","retenir":"Oxydation : perte d'électrons."},{"t":"Entraînement au format de l'examen","html":"<div class='integ'><h3>Partie A : évaluation des ressources</h3><p><strong>Vérification des savoirs.</strong> Un oxydant :</p><ol type='a'><li>cède des électrons</li><li>capte des électrons</li><li>ne réagit pas</li></ol><details><summary>Voir la réponse</summary><p><strong>capte des électrons</strong>. Définition.</p></details><p><strong>Application directe des savoirs.</strong></p><p>Dans Fe + Cu²⁺ → Fe²⁺ + Cu, qui est oxydé ?</p><details><summary>Voir la réponse</summary><p>(Réponse : le fer.)</p></details><h3>Partie B : évaluation des compétences</h3><p><strong>Situation.</strong> Un bijoutier de Foumban veut connaître la composition d'un laiton (cuivre et zinc). Il attaque 10 g d'alliage par un excès d'acide chlorhydrique et recueille 1,2 L de dihydrogène. M(Zn) = 65,4 g/mol ; V_m = 24 L/mol.</p><p><strong>Consigne 1.</strong> Écris l'équation de la réaction et indique quel métal réagit.</p><p><strong>Consigne 2.</strong> Calcule le pourcentage massique de zinc.</p><details><summary>Voir une réponse attendue</summary><p>Zn + 2H₃O⁺ → Zn²⁺ + H₂ + 2H₂O ; le cuivre ne réagit pas. n(H₂) = 0,05 mol = n(Zn), m = 3,27 g, soit 32,7 % de zinc.</p></details></div>","retenir":"Savoir-être mobilisé : Souci de la sécurité au laboratoire."}],"revision":["Oxydant, réducteur.","Oxydation, réduction.","Bilan."],"exo":"<p>Dans Fe + Cu²⁺ → Fe²⁺ + Cu, qui est oxydé ? <em>(Réponse : le fer.)</em></p>","quiz":[{"q":"Un oxydant :","r":["cède des électrons","capte des électrons","ne réagit pas"],"b":1,"e":"Définition."},{"q":"Le gaz dégagé par un acide sur le zinc est :","r":["le dihydrogène","le dioxygène","le chlore"],"b":0,"e":"Test : petite détonation."},{"q":"L'oxydation est :","r":["un gain d'électrons","un gain d'oxygène seulement","une perte d'électrons"],"b":2,"e":"Définition."},{"q":"27 g d'aluminium donnent un volume de H₂ de :","r":["24 L","36 L","12 L"],"b":1,"e":"1,5 × 24."}],"c":"1re D","m":"chimie","rang":9,"apc":{"module":"Oxydoréduction","famille":"Protection des métaux et production d'énergie","agir":"Prévenir la corrosion et exploiter les réactions d'oxydoréduction","situation":"Un chaudronnier de Garoua nettoie des copeaux d'aluminium de 27 g avec de l'acide chlorhydrique en excès.","tache":"Quel volume de gaz se dégage-t-il ?"},"gratuit":true});
VRT_L("1re-d-chimie-r10",{"duree":20,"titre":"Couples oxydant-réducteur","accroche":"Deux formes d'une même espèce.","intro":"Chaque oxydant est associé à un réducteur conjugué : ils forment un couple.","objectifs":["définir un couple","écrire une demi-équation","combiner deux demi-équations"],"parties":[{"t":"Définition","html":"<div class='def'><b>Définition</b>Un <strong>couple oxydant/réducteur</strong> est formé de deux espèces liées par la demi-équation <strong>Ox + ne⁻ ⇌ Red</strong>.</div>"},{"t":"Exemples","verrou":true},{"t":"Bilan","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"chimie","rang":10,"apc":{"module":"Oxydoréduction","famille":"Protection des métaux et production d'énergie","agir":"Prévenir la corrosion et exploiter les réactions d'oxydoréduction","situation":"Une bijoutière de Foumban dépose une fine couche d'argent sur un bijou en cuivre plongé dans une solution d'ions argent.","tache":"Écris les demi-équations et le bilan."},"verrou":true,"nq":4,"labo":true});
VRT_L("1re-d-chimie-r11",{"duree":20,"titre":"Classification électrochimique","accroche":"Prévoir qui réagit avec qui.","intro":"Classer les couples permet de prévoir les réactions spontanées.","objectifs":["classer des couples","appliquer la règle du gamma","prévoir l'action des acides"],"parties":[{"t":"La classification","html":"<div class='def'><b>Définition</b>On classe les couples selon leur potentiel standard E°. L'oxydant le plus fort réagit spontanément avec le réducteur le plus fort (<strong>règle du gamma</strong>).</div>"},{"t":"Ordre utile","verrou":true},{"t":"Prévisions","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"chimie","rang":11,"apc":{"module":"Oxydoréduction","famille":"Protection des métaux et production d'énergie","agir":"Prévenir la corrosion et exploiter les réactions d'oxydoréduction","situation":"Un menuisier de Kribi range ses clous en fer dans une boîte en cuivre humide.","tache":"Lequel des deux métaux sera attaqué ? Justifie."},"verrou":true,"nq":4,"labo":true});
VRT_L("1re-d-chimie-r12",{"duree":20,"titre":"La pile Daniell : description","accroche":"Une pile de laboratoire de 1,1 V.","intro":"La pile Daniell exploite la réaction entre le zinc et les ions cuivre, sans contact direct.","objectifs":["décrire la pile","écrire sa notation conventionnelle","indiquer les pôles"],"parties":[{"t":"Description","html":"<div class='def'><b>Définition</b>La <strong>pile Daniell</strong> comprend une lame de zinc dans une solution de Zn²⁺ et une lame de cuivre dans une solution de Cu²⁺, reliées par un <strong>pont salin</strong>.</div>"},{"t":"Fonctionnement","verrou":true},{"t":"Notation","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"chimie","rang":12,"apc":{"module":"Oxydoréduction","famille":"Protection des métaux et production d'énergie","agir":"Prévenir la corrosion et exploiter les réactions d'oxydoréduction","situation":"Au club scientifique d'un lycée de Bertoua, des élèves fabriquent une pile Daniell pour allumer une diode.","tache":"Décris le montage et indique les pôles."},"verrou":true,"nq":4,"labo":true});
VRT_L("1re-d-chimie-r13",{"duree":20,"titre":"Potentiels et force électromotrice d'une pile","accroche":"Calculer la tension à vide.","intro":"Les potentiels standards permettent de prévoir la force électromotrice d'une pile.","objectifs":["définir le potentiel standard","calculer une f.é.m.","identifier les pôles"],"parties":[{"t":"Potentiel standard","html":"<div class='def'><b>Définition</b>Le <strong>potentiel standard</strong> E° d'un couple est mesuré par rapport à l'électrode standard à hydrogène (E° = 0 V).</div>"},{"t":"Force électromotrice","verrou":true},{"t":"Pôles","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"chimie","rang":13,"apc":{"module":"Oxydoréduction","famille":"Protection des métaux et production d'énergie","agir":"Prévenir la corrosion et exploiter les réactions d'oxydoréduction","situation":"Un électricien de Ngaoundéré veut une pile de plus de 1 V avec des métaux de récupération : zinc, plomb, cuivre.","tache":"Quel couple de métaux choisir ?"},"verrou":true,"nq":4,"labo":true});
VRT_L("1re-d-chimie-r14",{"duree":20,"titre":"Couples autres que métal/ion métallique","accroche":"Permanganate, dichromate, iode.","intro":"Beaucoup d'oxydants et de réducteurs ne sont pas des métaux ; leurs demi-équations font intervenir l'eau et les ions H⁺.","objectifs":["équilibrer une demi-équation en milieu acide","citer des couples usuels","écrire un bilan"],"parties":[{"t":"Méthode","html":"<div class='def'><b>Définition</b>Pour équilibrer une demi-équation en milieu acide : équilibrer l'élément principal, puis O avec H₂O, puis H avec H⁺, puis les charges avec e⁻.</div>"},{"t":"Couples usuels","verrou":true},{"t":"Bilan","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"chimie","rang":14,"apc":{"module":"Oxydoréduction","famille":"Protection des métaux et production d'énergie","agir":"Prévenir la corrosion et exploiter les réactions d'oxydoréduction","situation":"Les éthylotests chimiques utilisés à Yaoundé virent de l'orange au vert en présence d'alcool.","tache":"Explique ce changement de couleur."},"verrou":true,"nq":4,"labo":true});
VRT_L("1re-d-chimie-r15",{"duree":20,"titre":"Dosages d'oxydoréduction","accroche":"Trouver une concentration inconnue.","intro":"Un dosage utilise une réaction rapide et totale ; l'équivalence se repère par un changement de couleur.","objectifs":["décrire le montage","écrire la relation à l'équivalence","calculer une concentration"],"parties":[{"t":"Équivalence","html":"<div class='def'><b>Définition</b>À l'<strong>équivalence</strong>, les réactifs ont été introduits dans les proportions stœchiométriques. Pour MnO₄⁻ + 5Fe²⁺ : n(Fe²⁺) = 5 × n(MnO₄⁻).</div>"},{"t":"Exemple","verrou":true},{"t":"Repérage","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"chimie","rang":15,"apc":{"module":"Oxydoréduction","famille":"Protection des métaux et production d'énergie","agir":"Prévenir la corrosion et exploiter les réactions d'oxydoréduction","situation":"Le club scientifique d'un lycée de l'Ouest dose l'alcool dans le sang d'un élève par le dichromate, selon le règlement intérieur qui fixe le seuil à 0,5 g/L.","tache":"Indique la démarche pour décider."},"verrou":true,"nq":4,"labo":true});
VRT_L("1re-d-chimie-r16",{"duree":20,"titre":"Électrolyse, corrosion et protection des métaux","accroche":"La rouille coûte cher.","intro":"L'électrolyse force une réaction ; la corrosion est une oxydation naturelle des métaux.","objectifs":["décrire une électrolyse","expliquer la corrosion du fer","choisir une protection"],"parties":[{"t":"Électrolyse","html":"<div class='def'><b>Définition</b>Une <strong>électrolyse</strong> est une réaction d'oxydoréduction forcée par un générateur. L'oxydation a lieu à l'anode (reliée au pôle +), la réduction à la cathode.</div>"},{"t":"Corrosion","verrou":true},{"t":"Protection","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"chimie","rang":16,"apc":{"module":"Oxydoréduction","famille":"Protection des métaux et production d'énergie","agir":"Prévenir la corrosion et exploiter les réactions d'oxydoréduction","situation":"Les tôles des maisons du quartier de Bonabéri, près de la mer, rouillent très vite.","tache":"Explique pourquoi et propose deux protections."},"verrou":true,"nq":4,"labo":true});
VRT_L("1re-d-chimie-r17",{"duree":20,"titre":"Le nombre d'oxydation","accroche":"Un compteur d'électrons.","intro":"Le nombre d'oxydation généralise les notions d'oxydation et de réduction, même sans ions.","objectifs":["appliquer les règles","calculer un nombre d'oxydation","repérer oxydation et réduction"],"parties":[{"t":"Règles","html":"<div class='def'><b>Définition</b>Le <strong>nombre d'oxydation</strong> (n.o.) vaut 0 pour un corps simple, la charge pour un ion monoatomique ; O vaut −2 (sauf peroxydes), H vaut +1 ; la somme des n.o. est égale à la charge de l'édifice.</div>"},{"t":"Exemples","html":"<p>Mn dans MnO₄⁻ : +7. Cr dans Cr₂O₇²⁻ : +6. S dans H₂SO₄ : +6.</p>","labo":{"type":"etapes","items":[["Charge","somme des n.o."],["Oxygène","−2 chacun."],["Hydrogène","+1 chacun."],["Inconnu","par différence."]]}},{"t":"Interprétation","html":"<p>Une oxydation est une augmentation du n.o. ; une réduction, une diminution.</p>","retenir":"Somme des n.o. = charge."},{"t":"Entraînement au format de l'examen","html":"<div class='integ'><h3>Partie A : évaluation des ressources</h3><p><strong>Vérification des savoirs.</strong> Le n.o. d'un corps simple vaut :</p><ol type='a'><li>1</li><li>0</li><li>sa masse</li></ol><details><summary>Voir la réponse</summary><p><strong>0</strong>. Règle.</p></details><p><strong>Application directe des savoirs.</strong></p><p>n.o. du carbone dans CO₂ ?</p><details><summary>Voir la réponse</summary><p>(Réponse : +4.)</p></details><h3>Partie B : évaluation des compétences</h3><p><strong>Situation.</strong> Dans l'industrie des engrais, l'ammoniac est oxydé : 4NH₃ + 5O₂ → 4NO + 6H₂O, puis NO devient NO₂ puis HNO₃.</p><p><strong>Consigne 1.</strong> Calcule le nombre d'oxydation de l'azote dans NH₃, NO, NO₂, HNO₃ et N₂.</p><p><strong>Consigne 2.</strong> Montre que la première réaction est une oxydoréduction en précisant l'oxydant et le réducteur.</p><details><summary>Voir une réponse attendue</summary><p>N : −3 (NH₃), +2 (NO), +4 (NO₂), +5 (HNO₃), 0 (N₂). L'azote passe de −3 à +2 (oxydé) ; l'oxygène de 0 à −2 (réduit) : O₂ est l'oxydant, NH₃ le réducteur.</p></details></div>","retenir":"Savoir-être mobilisé : Rigueur dans la démarche expérimentale."}],"revision":["Règles.","Calculs.","Augmentation : oxydation."],"exo":"<p>n.o. du carbone dans CO₂ ? <em>(Réponse : +4.)</em></p>","quiz":[{"q":"Le n.o. d'un corps simple vaut :","r":["1","0","sa masse"],"b":1,"e":"Règle."},{"q":"Le n.o. de Mn dans MnO₄⁻ est :","r":["+7","+2","−1"],"b":0,"e":"x − 8 = −1."},{"q":"« Le n.o. d'un élément dans un ion monoatomique est nul » est :","r":["vrai","vrai pour les métaux","faux"],"b":2,"e":"Il vaut la charge."},{"q":"Une oxydation correspond à :","r":["une diminution du n.o.","une augmentation du n.o.","aucun changement"],"b":1,"e":"Perte d'électrons."}],"c":"1re D","m":"chimie","rang":17,"apc":{"module":"Oxydoréduction","famille":"Protection des métaux et production d'énergie","agir":"Prévenir la corrosion et exploiter les réactions d'oxydoréduction","situation":"Un élève de Dschang hésite sur le n.o. du soufre dans l'acide des batteries, H₂SO₄.","tache":"Calcule-le."},"gratuit":true});
VRT_L("1re-d-chimie-r18",{"duree":20,"titre":"Utiliser le nombre d'oxydation","accroche":"Équilibrer sans ions.","intro":"Les n.o. permettent d'équilibrer des réactions en voie sèche, comme la métallurgie.","objectifs":["équilibrer avec les n.o.","étudier une réduction d'oxyde","décrire une métallurgie"],"parties":[{"t":"Méthode","html":"<div class='def'><b>Définition</b>La somme des augmentations de n.o. doit être égale à la somme des diminutions.</div>"},{"t":"Exemples","verrou":true},{"t":"Voie sèche","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"chimie","rang":18,"apc":{"module":"Oxydoréduction","famille":"Protection des métaux et production d'énergie","agir":"Prévenir la corrosion et exploiter les réactions d'oxydoréduction","situation":"Un exercice de Probatoire demande d'équilibrer CuO + NH₃ → Cu + H₂O + N₂.","tache":"Équilibre l'équation à l'aide des n.o."},"verrou":true,"nq":4,"labo":true});
VRT_L("1re-d-maths-r01",{"duree":20,"titre":"Équations et inéquations du second degré","accroche":"Un discriminant suffit à tout savoir.","intro":"Le trinôme ax² + bx + c revient à chaque Probatoire. Son discriminant indique le nombre de solutions, et son signe résout les inéquations.","objectifs":["calculer le discriminant","résoudre une équation du second degré","résoudre une inéquation du second degré"],"parties":[{"t":"Le discriminant","html":"<div class='def'><b>Définition</b>Pour ax² + bx + c = 0 (a ≠ 0), le <strong>discriminant</strong> est Δ = b² − 4ac. Si Δ > 0, il y a deux solutions x = (−b ± √Δ) / (2a) ; si Δ = 0, une solution −b / (2a) ; si Δ &lt; 0, aucune solution réelle.</div>"},{"t":"Le signe du trinôme","html":"<p>Le trinôme a le signe de a <strong>à l'extérieur</strong> des racines et le signe contraire entre elles. Sans racine, il garde le signe de a.</p><p class='formule'>x² − 5x + 6 &lt; 0 ⇔ x ∈ ]2 ; 3[</p>","retenir":"Signe de a à l'extérieur des racines.","labo":{"type":"parabole","a":1,"b":-5,"c":6}},{"t":"La forme canonique","html":"<p class='formule'>ax² + bx + c = a[(x + b/(2a))² − Δ/(4a²)]</p><p>Le Probatoire D l'utilise pour factoriser puis résoudre.</p>"},{"t":"Entraînement au format de l'examen","html":"<div class='integ'><h3>Partie A : évaluation des ressources</h3><p><strong>Question de cours.</strong> Le discriminant de x² − 5x + 6 vaut :</p><ol type='a'><li>25</li><li>1</li><li>−1</li></ol><details><summary>Voir la réponse</summary><p><strong>1</strong>. 25 − 24 = 1.</p></details><p><strong>Exercice.</strong></p><p>Résous 2x² + 3x − 2 = 0.</p><details><summary>Voir la réponse</summary><p>(Réponse : Δ = 25 ; x = 1/2 ou x = −2.)</p></details><h3>Partie B : évaluation des compétences</h3><p><strong>Situation.</strong> Un éleveur de Ngaoundéré veut clôturer un enclos rectangulaire avec 60 m de grillage ; l'enclos doit avoir une aire d'au moins 200 m².</p><p><strong>Tâche 1.</strong> Montre que la largeur x vérifie x² − 30x + 200 ≤ 0.</p><p><strong>Tâche 2.</strong> Résous l'inéquation et conclus.</p><details><summary>Voir une réponse attendue</summary><p>Longueur 30 − x ; x(30 − x) ≥ 200 ⇔ x² − 30x + 200 ≤ 0. Δ = 100, racines 10 et 20 : x ∈ [10 ; 20]. La largeur doit être comprise entre 10 m et 20 m.</p></details></div>","retenir":"Savoir-être mobilisé : Rigueur dans la rédaction."}],"revision":["Δ = b² − 4ac.","Solutions selon le signe de Δ.","Signe de a à l'extérieur des racines."],"exo":"<p>Résous 2x² + 3x − 2 = 0. <em>(Réponse : Δ = 25 ; x = 1/2 ou x = −2.)</em></p>","quiz":[{"q":"Le discriminant de x² − 5x + 6 vaut :","r":["25","1","−1"],"b":1,"e":"25 − 24 = 1."},{"q":"Si Δ &lt; 0, l'équation a :","r":["aucune solution réelle","une solution","deux solutions"],"b":0,"e":"Pas de racine réelle."},{"q":"−x² + x + 2 ≥ 0 a pour solution :","r":["]−∞ ; −1]","[2 ; +∞[","[−1 ; 2]"],"b":2,"e":"Racines −1 et 2, a &lt; 0 : positif entre les racines."},{"q":"Les racines de x² − 5x + 6 sont :","r":["1 et 6","2 et 3","−2 et −3"],"b":1,"e":"Produit 6, somme 5."}],"c":"1re D","m":"maths","rang":1,"apc":{"module":"Mathématiques de Première","famille":"Résolution de problèmes issus de la vie courante et des sciences","agir":"Modéliser et résoudre des situations de la vie économique et sociale","situation":"Une couturière de Bafoussam veut un tissu rectangulaire dont la longueur dépasse la largeur de 3 m, pour une aire de 40 m².","tache":"Détermine les dimensions du tissu."},"gratuit":true});
VRT_L("1re-d-maths-r02",{"duree":20,"titre":"Systèmes se ramenant au second degré","accroche":"Deux nombres dont on connaît la somme et le produit.","intro":"Certains systèmes non linéaires se résolvent grâce à une équation auxiliaire du second degré.","objectifs":["utiliser somme et produit","exploiter une substitution","vérifier les solutions"],"parties":[{"t":"Somme et produit","html":"<div class='def'><b>Définition</b>Si x + y = S et xy = P, alors x et y sont les solutions de <strong>X² − SX + P = 0</strong>, à condition que S² − 4P ≥ 0.</div>"},{"t":"Exemple","verrou":true},{"t":"Forme x² + y²","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"maths","rang":2,"apc":{"module":"Mathématiques de Première","famille":"Résolution de problèmes issus de la vie courante et des sciences","agir":"Modéliser et résoudre des situations de la vie économique et sociale","situation":"Un propriétaire de Limbé clôture une parcelle rectangulaire de 34 m de périmètre et de 60 m² d'aire.","tache":"Détermine la longueur et la largeur."},"verrou":true,"nq":4,"labo":true});
VRT_L("1re-d-maths-r03",{"duree":20,"titre":"Polynômes de degré 3 et factorisation","accroche":"Une racine évidente ouvre la voie.","intro":"Une racine connue d'un polynôme permet de le factoriser, puis de finir avec le second degré.","objectifs":["reconnaître une racine","factoriser par x − a","résoudre une équation de degré 3"],"parties":[{"t":"Racine et factorisation","html":"<div class='def'><b>Définition</b>Le réel a est une <strong>racine</strong> de P si P(a) = 0. Alors P(x) se factorise par (x − a) : P(x) = (x − a)Q(x).</div>"},{"t":"Identification","verrou":true},{"t":"Résolution","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"maths","rang":3,"apc":{"module":"Mathématiques de Première","famille":"Résolution de problèmes issus de la vie courante et des sciences","agir":"Modéliser et résoudre des situations de la vie économique et sociale","situation":"Un fabricant de boîtes à Douala modélise le volume d'une boîte par V(x) = x³ − 6x² + 11x − 6 et cherche les valeurs où ce volume s'annule.","tache":"Trouve ces valeurs."},"verrou":true,"nq":4,"labo":true});
VRT_L("1re-d-maths-r04",{"duree":20,"titre":"Signe d'un polynôme de degré 3","accroche":"Le tableau de signes fait tout le travail.","intro":"Une fois factorisé, un polynôme de degré 3 se lit dans un tableau de signes.","objectifs":["factoriser","dresser un tableau de signes","résoudre une inéquation"],"parties":[{"t":"La méthode","html":"<div class='def'><b>Définition</b>Pour étudier le <strong>signe</strong> d'un polynôme, on le factorise en facteurs du premier ou second degré, puis on dresse un tableau de signes.</div>"},{"t":"Exemple","verrou":true},{"t":"Inéquation","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"maths","rang":4,"apc":{"module":"Mathématiques de Première","famille":"Résolution de problèmes issus de la vie courante et des sciences","agir":"Modéliser et résoudre des situations de la vie économique et sociale","situation":"Le bénéfice d'une petite unité de Kribi est modélisé par B(x) = x(x − 2)(x + 2), pour x exprimé en centaines d'articles, x positif.","tache":"Détermine les quantités qui donnent un bénéfice positif."},"verrou":true,"nq":4,"labo":true});
VRT_L("1re-d-maths-r05",{"duree":20,"titre":"Équations irrationnelles","accroche":"On élève au carré, puis on trie.","intro":"Une équation avec racine carrée se résout en respectant une condition essentielle.","objectifs":["déterminer les conditions","résoudre","vérifier les solutions"],"parties":[{"t":"Le principe","html":"<div class='def'><b>Définition</b>Une équation <strong>irrationnelle</strong> contient l'inconnue sous un radical. <strong>√A = B ⇔ B ≥ 0 et A = B²</strong>.</div>"},{"t":"Exemple","verrou":true},{"t":"Vérification","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"maths","rang":5,"apc":{"module":"Mathématiques de Première","famille":"Résolution de problèmes issus de la vie courante et des sciences","agir":"Modéliser et résoudre des situations de la vie économique et sociale","situation":"Pour une rampe à Kumba, la longueur en mètres vérifie √(2x + 3) = x.","tache":"Détermine la valeur de x et justifie."},"verrou":true,"nq":4,"labo":true});
VRT_L("1re-d-maths-r06",{"duree":20,"titre":"Inéquations irrationnelles","accroche":"Deux schémas à connaître.","intro":"Selon le sens de l'inégalité, on utilise des conditions différentes.","objectifs":["utiliser les équivalences","résoudre","présenter sur un axe"],"parties":[{"t":"Les équivalences","html":"<div class='def'><b>Définition</b><strong>√A &lt; B ⇔ A ≥ 0, B > 0 et A &lt; B²</strong>. Pour √A > B : ou bien B &lt; 0 et A ≥ 0, ou bien B ≥ 0 et A > B².</div>"},{"t":"Exemple","verrou":true},{"t":"Rédaction","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"maths","rang":6,"apc":{"module":"Mathématiques de Première","famille":"Résolution de problèmes issus de la vie courante et des sciences","agir":"Modéliser et résoudre des situations de la vie économique et sociale","situation":"La vitesse d'un jet d'eau à Mbalmayo vérifie √(x + 2) &lt; x, avec x en dizaines de cm.","tache":"Détermine les valeurs de x possibles."},"verrou":true,"nq":4,"labo":true});
VRT_L("1re-d-maths-r07",{"duree":20,"titre":"Systèmes linéaires à deux inconnues","accroche":"Deux droites, un point.","intro":"Résoudre un système, c'est chercher le point commun de deux droites.","objectifs":["résoudre par substitution","utiliser le déterminant","interpréter"],"parties":[{"t":"Le système","html":"<div class='def'><b>Définition</b>Le système ax + by = c ; a'x + b'y = c' a pour <strong>déterminant</strong> D = ab' − a'b. Si D ≠ 0, il a une solution unique.</div>"},{"t":"La méthode de Cramer","verrou":true},{"t":"Interprétation","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"maths","rang":7,"apc":{"module":"Mathématiques de Première","famille":"Résolution de problèmes issus de la vie courante et des sciences","agir":"Modéliser et résoudre des situations de la vie économique et sociale","situation":"Au marché de Foumbot, 2 tas de tomates et 3 tas de piment coûtent 1 200 F ; un tas de tomates coûte 100 F de plus qu'un tas de piment.","tache":"Trouve le prix de chaque tas."},"verrou":true,"nq":4,"labo":true});
VRT_L("1re-d-maths-r08",{"duree":20,"titre":"Systèmes linéaires à trois inconnues","accroche":"Pivot de Gauss : une inconnue à la fois.","intro":"La méthode du pivot triangularise le système. Ce type de système revient très souvent au Probatoire.","objectifs":["appliquer le pivot","remonter les inconnues","vérifier"],"parties":[{"t":"La méthode","html":"<div class='def'><b>Définition</b>Le <strong>pivot de Gauss</strong> remplace les lignes par des combinaisons pour obtenir un système triangulaire équivalent.</div>"},{"t":"Exemple","verrou":true},{"t":"Modéliser","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"maths","rang":8,"apc":{"module":"Mathématiques de Première","famille":"Résolution de problèmes issus de la vie courante et des sciences","agir":"Modéliser et résoudre des situations de la vie économique et sociale","situation":"Un fermier de Foumban achète à crédit des bêtes. 10 poussins, 2 pourceaux et 1 chevreau coûtent 45 000 F ; 20 poussins, 1 pourceau et 2 chevreaux coûtent 45 000 F ; 30 poussins, 2 pourceaux et 2 chevreaux coûtent 65 000 F.","tache":"Détermine le prix unitaire de chaque espèce."},"verrou":true,"nq":4,"labo":true});
VRT_L("1re-d-maths-r09",{"duree":20,"titre":"Formules de transformation","accroche":"Transformer un produit, simplifier une somme.","intro":"Les formules d'addition et de duplication simplifient les expressions trigonométriques.","objectifs":["utiliser les formules d'addition","utiliser la duplication","écrire a cos x + b sin x"],"parties":[{"t":"Addition","html":"<div class='def'><b>Définition</b><strong>cos(a + b) = cos a cos b − sin a sin b</strong> ; <strong>sin(a + b) = sin a cos b + cos a sin b</strong>.</div>"},{"t":"Duplication","verrou":true},{"t":"Forme R cos(x − φ)","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"maths","rang":9,"apc":{"module":"Mathématiques de Première","famille":"Résolution de problèmes issus de la vie courante et des sciences","agir":"Modéliser et résoudre des situations de la vie économique et sociale","situation":"Un élève de Dschang étudie une tension alternative de la forme √3 cos t + sin t.","tache":"Écris-la sous la forme R cos(t − φ)."},"verrou":true,"nq":4,"labo":true});
VRT_L("1re-d-maths-r10",{"duree":20,"titre":"Équations et inéquations trigonométriques","accroche":"Deux familles de solutions.","intro":"Il faut savoir traduire une équation par une égalité d'angles, puis choisir les solutions dans l'intervalle.","objectifs":["résoudre cos x = cos a","résoudre sin x = sin a","résoudre une inéquation sur un intervalle"],"parties":[{"t":"Les équations de base","html":"<div class='def'><b>Définition</b><strong>cos x = cos a ⇔ x = a + 2kπ ou x = −a + 2kπ</strong>. <strong>sin x = sin a ⇔ x = a + 2kπ ou x = π − a + 2kπ</strong>, k entier.</div>"},{"t":"Exemple","verrou":true},{"t":"Se ramener au second degré","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"maths","rang":10,"apc":{"module":"Mathématiques de Première","famille":"Résolution de problèmes issus de la vie courante et des sciences","agir":"Modéliser et résoudre des situations de la vie économique et sociale","situation":"Un technicien de Song Loulou cherche sur [0 ; 2π[ les instants où une tension vérifie 2 cos t − 1 = 0.","tache":"Détermine les solutions."},"verrou":true,"nq":4,"labo":true});
VRT_L("1re-d-maths-r11",{"duree":20,"titre":"Premiers outils du dénombrement","accroche":"Compter sans tout écrire.","intro":"Deux principes simples, somme et produit, résolvent la plupart des comptages.","objectifs":["utiliser le principe additif","utiliser le principe multiplicatif","utiliser la factorielle"],"parties":[{"t":"Les principes","html":"<div class='def'><b>Définition</b><strong>Principe additif</strong> : on additionne si les cas s'excluent. <strong>Principe multiplicatif</strong> : on multiplie pour des choix successifs.</div>"},{"t":"Réunion","verrou":true},{"t":"Factorielle","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"maths","rang":11,"apc":{"module":"Mathématiques de Première","famille":"Résolution de problèmes issus de la vie courante et des sciences","agir":"Modéliser et résoudre des situations de la vie économique et sociale","situation":"Une école de Garoua propose 3 entrées et 4 plats au déjeuner du samedi.","tache":"Détermine le nombre de menus possibles."},"verrou":true,"nq":4,"labo":true});
VRT_L("1re-d-maths-r13",{"duree":20,"titre":"p-listes, arrangements et combinaisons","accroche":"L'ordre compte-t-il ? Peut-on répéter ?","intro":"Deux questions suffisent à choisir la bonne formule.","objectifs":["reconnaître chaque situation","appliquer les formules","résoudre un tirage"],"parties":[{"t":"Les trois formules","html":"<div class='def'><b>Définition</b>Choisir p éléments parmi n : <strong>p-liste</strong> nᵖ (ordre, répétition) ; <strong>arrangement</strong> n!/(n − p)! (ordre, sans répétition) ; <strong>combinaison</strong> n!/[p!(n − p)!] (sans ordre, sans répétition).</div>"},{"t":"Exemples","verrou":true},{"t":"Au Probatoire","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"maths","rang":13,"apc":{"module":"Mathématiques de Première","famille":"Résolution de problèmes issus de la vie courante et des sciences","agir":"Modéliser et résoudre des situations de la vie économique et sociale","situation":"Une PME de Douala choisit 6 responsables parmi 10 candidats, et prévoit une enveloppe à 100 F par groupe possible, pour un budget de 12 500 F.","tache":"Le budget suffit-il ?"},"verrou":true,"nq":4,"labo":true});
VRT_L("1re-d-maths-r12",{"duree":20,"titre":"Intégration : compter pour décider","accroche":"Tirage et budget d'un concours.","intro":"Le dénombrement sert à estimer le coût d'une organisation.","objectifs":["identifier le type de tirage","calculer","décider"],"parties":[{"t":"Modèle","html":"<div class='def'><b>Définition</b>Une situation de <strong>choix simultané</strong> relève des combinaisons ; un choix ordonné relève des arrangements.</div>"},{"t":"Démarche","verrou":true},{"t":"Conclusion","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"maths","rang":12,"apc":{"module":"Mathématiques de Première","famille":"Résolution de problèmes issus de la vie courante et des sciences","agir":"Modéliser et résoudre des situations de la vie économique et sociale","situation":"Le foyer d'un lycée de Mbouda organise un tirage : un jeu de 2 billets à gratter parmi 12, à 50 F par tirage possible.","tache":"Calcule le budget nécessaire pour imprimer un billet par tirage possible."},"verrou":true,"nq":4,"labo":true});
VRT_L("1re-d-maths-r14",{"duree":20,"titre":"Le barycentre","accroche":"Le point d'équilibre d'un système de points pondérés.","intro":"Le barycentre généralise le milieu : il tient compte du poids de chaque point.","objectifs":["définir le barycentre","le construire","utiliser la réduction vectorielle"],"parties":[{"t":"Définition","html":"<div class='def'><b>Définition</b>Si a + b ≠ 0, le <strong>barycentre</strong> G de (A ; a) et (B ; b) est l'unique point tel que a·GA⃗ + b·GB⃗ = 0⃗. Alors AG⃗ = b/(a + b) · AB⃗.</div>"},{"t":"Réduction","verrou":true},{"t":"Associativité","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"maths","rang":14,"apc":{"module":"Mathématiques de Première","famille":"Résolution de problèmes issus de la vie courante et des sciences","agir":"Modéliser et résoudre des situations de la vie économique et sociale","situation":"Un porteur de Bafang transporte deux seaux de 10 kg et 30 kg aux extrémités d'un bâton de 2 m.","tache":"Où doit-il placer l'épaule pour l'équilibre ?"},"verrou":true,"nq":4,"labo":true});
VRT_L("1re-d-maths-r15",{"duree":20,"titre":"Lignes de niveau","accroche":"Un ensemble de points défini par une égalité.","intro":"Les fonctions vectorielles du barycentre permettent de reconnaître des droites et des cercles.","objectifs":["réduire une somme vectorielle","reconnaître un cercle","reconnaître une droite"],"parties":[{"t":"Définition","html":"<div class='def'><b>Définition</b>Une <strong>ligne de niveau</strong> k d'une fonction f du plan est l'ensemble des points M tels que f(M) = k.</div>"},{"t":"Les cas classiques","verrou":true},{"t":"Méthode","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"maths","rang":15,"apc":{"module":"Mathématiques de Première","famille":"Résolution de problèmes issus de la vie courante et des sciences","agir":"Modéliser et résoudre des situations de la vie économique et sociale","situation":"Pour un forage, l'ingénieur de Mbalmayo cherche les points M tels que MA² + MB² = 24 m², avec AB = 4 m.","tache":"Décris cet ensemble."},"verrou":true,"nq":4,"labo":true});
VRT_L("1re-d-maths-r16",{"duree":20,"titre":"Notion de fonctions et d'applications","accroche":"Une machine qui associe au plus un résultat.","intro":"Avant d'étudier une fonction, il faut connaître son ensemble de définition.","objectifs":["déterminer un ensemble de définition","distinguer fonction et application","composer des fonctions"],"parties":[{"t":"Définitions","html":"<div class='def'><b>Définition</b>Une <strong>fonction</strong> associe à chaque élément de E au plus une image dans F. Une <strong>application</strong> associe à chaque élément de E exactement une image.</div>"},{"t":"Ensemble de définition","verrou":true},{"t":"Composée","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"maths","rang":16,"apc":{"module":"Mathématiques de Première","famille":"Résolution de problèmes issus de la vie courante et des sciences","agir":"Modéliser et résoudre des situations de la vie économique et sociale","situation":"Le prix au kilo d'une denrée à Bafoussam est modélisé par p(x) = 1 200/(x − 2), où x est le jour du mois.","tache":"Pour quels jours la formule a-t-elle un sens ?"},"verrou":true,"nq":4,"labo":true});
VRT_L("1re-d-maths-r19",{"duree":20,"titre":"Fonctions et applications : entraînement","accroche":"Un ensemble de définition piège.","intro":"Cette séance d'entraînement reprend la notion avec un exercice du niveau du Probatoire.","objectifs":["reconnaître le type d'exercice","rédiger la méthode","éviter le piège classique"],"parties":[{"t":"Le rappel","html":"<div class='def'><b>À retenir</b>Il faut réunir toutes les conditions : dénominateur, radical, et éventuel quotient sous radical.</div>"},{"t":"Exercice résolu","verrou":true},{"t":"Le piège à éviter","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"maths","rang":19,"apc":{"module":"Mathématiques de Première","famille":"Résolution de problèmes issus de la vie courante et des sciences","agir":"Modéliser et résoudre des situations de la vie économique et sociale","situation":"Un tarif de taxi à Douala est f(x) = √(x² − 4) × 100 F, x étant la distance en km.","tache":"Indique les distances acceptées par la formule."},"verrou":true,"nq":4,"labo":true});
VRT_L("1re-d-maths-r17",{"duree":20,"titre":"Symétries et translations des courbes","accroche":"Construire une courbe à partir d'une autre.","intro":"Repérer une symétrie réduit l'étude d'une fonction ; une translation donne une courbe nouvelle à partir d'une courbe connue.","objectifs":["prouver un axe de symétrie","prouver un centre de symétrie","utiliser une translation"],"parties":[{"t":"Éléments de symétrie","html":"<div class='def'><b>Définition</b>La droite x = a est un <strong>axe de symétrie</strong> si f(2a − x) = f(x). Le point I(a ; b) est un <strong>centre de symétrie</strong> si f(2a − x) + f(x) = 2b.</div>"},{"t":"Translations","verrou":true},{"t":"Courbes associées","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"maths","rang":17,"apc":{"module":"Mathématiques de Première","famille":"Résolution de problèmes issus de la vie courante et des sciences","agir":"Modéliser et résoudre des situations de la vie économique et sociale","situation":"Un artisan de Foumban dessine une calebasse dont le profil suit y = x² − 4x + 1.","tache":"Indique l'axe de symétrie du profil."},"verrou":true,"nq":4,"labo":true});
VRT_L("1re-d-maths-r20",{"duree":20,"titre":"Symétries des courbes : entraînement","accroche":"Démontrer un centre de symétrie.","intro":"Cette séance d'entraînement reprend la notion avec un exercice du niveau du Probatoire.","objectifs":["reconnaître le type d'exercice","rédiger la méthode","éviter le piège classique"],"parties":[{"t":"Le rappel","html":"<div class='def'><b>À retenir</b>Pour un centre, on calcule f(2a − x) + f(x).</div>"},{"t":"Exercice résolu","verrou":true},{"t":"Le piège à éviter","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"maths","rang":20,"apc":{"module":"Mathématiques de Première","famille":"Résolution de problèmes issus de la vie courante et des sciences","agir":"Modéliser et résoudre des situations de la vie économique et sociale","situation":"Au Probatoire C, on demande la courbe de g(x) = f(|x|) à partir de celle de f.","tache":"Explique la construction."},"verrou":true,"nq":4,"labo":true});
VRT_L("1re-d-maths-r21",{"duree":20,"titre":"Limites et asymptotes","accroche":"Ce qui se passe au bout de la courbe.","intro":"Les limites décrivent le comportement d'une fonction aux bornes de son domaine et donnent les asymptotes.","objectifs":["calculer des limites usuelles","lever une indétermination","reconnaître une asymptote"],"parties":[{"t":"Les asymptotes","html":"<div class='def'><b>Définition</b>Si lim f(x) = ±∞ quand x tend vers a, la droite x = a est <strong>asymptote verticale</strong>. Si lim f(x) = b en ±∞, la droite y = b est <strong>asymptote horizontale</strong>.</div>"},{"t":"Fonctions rationnelles","verrou":true},{"t":"Indéterminations","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"maths","rang":21,"apc":{"module":"Mathématiques de Première","famille":"Résolution de problèmes issus de la vie courante et des sciences","agir":"Modéliser et résoudre des situations de la vie économique et sociale","situation":"Le coût moyen de production d'un savonnier de Bafoussam est C(x) = (2x + 600)/x pour x pains.","tache":"Que devient ce coût pour de très grandes quantités ?"},"verrou":true,"nq":4,"labo":true});
VRT_L("1re-d-maths-r22",{"duree":20,"titre":"Continuité","accroche":"Une courbe tracée sans lever le crayon.","intro":"La continuité garantit l'existence de solutions pour certaines équations.","objectifs":["définir la continuité en un point","reconnaître les fonctions continues","utiliser le théorème des valeurs intermédiaires"],"parties":[{"t":"Définition","html":"<div class='def'><b>Définition</b>f est <strong>continue en a</strong> si lim f(x) = f(a) quand x tend vers a.</div>"},{"t":"Fonctions continues","verrou":true},{"t":"Valeurs intermédiaires","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"maths","rang":22,"apc":{"module":"Mathématiques de Première","famille":"Résolution de problèmes issus de la vie courante et des sciences","agir":"Modéliser et résoudre des situations de la vie économique et sociale","situation":"Un réservoir à Ngaoundéré se remplit selon une fonction continue ; il contient 200 L à 8 h et 1 000 L à 10 h.","tache":"Le volume a-t-il atteint 600 L entre 8 h et 10 h ?"},"verrou":true,"nq":4,"labo":true});
VRT_L("1re-d-maths-r23",{"duree":20,"titre":"Nombre dérivé et fonction dérivée","accroche":"La pente d'une courbe en un point.","intro":"Le nombre dérivé mesure la vitesse de variation et donne l'équation de la tangente.","objectifs":["définir le nombre dérivé","écrire une tangente","calculer des dérivées"],"parties":[{"t":"Le nombre dérivé","html":"<div class='def'><b>Définition</b>f est dérivable en a si (f(a + h) − f(a))/h a une limite finie quand h tend vers 0 ; cette limite est le <strong>nombre dérivé</strong> f'(a).</div>"},{"t":"La tangente","verrou":true},{"t":"Dérivées usuelles","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"maths","rang":23,"apc":{"module":"Mathématiques de Première","famille":"Résolution de problèmes issus de la vie courante et des sciences","agir":"Modéliser et résoudre des situations de la vie économique et sociale","situation":"Le trajet d'une moto-taxi à Douala est modélisé par d(t) = t², en km, t en heures.","tache":"Quelle est la vitesse instantanée à t = 1 h ?"},"verrou":true,"nq":4,"labo":true});
VRT_L("1re-d-maths-r24",{"duree":20,"titre":"Utiliser la fonction dérivée","accroche":"Le signe de f' donne les variations.","intro":"La dérivée permet d'étudier les variations et de trouver un maximum ou un minimum.","objectifs":["relier signe de f' et variations","dresser un tableau de variation","résoudre un problème d'optimisation"],"parties":[{"t":"Le théorème","html":"<div class='def'><b>Définition</b>Si f' > 0 sur un intervalle, f y est <strong>strictement croissante</strong> ; si f' &lt; 0, f y est <strong>strictement décroissante</strong>.</div>"},{"t":"Exemple","html":"<p>f(x) = x³ − 3x, f'(x) = 3(x − 1)(x + 1). f croît sur ]−∞ ; −1], décroît sur [−1 ; 1], croît sur [1 ; +∞[. Maximum local f(−1) = 2, minimum local f(1) = −2.</p>","labo":{"type":"courbe","fn":"x3","xmin":-2,"xmax":2,"ymin":-8,"ymax":8,"x0":1}},{"t":"Optimisation","html":"<p>Clôture de 100 m le long d'un mur : A(x) = x(100 − 2x), A'(x) = 100 − 4x. Maximum pour x = 25 : A = 1 250 m².</p>","retenir":"Un extremum se lit là où f' s'annule en changeant de signe."},{"t":"Entraînement au format de l'examen","html":"<div class='integ'><h3>Partie A : évaluation des ressources</h3><p><strong>Question de cours.</strong> Si f' &gt; 0, f est :</p><ol type='a'><li>décroissante</li><li>croissante</li><li>constante</li></ol><details><summary>Voir la réponse</summary><p><strong>croissante</strong>. Théorème.</p></details><p><strong>Exercice.</strong></p><p>Quel est le maximum de f(x) = −x² + 4x ?</p><details><summary>Voir la réponse</summary><p>(Réponse : 4, pour x = 2.)</p></details><h3>Partie B : évaluation des compétences</h3><p><strong>Situation.</strong> Un menuisier de Bertoua découpe un carré de côté x aux quatre coins d'une plaque de 30 cm sur 30 cm pour fabriquer une boîte sans couvercle. Le volume est V(x) = x(30 − 2x)², x ∈ ]0 ; 15[.</p><p><strong>Tâche 1.</strong> Calcule V'(x) et étudie son signe.</p><p><strong>Tâche 2.</strong> Pour quelle valeur de x le volume est-il maximal ? Calcule-le.</p><details><summary>Voir une réponse attendue</summary><p>V'(x) = (30 − 2x)(30 − 6x), positif sur ]0 ; 5[, négatif sur ]5 ; 15[. Maximum en x = 5 cm : V = 5 × 20² = 2 000 cm³.</p></details></div>","retenir":"Savoir-être mobilisé : Persévérance dans la recherche."}],"revision":["Signe de f'.","Tableau de variation.","Extremum."],"exo":"<p>Quel est le maximum de f(x) = −x² + 4x ? <em>(Réponse : 4, pour x = 2.)</em></p>","quiz":[{"q":"Si f' > 0, f est :","r":["décroissante","croissante","constante"],"b":1,"e":"Théorème."},{"q":"Un extremum se trouve où :","r":["f' s'annule en changeant de signe","f vaut 0","x vaut 0"],"b":0,"e":"Condition."},{"q":"Pour A(x) = x(100 − 2x), le maximum est atteint en :","r":["50","20","25"],"b":2,"e":"A'(x) = 0."},{"q":"f(x) = x³ − 3x a un maximum local en :","r":["1","−1","0"],"b":1,"e":"f' change de signe de + à −."}],"c":"1re D","m":"maths","rang":24,"apc":{"module":"Mathématiques de Première","famille":"Résolution de problèmes issus de la vie courante et des sciences","agir":"Modéliser et résoudre des situations de la vie économique et sociale","situation":"Ben, à Edéa, dispose de 100 m de grillage pour clore une parcelle rectangulaire adossée à un mur.","tache":"Détermine la plus grande superficie possible."},"gratuit":true});
VRT_L("1re-d-maths-r26",{"duree":20,"titre":"Utiliser la dérivée : entraînement","accroche":"Le nombre de solutions d'une équation.","intro":"Cette séance d'entraînement reprend la notion avec un exercice du niveau du Probatoire.","objectifs":["reconnaître le type d'exercice","rédiger la méthode","éviter le piège classique"],"parties":[{"t":"Le rappel","html":"<div class='def'><b>À retenir</b>Le tableau de variation et les valeurs extrêmes donnent le nombre de solutions de f(x) = 0.</div>"},{"t":"Exercice résolu","verrou":true},{"t":"Le piège à éviter","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"maths","rang":26,"apc":{"module":"Mathématiques de Première","famille":"Résolution de problèmes issus de la vie courante et des sciences","agir":"Modéliser et résoudre des situations de la vie économique et sociale","situation":"Le profit d'une coopérative de Bertoua suit f(x) = x³ − 3x² + 1, pour une production x.","tache":"Combien de fois le profit s'annule-t-il ?"},"verrou":true,"nq":4,"labo":true});
VRT_L("1re-d-maths-r25",{"duree":20,"titre":"Intégration : bénéfice d'une PME","accroche":"Produire assez pour gagner.","intro":"Le Probatoire C 2022 étudiait le bénéfice d'une PME : coût, recette, seuil de rentabilité.","objectifs":["écrire le bénéfice","résoudre B(x) > 0","conclure avec la capacité"],"parties":[{"t":"Le modèle","html":"<div class='def'><b>Définition</b>Le <strong>bénéfice</strong> est B(x) = R(x) − C(x), recette moins coût.</div>"},{"t":"Exemple","verrou":true},{"t":"Conclusion","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"maths","rang":25,"apc":{"module":"Mathématiques de Première","famille":"Résolution de problèmes issus de la vie courante et des sciences","agir":"Modéliser et résoudre des situations de la vie économique et sociale","situation":"Des jeunes de Yaoundé montent une PME : coût C(x) = x² + 202 500 F, prix de vente 1 500 F l'unité, capacité 1 300.","tache":"Quel est le nombre minimal d'articles pour un bénéfice ?"},"verrou":true,"nq":4,"labo":true});
VRT_L("1re-d-maths-r32",{"duree":20,"titre":"Représentation des fonctions polynômes","accroche":"Du tableau de variation à la courbe.","intro":"L'étude complète d'un polynôme suit un plan fixe.","objectifs":["suivre le plan d'étude","placer les points remarquables","tracer la courbe"],"parties":[{"t":"Le plan d'étude","html":"<div class='def'><b>Définition</b>Étudier une fonction, c'est donner son <strong>ensemble de définition</strong>, ses <strong>limites</strong>, sa <strong>dérivée</strong>, son <strong>tableau de variation</strong>, puis tracer sa courbe.</div>"},{"t":"Exemple","verrou":true},{"t":"Le tracé","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"maths","rang":32,"apc":{"module":"Mathématiques de Première","famille":"Résolution de problèmes issus de la vie courante et des sciences","agir":"Modéliser et résoudre des situations de la vie économique et sociale","situation":"Un ingénieur de Kribi trace le profil d'une dune avec y = x³ − 3x + 1, entre −2 et 2.","tache":"Donne les hauteurs extrêmes."},"verrou":true,"nq":4,"labo":true});
VRT_L("1re-d-maths-r33",{"duree":20,"titre":"Représentation des fonctions rationnelles","accroche":"Asymptotes et centre de symétrie.","intro":"Les fonctions rationnelles simples ont des asymptotes qui guident le tracé.","objectifs":["étudier une homographique","étudier x + 1/x","tracer avec les asymptotes"],"parties":[{"t":"Homographique","html":"<div class='def'><b>Définition</b>Pour f(x) = (ax + b)/(cx + d), la droite x = −d/c est <strong>asymptote verticale</strong> et la droite y = a/c est <strong>asymptote horizontale</strong>. Leur intersection est centre de symétrie.</div>"},{"t":"Exemple","verrou":true},{"t":"Asymptote oblique","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"maths","rang":33,"apc":{"module":"Mathématiques de Première","famille":"Résolution de problèmes issus de la vie courante et des sciences","agir":"Modéliser et résoudre des situations de la vie économique et sociale","situation":"Le rendement d'un champ de maïs à Bafia est modélisé par f(x) = (x + 1)/(x − 1) pour x > 1.","tache":"Décris l'évolution du rendement."},"verrou":true,"nq":4,"labo":true});
VRT_L("1re-d-maths-r35",{"duree":20,"titre":"Fonctions rationnelles : entraînement","accroche":"Une division pour faire apparaître l'asymptote.","intro":"Cette séance d'entraînement reprend la notion avec un exercice du niveau du Probatoire.","objectifs":["reconnaître le type d'exercice","rédiger la méthode","éviter le piège classique"],"parties":[{"t":"Le rappel","html":"<div class='def'><b>À retenir</b>Écrire f(x) = ax + b + c/(x − d) montre l'asymptote oblique y = ax + b.</div>"},{"t":"Exercice résolu","verrou":true},{"t":"Le piège à éviter","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"maths","rang":35,"apc":{"module":"Mathématiques de Première","famille":"Résolution de problèmes issus de la vie courante et des sciences","agir":"Modéliser et résoudre des situations de la vie économique et sociale","situation":"Au Probatoire D-TI, on admet f(x) = ax + b + c/(x + 1) et on connaît trois valeurs de f.","tache":"Explique comment trouver a, b et c."},"verrou":true,"nq":4,"labo":true});
VRT_L("1re-d-maths-r34",{"duree":20,"titre":"Intégration : lire une courbe","accroche":"Un sujet de Probatoire entièrement graphique.","intro":"Le Probatoire donne souvent la courbe d'une fonction et demande de la lire avant de retrouver son expression.","objectifs":["lire domaine et limites","lire les asymptotes","retrouver une expression"],"parties":[{"t":"Lecture","html":"<div class='def'><b>Définition</b>Lire une courbe, c'est en tirer le <strong>domaine</strong>, les <strong>limites</strong>, les <strong>asymptotes</strong>, le signe de f et de f'.</div>"},{"t":"Retrouver f","verrou":true},{"t":"Courbes associées","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"maths","rang":34,"apc":{"module":"Mathématiques de Première","famille":"Résolution de problèmes issus de la vie courante et des sciences","agir":"Modéliser et résoudre des situations de la vie économique et sociale","situation":"Au Probatoire C 2026 blanc, la courbe d'une fonction f(x) = (ax² + bx + c)/(x − 1) est donnée.","tache":"Décris la démarche pour répondre au sujet."},"verrou":true,"nq":4,"labo":true});
VRT_L("1re-d-maths-r18",{"duree":20,"titre":"Intégration : équilibre et fonctions","accroche":"Le barycentre au service du portage.","intro":"Ce problème relie barycentre et étude de fonction, comme dans les sujets de Probatoire.","objectifs":["modéliser un équilibre","utiliser une fonction","conclure"],"parties":[{"t":"Modèle","html":"<div class='def'><b>Définition</b>Le point d'équilibre d'un système de charges est le <strong>barycentre</strong> des positions pondérées par les masses.</div>"},{"t":"Fonction de la masse","verrou":true},{"t":"Conclusion","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"maths","rang":18,"apc":{"module":"Mathématiques de Première","famille":"Résolution de problèmes issus de la vie courante et des sciences","agir":"Modéliser et résoudre des situations de la vie économique et sociale","situation":"Une vendeuse de Kumba porte sur l'épaule un bâton de 2 m avec 10 kg de plantains à un bout et un panier de masse m à l'autre.","tache":"Exprime la position de l'épaule et commente."},"verrou":true,"nq":4,"labo":true});
VRT_L("1re-d-maths-r27",{"duree":20,"titre":"Composée de deux symétries orthogonales","accroche":"Deux miroirs font une rotation.","intro":"Composer deux réflexions donne une rotation ou une translation selon la position des axes.","objectifs":["composer deux réflexions","reconnaître la transformation obtenue","décomposer une rotation"],"parties":[{"t":"Le résultat","html":"<div class='def'><b>Définition</b>Si les axes Δ et Δ' sont <strong>sécants</strong> en O, s_Δ' ∘ s_Δ est la <strong>rotation</strong> de centre O et d'angle 2(Δ ; Δ'). S'ils sont <strong>parallèles</strong>, c'est une <strong>translation</strong> de vecteur double du vecteur qui va de Δ à Δ' perpendiculairement.</div>"},{"t":"Décomposition","verrou":true},{"t":"Exemple","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"maths","rang":27,"apc":{"module":"Mathématiques de Première","famille":"Résolution de problèmes issus de la vie courante et des sciences","agir":"Modéliser et résoudre des situations de la vie économique et sociale","situation":"Un artisan de Foumban veut reproduire un motif tourné de 60° à l'aide de deux miroirs.","tache":"Quel angle doit-il donner aux miroirs ?"},"verrou":true,"nq":4,"labo":true});
VRT_L("1re-d-maths-r29",{"duree":20,"titre":"Composée de réflexions : entraînement","accroche":"Décomposer une rotation, comme au Probatoire C.","intro":"Cette séance d'entraînement reprend la notion avec un exercice du niveau du Probatoire.","objectifs":["reconnaître le type d'exercice","rédiger la méthode","éviter le piège classique"],"parties":[{"t":"Le rappel","html":"<div class='def'><b>À retenir</b>r(A ; θ) = s_(AB) ∘ s_Δ où Δ passe par A et vérifie 2(Δ ; (AB)) = θ.</div>"},{"t":"Exercice résolu","verrou":true},{"t":"Le piège à éviter","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"maths","rang":29,"apc":{"module":"Mathématiques de Première","famille":"Résolution de problèmes issus de la vie courante et des sciences","agir":"Modéliser et résoudre des situations de la vie économique et sociale","situation":"Dans un exercice de Probatoire C, on donne AB = 4 cm et la rotation r(A ; −2π/3).","tache":"Indique comment construire Δ."},"verrou":true,"nq":4,"labo":true});
VRT_L("1re-d-maths-r28",{"duree":20,"titre":"Composée de deux rotations","accroche":"Tourner deux fois autour du même point.","intro":"Composer deux rotations de même centre revient à additionner leurs angles.","objectifs":["composer des rotations de même centre","traiter des centres différents","reconnaître l'identité"],"parties":[{"t":"Même centre","html":"<div class='def'><b>Définition</b>r(O ; α) ∘ r(O ; β) est la <strong>rotation</strong> r(O ; α + β). Si α + β = 2kπ, c'est l'<strong>identité</strong>.</div>"},{"t":"Centres différents","verrou":true},{"t":"Méthode","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"maths","rang":28,"apc":{"module":"Mathématiques de Première","famille":"Résolution de problèmes issus de la vie courante et des sciences","agir":"Modéliser et résoudre des situations de la vie économique et sociale","situation":"Une roue de manège à Douala tourne de 45°, puis encore de 75° autour du même axe.","tache":"Quelle rotation obtient-on au total ?"},"verrou":true,"nq":4,"labo":true});
VRT_L("1re-d-maths-r30",{"duree":20,"titre":"Composée de rotations : entraînement","accroche":"Deux centres différents.","intro":"Cette séance d'entraînement reprend la notion avec un exercice du niveau du Probatoire.","objectifs":["reconnaître le type d'exercice","rédiger la méthode","éviter le piège classique"],"parties":[{"t":"Le rappel","html":"<div class='def'><b>À retenir</b>r(B ; β) ∘ r(A ; α) se ramène à quatre réflexions dont deux s'annulent.</div>"},{"t":"Exercice résolu","verrou":true},{"t":"Le piège à éviter","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"maths","rang":30,"apc":{"module":"Mathématiques de Première","famille":"Résolution de problèmes issus de la vie courante et des sciences","agir":"Modéliser et résoudre des situations de la vie économique et sociale","situation":"Au Probatoire C, on compose deux rotations r et r' de centres A et B d'angle −2π/3.","tache":"Donne la nature de r' ∘ r."},"verrou":true,"nq":4,"labo":true});
VRT_L("1re-d-maths-r31",{"duree":20,"titre":"Composée d'homothéties et de translations","accroche":"Agrandir, puis agrandir encore.","intro":"Les homothéties de même centre se composent en multipliant les rapports.","objectifs":["composer deux homothéties de même centre","composer homothétie et translation","déterminer centre et rapport"],"parties":[{"t":"Même centre","html":"<div class='def'><b>Définition</b>h(O ; k) ∘ h(O ; k') est l'<strong>homothétie</strong> h(O ; kk').</div>"},{"t":"Homothétie et translation","verrou":true},{"t":"Trouver un centre","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"maths","rang":31,"apc":{"module":"Mathématiques de Première","famille":"Résolution de problèmes issus de la vie courante et des sciences","agir":"Modéliser et résoudre des situations de la vie économique et sociale","situation":"Un imprimeur de Yaoundé agrandit une affiche au double, puis encore de 1,5 depuis le même coin.","tache":"Quel est l'agrandissement total ?"},"verrou":true,"nq":4,"labo":true});
VRT_L("1re-d-maths-r36",{"duree":20,"titre":"Généralités sur les suites numériques","accroche":"Une liste de nombres qui suit une règle.","intro":"Une suite peut être donnée par une formule ou par une relation de récurrence.","objectifs":["calculer des termes","étudier le sens de variation","utiliser le raisonnement par récurrence"],"parties":[{"t":"Définition","html":"<div class='def'><b>Définition</b>Une <strong>suite</strong> associe à chaque entier n un réel uₙ. Elle est définie <strong>explicitement</strong> (uₙ = 2n + 1) ou <strong>par récurrence</strong> (u₀ = 1, uₙ₊₁ = 2uₙ + 1).</div>"},{"t":"Sens de variation","verrou":true},{"t":"Récurrence","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"maths","rang":36,"apc":{"module":"Mathématiques de Première","famille":"Résolution de problèmes issus de la vie courante et des sciences","agir":"Modéliser et résoudre des situations de la vie économique et sociale","situation":"Une tontine de quartier à Douala commence avec 1 membre et chaque mois chaque membre en invite un, plus le fondateur un de plus : uₙ₊₁ = 2uₙ + 1.","tache":"Combien de membres au bout de 3 mois ?"},"verrou":true,"nq":4,"labo":true});
VRT_L("1re-d-maths-r37",{"duree":20,"titre":"Suites arithmétiques et géométriques","accroche":"Ajouter ou multiplier la même quantité.","intro":"Ces deux suites modélisent salaires, épargne et populations.","objectifs":["reconnaître chaque suite","calculer le terme général","calculer une somme"],"parties":[{"t":"Définitions","html":"<div class='def'><b>Définition</b>Une suite est <strong>arithmétique</strong> de raison r si uₙ₊₁ = uₙ + r ; elle est <strong>géométrique</strong> de raison q si vₙ₊₁ = q·vₙ.</div>"},{"t":"Formules","verrou":true},{"t":"Intérêts composés","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"maths","rang":37,"apc":{"module":"Mathématiques de Première","famille":"Résolution de problèmes issus de la vie courante et des sciences","agir":"Modéliser et résoudre des situations de la vie économique et sociale","situation":"Un fermier de Foumbot place 1 000 000 F à 15 % d'intérêts composés pour financer un élevage de 3 000 000 F dans 8 ans.","tache":"Ce placement suffira-t-il ?"},"verrou":true,"nq":4,"labo":true});
VRT_L("1re-d-maths-r38",{"duree":20,"titre":"Caractéristiques de position et de dispersion","accroche":"Moyenne, médiane, variance d'une série regroupée.","intro":"Pour une série regroupée en classes, on remplace chaque classe par son centre.","objectifs":["calculer la moyenne","calculer variance et écart type","trouver la médiane par interpolation"],"parties":[{"t":"Définitions","html":"<div class='def'><b>Définition</b>Pour une série en classes de centres cᵢ et d'effectifs nᵢ (total N) : <strong>moyenne</strong> x̄ = Σnᵢcᵢ/N ; <strong>variance</strong> V = Σnᵢcᵢ²/N − x̄² ; <strong>écart type</strong> σ = √V.</div>"},{"t":"Exemple","verrou":true},{"t":"Médiane","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"maths","rang":38,"apc":{"module":"Mathématiques de Première","famille":"Résolution de problèmes issus de la vie courante et des sciences","agir":"Modéliser et résoudre des situations de la vie économique et sociale","situation":"Une association de Douala relève les dépenses quotidiennes de ses membres, regroupées en classes, pour fixer une cotisation.","tache":"Indique les calculs utiles."},"verrou":true,"nq":4,"labo":true});
VRT_L("1re-d-maths-r39",{"duree":20,"titre":"Représentations graphiques des séries en classes","accroche":"Histogramme et polygone des effectifs cumulés.","intro":"Le graphique donne une lecture rapide de la série et permet de lire la médiane.","objectifs":["tracer un histogramme","tracer le polygone des effectifs cumulés","lire la médiane"],"parties":[{"t":"L'histogramme","html":"<div class='def'><b>Définition</b>Dans un <strong>histogramme</strong>, chaque classe est représentée par un rectangle dont l'<strong>aire</strong> est proportionnelle à l'effectif.</div>"},{"t":"Classes inégales","html":"<p>Si une classe est deux fois plus large, la hauteur de son rectangle est l'effectif divisé par 2.</p>","retenir":"Aire proportionnelle à l'effectif.","labo":{"type":"stats","classes":[0,10,20,30],"eff":[5,15,20,10],"amplitude":10}},{"t":"Effectifs cumulés","html":"<p>Le polygone des effectifs cumulés croissants relie les points (borne droite ; effectif cumulé). La médiane est l'abscisse du point d'ordonnée N/2.</p>"},{"t":"Entraînement au format de l'examen","html":"<div class='integ'><h3>Partie A : évaluation des ressources</h3><p><strong>Question de cours.</strong> Dans un histogramme, l'effectif est proportionnel à :</p><ol type='a'><li>la hauteur toujours</li><li>l'aire</li><li>la largeur</li></ol><details><summary>Voir la réponse</summary><p><strong>l'aire</strong>. Définition.</p></details><p><strong>Exercice.</strong></p><p>Classe [4 ; 8[ de fréquence 35 % : hauteur si l'unité est la classe de longueur 1 ?</p><details><summary>Voir la réponse</summary><p>(Réponse : 8,75.)</p></details><h3>Partie B : évaluation des compétences</h3><p><strong>Situation.</strong> Les dépenses de 90 clients d'un supermarché de Yaoundé (en milliers de F) : [0 ; 10[ : 20 ; [10 ; 30[ : 40 ; [30 ; 60[ : 30.</p><p><strong>Tâche 1.</strong> Calcule les hauteurs des rectangles de l'histogramme (unité : classe de 10).</p><p><strong>Tâche 2.</strong> Trace le polygone des effectifs cumulés croissants et lis la médiane.</p><details><summary>Voir une réponse attendue</summary><p>Hauteurs : 20, 40/2 = 20, 30/3 = 10. ECC : 20, 60, 90. Médiane (45e valeur) : 10 + (45 − 20)/40 × 20 = 22,5 milliers de F.</p></details></div>","retenir":"Savoir-être mobilisé : Rigueur dans la rédaction."}],"revision":["Aire proportionnelle.","Classes inégales.","Polygone et médiane."],"exo":"<p>Classe [4 ; 8[ de fréquence 35 % : hauteur si l'unité est la classe de longueur 1 ? <em>(Réponse : 8,75.)</em></p>","quiz":[{"q":"Dans un histogramme, l'effectif est proportionnel à :","r":["la hauteur toujours","l'aire","la largeur"],"b":1,"e":"Définition."},{"q":"Une classe deux fois plus large a une hauteur :","r":["divisée par 2","doublée","identique"],"b":0,"e":"Effectif constant."},{"q":"La médiane se lit à l'ordonnée :","r":["N","0","N/2"],"b":2,"e":"Polygone cumulé."},{"q":"Le polygone cumulé croissant utilise :","r":["les centres","les bornes droites","les bornes gauches seulement"],"b":1,"e":"Points."}],"c":"1re D","m":"maths","rang":39,"apc":{"module":"Mathématiques de Première","famille":"Résolution de problèmes issus de la vie courante et des sciences","agir":"Modéliser et résoudre des situations de la vie économique et sociale","situation":"Un journaliste de Yaoundé présente le temps passé devant la télévision le dimanche, en classes inégales.","tache":"Comment doit-il tracer l'histogramme ?"},"gratuit":true});
VRT_L("1re-d-maths-r41",{"duree":20,"titre":"Représentations graphiques : entraînement","accroche":"Un sujet de Probatoire D-TI 2026.","intro":"Cette séance d'entraînement reprend la notion avec un exercice du niveau du Probatoire.","objectifs":["reconnaître le type d'exercice","rédiger la méthode","éviter le piège classique"],"parties":[{"t":"Le rappel","html":"<div class='def'><b>À retenir</b>Avec des fréquences, on remplace N par 100.</div>"},{"t":"Exercice résolu","verrou":true},{"t":"Le piège à éviter","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"maths","rang":41,"apc":{"module":"Mathématiques de Première","famille":"Résolution de problèmes issus de la vie courante et des sciences","agir":"Modéliser et résoudre des situations de la vie économique et sociale","situation":"Une radio de Garoua veut savoir si la moitié des auditeurs regarde la télévision plus de 3 h le dimanche.","tache":"Réponds avec la médiane."},"verrou":true,"nq":4,"labo":true});
VRT_L("1re-d-maths-r40",{"duree":20,"titre":"Intégration : statistiques d'une association","accroche":"Des chiffres pour organiser une construction.","intro":"Le Probatoire D 2024 blanc partait d'un village qui finance une école : contributions, âges, choix de superviseurs.","objectifs":["calculer une moyenne","lire la classe modale","dénombrer un choix"],"parties":[{"t":"Les outils","html":"<div class='def'><b>Définition</b><strong>Moyenne</strong>, <strong>médiane</strong> et <strong>classe modale</strong> résument une série ; le dénombrement compte les choix possibles.</div>"},{"t":"Exemple","verrou":true},{"t":"Choix","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"maths","rang":40,"apc":{"module":"Mathématiques de Première","famille":"Résolution de problèmes issus de la vie courante et des sciences","agir":"Modéliser et résoudre des situations de la vie économique et sociale","situation":"Trois groupes d'un village de l'Ouest financent une école ; leurs 54 membres ont entre 25 et 50 ans.","tache":"Calcule l'âge moyen et le nombre de façons de choisir 3 superviseurs."},"verrou":true,"nq":4,"labo":true});
VRT_L("1re-d-maths-r42",{"duree":20,"titre":"Droites orthogonales dans l'espace","accroche":"Orthogonales sans se couper.","intro":"Dans l'espace, deux droites peuvent être orthogonales sans être sécantes.","objectifs":["définir l'orthogonalité","utiliser le produit scalaire","raisonner dans un cube"],"parties":[{"t":"Définition","html":"<div class='def'><b>Définition</b>Deux droites de l'espace sont <strong>orthogonales</strong> si leurs parallèles menées par un même point sont perpendiculaires, c'est-à-dire si leurs vecteurs directeurs ont un produit scalaire nul.</div>"},{"t":"Dans le cube","verrou":true},{"t":"Piège du Probatoire","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"maths","rang":42,"apc":{"module":"Mathématiques de Première","famille":"Résolution de problèmes issus de la vie courante et des sciences","agir":"Modéliser et résoudre des situations de la vie économique et sociale","situation":"Un charpentier de Bandjoun vérifie qu'une poutre et un chevron qui ne se touchent pas sont bien d'équerre.","tache":"Comment le vérifier avec des vecteurs ?"},"verrou":true,"nq":4,"labo":true});
VRT_L("1re-d-maths-r45",{"duree":20,"titre":"Droites orthogonales : entraînement","accroche":"Vrai ou faux, comme au Probatoire C 2022.","intro":"Cette séance d'entraînement reprend la notion avec un exercice du niveau du Probatoire.","objectifs":["reconnaître le type d'exercice","rédiger la méthode","éviter le piège classique"],"parties":[{"t":"Le rappel","html":"<div class='def'><b>À retenir</b>Pour montrer que deux droites sont orthogonales, il suffit qu'une droite soit orthogonale à un plan contenant l'autre.</div>"},{"t":"Exercice résolu","verrou":true},{"t":"Le piège à éviter","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"maths","rang":45,"apc":{"module":"Mathématiques de Première","famille":"Résolution de problèmes issus de la vie courante et des sciences","agir":"Modéliser et résoudre des situations de la vie économique et sociale","situation":"Un élève de Bafang dessine un cube en carton pour un exposé.","tache":"Utilise le cube pour réfuter l'affirmation."},"verrou":true,"nq":4,"labo":true});
VRT_L("1re-d-maths-r43",{"duree":20,"titre":"Plans orthogonaux","accroche":"Un mur et le sol.","intro":"Deux plans orthogonaux se reconnaissent à leurs vecteurs normaux.","objectifs":["définir des plans orthogonaux","utiliser les vecteurs normaux","vérifier par le calcul"],"parties":[{"t":"Définition","html":"<div class='def'><b>Définition</b>Deux plans sont <strong>orthogonaux</strong> si l'un contient une droite orthogonale à l'autre ; de façon équivalente, leurs <strong>vecteurs normaux</strong> sont orthogonaux.</div>"},{"t":"Exemple","verrou":true},{"t":"Vecteur normal","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"maths","rang":43,"apc":{"module":"Mathématiques de Première","famille":"Résolution de problèmes issus de la vie courante et des sciences","agir":"Modéliser et résoudre des situations de la vie économique et sociale","situation":"Un maçon de Ngaoundéré vérifie qu'un mur d'équation x − y = 3 est orthogonal à une dalle x + y + z = 0 dans son repère.","tache":"Conclus."},"verrou":true,"nq":4,"labo":true});
VRT_L("1re-d-maths-r46",{"duree":20,"titre":"Plans orthogonaux : entraînement","accroche":"Trouver un paramètre.","intro":"Cette séance d'entraînement reprend la notion avec un exercice du niveau du Probatoire.","objectifs":["reconnaître le type d'exercice","rédiger la méthode","éviter le piège classique"],"parties":[{"t":"Le rappel","html":"<div class='def'><b>À retenir</b>On écrit n⃗ · n⃗' = 0 et on résout en m.</div>"},{"t":"Exercice résolu","verrou":true},{"t":"Le piège à éviter","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"maths","rang":46,"apc":{"module":"Mathématiques de Première","famille":"Résolution de problèmes issus de la vie courante et des sciences","agir":"Modéliser et résoudre des situations de la vie économique et sociale","situation":"Un menuisier de Bamenda règle l'inclinaison d'un panneau dont le plan dépend d'un réglage m.","tache":"Explique comment trouver le réglage qui le rend orthogonal à la table."},"verrou":true,"nq":4,"labo":true});
VRT_L("1re-d-maths-r44",{"duree":20,"titre":"Droite et plan orthogonaux","accroche":"Un poteau bien vertical.","intro":"Une droite orthogonale à un plan l'est à toutes ses droites.","objectifs":["caractériser une droite orthogonale à un plan","utiliser vecteur directeur et vecteur normal","écrire un plan"],"parties":[{"t":"Théorème","html":"<div class='def'><b>Définition</b>Une droite est <strong>orthogonale à un plan</strong> si elle est orthogonale à deux droites sécantes de ce plan ; son vecteur directeur est alors colinéaire au vecteur normal.</div>"},{"t":"Exemple","verrou":true},{"t":"Écrire un plan","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"maths","rang":44,"apc":{"module":"Mathématiques de Première","famille":"Résolution de problèmes issus de la vie courante et des sciences","agir":"Modéliser et résoudre des situations de la vie économique et sociale","situation":"À la construction d'une antenne à Bertoua, le mât doit être orthogonal au sol d'équation z = 0.","tache":"Quelle direction doit avoir le mât ?"},"verrou":true,"nq":4,"labo":true});
VRT_L("1re-d-maths-r47",{"duree":20,"titre":"Droite et plan orthogonaux : entraînement","accroche":"Le point d'intersection, comme au Probatoire C 2026.","intro":"Cette séance d'entraînement reprend la notion avec un exercice du niveau du Probatoire.","objectifs":["reconnaître le type d'exercice","rédiger la méthode","éviter le piège classique"],"parties":[{"t":"Le rappel","html":"<div class='def'><b>À retenir</b>On remplace la représentation paramétrique dans l'équation du plan.</div>"},{"t":"Exercice résolu","verrou":true},{"t":"Le piège à éviter","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"maths","rang":47,"apc":{"module":"Mathématiques de Première","famille":"Résolution de problèmes issus de la vie courante et des sciences","agir":"Modéliser et résoudre des situations de la vie économique et sociale","situation":"Un architecte de Douala vérifie qu'un pilier traverse une dalle à angle droit.","tache":"Donne les deux étapes."},"verrou":true,"nq":4,"labo":true});
VRT_L("1re-d-maths-r48",{"duree":20,"titre":"Présentation du concept de graphe","accroche":"Des points et des liens.","intro":"Un graphe modélise des relations : routes entre villes, amitiés, vols.","objectifs":["définir sommets et arêtes","reconnaître un graphe simple","reconnaître un graphe complet"],"parties":[{"t":"Définition","html":"<div class='def'><b>Définition</b>Un <strong>graphe</strong> est formé de <strong>sommets</strong> reliés par des <strong>arêtes</strong>. Son <strong>ordre</strong> est le nombre de sommets.</div>"},{"t":"Graphe simple et complet","verrou":true},{"t":"Exemple","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"maths","rang":48,"apc":{"module":"Mathématiques de Première","famille":"Résolution de problèmes issus de la vie courante et des sciences","agir":"Modéliser et résoudre des situations de la vie économique et sociale","situation":"Ali, à Yaoundé, veut inviter 5 amis, dont certains ne s'entendent pas : A avec D ; B avec C, D, E ; D avec E.","tache":"Représente la situation par un graphe."},"verrou":true,"nq":4,"labo":true});
VRT_L("1re-d-maths-r49",{"duree":20,"titre":"Nombre d'arêtes et somme des degrés","accroche":"Chaque arête compte deux fois.","intro":"La somme des degrés est toujours le double du nombre d'arêtes.","objectifs":["calculer un degré","utiliser la formule des degrés","compter les arêtes d'un graphe complet"],"parties":[{"t":"Théorème","html":"<div class='def'><b>Définition</b>Le <strong>degré</strong> d'un sommet est le nombre d'arêtes qui y aboutissent. <strong>La somme des degrés est égale au double du nombre d'arêtes.</strong></div>"},{"t":"Conséquence","verrou":true},{"t":"Graphe complet","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"maths","rang":49,"apc":{"module":"Mathématiques de Première","famille":"Résolution de problèmes issus de la vie courante et des sciences","agir":"Modéliser et résoudre des situations de la vie économique et sociale","situation":"Une compagnie aérienne veut relier 5 villes du Cameroun deux à deux.","tache":"Combien de vols aller simple doit-elle prévoir ?"},"verrou":true,"nq":4,"labo":true});
VRT_L("1re-d-maths-r50",{"duree":20,"titre":"Intégration : un réseau de vols","accroche":"Graphes et espace au service d'une compagnie.","intro":"Le Probatoire D 2022 traduisait des liaisons aériennes par un graphe.","objectifs":["construire un graphe","le caractériser","compter les vols"],"parties":[{"t":"Modèle","html":"<div class='def'><b>Définition</b>Chaque ville est un <strong>sommet</strong>, chaque liaison une <strong>arête</strong>.</div>"},{"t":"Exemple","verrou":true},{"t":"Conclusion","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"maths","rang":50,"apc":{"module":"Mathématiques de Première","famille":"Résolution de problèmes issus de la vie courante et des sciences","agir":"Modéliser et résoudre des situations de la vie économique et sociale","situation":"Une compagnie relie Douala, Yaoundé, Garoua, Maroua et Bertoua l'une à toutes les autres.","tache":"Construis le graphe et calcule le nombre de vols aller simple."},"verrou":true,"nq":4,"labo":true});
VRT_L("1re-d-physique-r01",{"duree":20,"titre":"Mesures et incertitudes","accroche":"Aucune mesure n'est parfaite.","intro":"Toute mesure s'accompagne d'une incertitude. Savoir l'évaluer, c'est savoir quelle confiance accorder au résultat.","objectifs":["utiliser les unités du Système international","évaluer une incertitude","écrire un résultat correctement"],"parties":[{"t":"Mesure et incertitude","html":"<div class='def'><b>Définition</b>Le résultat d'une mesure s'écrit <strong>x = x̄ ± U</strong>, où U est l'<strong>incertitude</strong>, avec l'unité. L'incertitude relative vaut U/x̄.</div>"},{"t":"Série de mesures","html":"<p>Pour n mesures répétées de moyenne x̄ et d'écart type σ, l'incertitude vaut U = k·σ/√n, k étant le facteur d'élargissement.</p><p class='formule'>n = 12, σ = 0,27 cm, k = 2,18 : U = 2,18 × 0,27/√12 ≈ 0,17 cm</p>","labo":{"type":"calcul","f":"incert","vals":{"x":20,"d":0.5}}},{"t":"Écrire le résultat","html":"<p>f' = (10,41 ± 0,17) cm. On arrondit l'incertitude à deux chiffres significatifs au plus, et la valeur au même rang.</p>","retenir":"Valeur, incertitude, unité."},{"t":"Entraînement au format de l'examen","html":"<div class='integ'><h3>Partie A : évaluation des ressources</h3><p><strong>Vérification des savoirs.</strong> L'incertitude relative vaut :</p><ol type='a'><li>U × x̄</li><li>U / x̄</li><li>x̄ / U</li></ol><details><summary>Voir la réponse</summary><p><strong>U / x̄</strong>. Définition.</p></details><p><strong>Application directe des savoirs.</strong></p><p>Une longueur vaut 20 cm à 0,5 cm près : incertitude relative ?</p><details><summary>Voir la réponse</summary><p>(Réponse : 2,5 %.)</p></details><h3>Partie B : évaluation des compétences</h3><p><strong>Situation.</strong> Pour vérifier un pendule de laboratoire, deux groupes du lycée de Mbouda mesurent sa période. Groupe A : 10 mesures, moyenne 1,52 s, écart type 0,04 s (k = 2,26). Groupe B : 5 mesures, moyenne 1,49 s, écart type 0,06 s (k = 2,78).</p><p><strong>Consigne 1.</strong> Écris le résultat de chaque groupe avec son incertitude.</p><p><strong>Consigne 2.</strong> Les deux résultats sont-ils compatibles ? Justifie.</p><details><summary>Voir une réponse attendue</summary><p>U_A = 2,26 × 0,04/√10 ≈ 0,03 s : T = (1,52 ± 0,03) s. U_B = 2,78 × 0,06/√5 ≈ 0,07 s : T = (1,49 ± 0,07) s. Les intervalles [1,49 ; 1,55] et [1,42 ; 1,56] se chevauchent : les résultats sont compatibles.</p></details></div>","retenir":"Savoir-être mobilisé : Rigueur dans la démarche expérimentale."}],"revision":["x = x̄ ± U.","U = kσ/√n.","Arrondir au même rang."],"exo":"<p>Une longueur vaut 20 cm à 0,5 cm près : incertitude relative ? <em>(Réponse : 2,5 %.)</em></p>","quiz":[{"q":"L'incertitude relative vaut :","r":["U × x̄","U / x̄","x̄ / U"],"b":1,"e":"Définition."},{"q":"Un résultat complet comporte :","r":["valeur, incertitude et unité","seulement la valeur","seulement l'unité"],"b":0,"e":"Écriture."},{"q":"Si n augmente, l'incertitude :","r":["augmente","reste égale","diminue"],"b":2,"e":"Division par √n."},{"q":"L'unité SI de la masse est :","r":["le gramme","le kilogramme","la tonne"],"b":1,"e":"SI."}],"c":"1re D","m":"physique","rang":1,"apc":{"module":"Mesures, énergie mécanique et chaleur","famille":"Utilisation rationnelle de l'énergie","agir":"Évaluer et économiser l'énergie dans les activités quotidiennes","situation":"Au laboratoire du lycée de Mbouda, douze groupes mesurent la distance focale d'une même lentille et obtiennent une moyenne de 10,41 cm avec un écart type de 0,27 cm.","tache":"Présente le résultat avec son incertitude (k = 2,18)."},"gratuit":true});
VRT_L("1re-d-physique-r02",{"duree":20,"titre":"Notion de modèle","accroche":"Une représentation simplifiée du réel.","intro":"Les physiciens remplacent le réel par des modèles qui permettent de prévoir.","objectifs":["définir un modèle","donner des exemples","connaître les limites d'un modèle"],"parties":[{"t":"Définition","html":"<div class='def'><b>Définition</b>Un <strong>modèle</strong> est une représentation simplifiée d'un phénomène, qui permet de l'expliquer et de prévoir son évolution dans un <strong>domaine de validité</strong>.</div>"},{"t":"Exemples","verrou":true},{"t":"Limites","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"physique","rang":2,"apc":{"module":"Mesures, énergie mécanique et chaleur","famille":"Utilisation rationnelle de l'énergie","agir":"Évaluer et économiser l'énergie dans les activités quotidiennes","situation":"Un élève de Garoua modélise le ballon de football par un point pour calculer sa trajectoire.","tache":"Ce modèle permet-il d'étudier l'effet donné au ballon ? Justifie."},"verrou":true,"nq":4,"labo":true});
VRT_L("1re-d-physique-r03",{"duree":20,"titre":"Travail d'une force","accroche":"Une force qui déplace son point d'application travaille.","intro":"Le travail mesure l'énergie transférée par une force lors d'un déplacement.","objectifs":["calculer le travail d'une force constante","calculer le travail du poids","calculer le travail d'un couple"],"parties":[{"t":"Force constante","html":"<div class='def'><b>Définition</b>Le <strong>travail</strong> d'une force constante F⃗ sur un déplacement AB⃗ est <strong>W = F × AB × cos α</strong>, en joules (J). Il est moteur si W > 0, résistant si W &lt; 0.</div>"},{"t":"Poids et ressort","verrou":true},{"t":"Couple","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"physique","rang":3,"apc":{"module":"Mesures, énergie mécanique et chaleur","famille":"Utilisation rationnelle de l'énergie","agir":"Évaluer et économiser l'énergie dans les activités quotidiennes","situation":"Un pousseur du marché de Mokolo tire son chariot avec une force de 50 N inclinée de 30° sur 10 m.","tache":"Calcule le travail fourni."},"verrou":true,"nq":4,"labo":true});
VRT_L("1re-d-physique-r04",{"duree":20,"titre":"Puissance d'une force","accroche":"Le même travail, plus ou moins vite.","intro":"La puissance mesure la rapidité avec laquelle une force effectue un travail.","objectifs":["définir la puissance","utiliser P = F·v","calculer la puissance d'un couple"],"parties":[{"t":"Définition","html":"<div class='def'><b>Définition</b>La <strong>puissance moyenne</strong> est P = W/Δt, en watts (W). Pour une force constante, la puissance instantanée vaut <strong>P = F × v × cos α</strong>.</div>"},{"t":"Couple","verrou":true},{"t":"Unités","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"physique","rang":4,"apc":{"module":"Mesures, énergie mécanique et chaleur","famille":"Utilisation rationnelle de l'énergie","agir":"Évaluer et économiser l'énergie dans les activités quotidiennes","situation":"Le moteur d'une moulinette à maïs d'une meunière de Bafoussam exerce un couple de 20 N·m à 1 500 tr/min.","tache":"Quelle est sa puissance mécanique ?"},"verrou":true,"nq":4,"labo":true});
VRT_L("1re-d-physique-r05",{"duree":20,"titre":"Énergie cinétique et théorème de l'énergie cinétique","accroche":"Plus on va vite, plus il faut freiner longtemps.","intro":"L'énergie cinétique dépend de la masse et du carré de la vitesse. Le théorème relie sa variation aux travaux des forces.","objectifs":["calculer une énergie cinétique","énoncer le théorème","calculer une distance de freinage"],"parties":[{"t":"Énergie cinétique","html":"<div class='def'><b>Définition</b>Un solide de masse m en translation à la vitesse v possède l'<strong>énergie cinétique</strong> Ec = ½mv², en joules.</div>"},{"t":"Le théorème","verrou":true},{"t":"Freinage","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"physique","rang":5,"apc":{"module":"Mesures, énergie mécanique et chaleur","famille":"Utilisation rationnelle de l'énergie","agir":"Évaluer et économiser l'énergie dans les activités quotidiennes","situation":"Sur l'axe Douala-Yaoundé, un car de 1 000 kg roulant à 72 km/h freine avec une force de 5 000 N.","tache":"Quelle distance lui faut-il pour s'arrêter ?"},"verrou":true,"nq":4,"labo":true});
VRT_L("1re-d-physique-r06",{"duree":20,"titre":"Énergie potentielle","accroche":"De l'énergie en réserve.","intro":"Un solide en hauteur ou un ressort comprimé stockent de l'énergie potentielle.","objectifs":["calculer l'énergie potentielle de pesanteur","choisir une référence","calculer l'énergie élastique"],"parties":[{"t":"Pesanteur","html":"<div class='def'><b>Définition</b>L'<strong>énergie potentielle de pesanteur</strong> vaut Ep = mgz + constante, z étant l'altitude comptée sur un axe vertical vers le haut ; on choisit souvent Ep = 0 au niveau de référence.</div>"},{"t":"Exemple","verrou":true},{"t":"Élastique","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"physique","rang":6,"apc":{"module":"Mesures, énergie mécanique et chaleur","famille":"Utilisation rationnelle de l'énergie","agir":"Évaluer et économiser l'énergie dans les activités quotidiennes","situation":"Un ouvrier de Kribi hisse un sac de ciment de 50 kg sur un échafaudage de 2 m.","tache":"Quelle énergie potentielle le sac a-t-il gagnée ?"},"verrou":true,"nq":4,"labo":true});
VRT_L("1re-d-physique-r07",{"duree":20,"titre":"Énergie mécanique et sa conservation","accroche":"Sans frottement, rien ne se perd.","intro":"L'énergie mécanique se conserve si seules des forces conservatives travaillent.","objectifs":["définir l'énergie mécanique","appliquer la conservation","tenir compte des frottements"],"parties":[{"t":"Définition","html":"<div class='def'><b>Définition</b>L'<strong>énergie mécanique</strong> est Em = Ec + Ep. En l'absence de frottements, elle se <strong>conserve</strong>.</div>"},{"t":"Chute libre","verrou":true},{"t":"Frottements","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"physique","rang":7,"apc":{"module":"Mesures, énergie mécanique et chaleur","famille":"Utilisation rationnelle de l'énergie","agir":"Évaluer et économiser l'énergie dans les activités quotidiennes","situation":"Un enfant de Limbé descend un toboggan de 2 m de haut ; il arrive en bas à 5 m/s.","tache":"Montre que des frottements ont agi."},"verrou":true,"nq":4,"labo":true});
VRT_L("1re-d-physique-r08",{"duree":20,"titre":"La chaleur et ses modes de transfert","accroche":"Conduction, convection, rayonnement.","intro":"La chaleur est un transfert d'énergie qui va spontanément du corps chaud vers le corps froid.","objectifs":["distinguer chaleur et température","citer les modes de transfert","calculer une quantité de chaleur"],"parties":[{"t":"Définition","html":"<div class='def'><b>Définition</b>La <strong>chaleur</strong> Q est l'énergie transférée d'un corps chaud à un corps froid. Sans changement d'état, <strong>Q = m·c·Δθ</strong>, c étant la chaleur massique.</div>"},{"t":"Modes de transfert","verrou":true},{"t":"Changement d'état","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"physique","rang":8,"apc":{"module":"Mesures, énergie mécanique et chaleur","famille":"Utilisation rationnelle de l'énergie","agir":"Évaluer et économiser l'énergie dans les activités quotidiennes","situation":"Une vendeuse de bouillie de Ngaoundéré chauffe 2 kg d'eau de 25 °C à 100 °C (c = 4 190 J/kg/°C).","tache":"Calcule l'énergie nécessaire."},"verrou":true,"nq":4,"labo":true});
VRT_L("1re-d-physique-r09",{"duree":20,"titre":"Calorimétrie et échanges de chaleur","accroche":"Dans un calorimètre, rien ne s'échappe.","intro":"Le calorimètre isole un système pour mesurer les échanges de chaleur.","objectifs":["énoncer le principe des échanges","trouver une température d'équilibre","mesurer une chaleur massique"],"parties":[{"t":"Principe","html":"<div class='def'><b>Définition</b>Dans un <strong>calorimètre</strong> isolé, la somme des quantités de chaleur échangées est nulle : <strong>ΣQ = 0</strong>, c'est-à-dire chaleur cédée = chaleur reçue.</div>"},{"t":"Exemple","verrou":true},{"t":"Capacité du calorimètre","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"physique","rang":9,"apc":{"module":"Mesures, énergie mécanique et chaleur","famille":"Utilisation rationnelle de l'énergie","agir":"Évaluer et économiser l'énergie dans les activités quotidiennes","situation":"Pour estimer la température du foyer d'un forgeron de Foumban, on plonge un morceau de fer chauffé dans de l'eau d'un calorimètre.","tache":"Explique la démarche."},"verrou":true,"nq":4,"labo":true});
VRT_L("1re-d-physique-r10",{"duree":20,"titre":"Lentilles minces : caractéristiques","accroche":"Converger ou diverger.","intro":"Une lentille mince dévie la lumière ; ses foyers et sa vergence la caractérisent.","objectifs":["distinguer les lentilles","définir foyers et distance focale","calculer une vergence"],"parties":[{"t":"Définitions","html":"<div class='def'><b>Définition</b>Une <strong>lentille mince</strong> convergente a des bords minces ; une divergente, des bords épais. La <strong>vergence</strong> vaut C = 1/f', en dioptries (δ), f' étant en mètres : C > 0 pour une convergente.</div>"},{"t":"Les rayons particuliers","html":"<ul><li>Un rayon passant par le centre optique O n'est pas dévié.</li><li>Un rayon parallèle à l'axe émerge en passant par F'.</li><li>Un rayon passant par F émerge parallèle à l'axe.</li></ul>","labo":{"type":"lentille","f":10,"oa":-30}},{"t":"Vergences","html":"<p>C = (n − 1)(1/R₁ − 1/R₂). Lentille biconvexe, R = 5 cm, n = 1,5 : C = 20 δ, f' = 5 cm. Lentilles accolées : C = C₁ + C₂ (théorème des vergences).</p>","retenir":"C = 1/f' en dioptries."},{"t":"Entraînement au format de l'examen","html":"<div class='integ'><h3>Partie A : évaluation des ressources</h3><p><strong>Vérification des savoirs.</strong> Une lentille à bords épais est :</p><ol type='a'><li>convergente</li><li>divergente</li><li>plane</li></ol><details><summary>Voir la réponse</summary><p><strong>divergente</strong>. Reconnaissance.</p></details><p><strong>Application directe des savoirs.</strong></p><p>Vergence d'une lentille de f' = 20 cm ?</p><details><summary>Voir la réponse</summary><p>(Réponse : 5 δ.)</p></details><h3>Partie B : évaluation des compétences</h3><p><strong>Situation.</strong> Un opticien du marché Central dispose de trois lentilles : L₁ de vergence +5 δ, L₂ de vergence −4 δ, et L₃ biconvexe en verre d'indice 1,5 dont les deux faces ont un rayon de courbure de 10 cm.</p><p><strong>Consigne 1.</strong> Calcule la distance focale de chaque lentille et donne sa nature.</p><p><strong>Consigne 2.</strong> Laquelle choisir pour fabriquer une loupe ? Justifie.</p><details><summary>Voir une réponse attendue</summary><p>L₁ : f' = 20 cm, convergente. L₂ : f' = −25 cm, divergente. L₃ : C = (1,5 − 1)(1/0,1 + 1/0,1) = 10 δ, f' = 10 cm, convergente. Pour une loupe, on choisit la convergente la plus puissante : L₃.</p></details></div>","retenir":"Savoir-être mobilisé : Rigueur dans la démarche expérimentale."}],"revision":["Convergente ou divergente.","Rayons particuliers.","C = 1/f'."],"exo":"<p>Vergence d'une lentille de f' = 20 cm ? <em>(Réponse : 5 δ.)</em></p>","quiz":[{"q":"Une lentille à bords épais est :","r":["convergente","divergente","plane"],"b":1,"e":"Reconnaissance."},{"q":"Un rayon passant par O :","r":["n'est pas dévié","passe par F'","est réfléchi"],"b":0,"e":"Rayon particulier."},{"q":"f' = 20 cm donne C =","r":["20 δ","0,2 δ","5 δ"],"b":2,"e":"1/0,2."},{"q":"Deux lentilles accolées de 5 δ et −2 δ ont :","r":["7 δ","3 δ","−10 δ"],"b":1,"e":"Somme."}],"c":"1re D","m":"physique","rang":10,"apc":{"module":"Optique et lumière","famille":"Protection et amélioration de la vision","agir":"Choisir et utiliser des instruments d'optique","situation":"Un réparateur de lunettes du marché Central reçoit une lentille sans étiquette.","tache":"Comment savoir si elle est convergente ?"},"gratuit":true});
VRT_L("1re-d-physique-r11",{"duree":20,"titre":"Image donnée par une lentille et relation de conjugaison","accroche":"Calculer où se forme l'image.","intro":"La relation de conjugaison et le grandissement donnent la position et la taille de l'image.","objectifs":["construire une image","appliquer la relation de conjugaison","calculer le grandissement"],"parties":[{"t":"Conjugaison","html":"<div class='def'><b>Définition</b>Avec des distances algébriques mesurées depuis O : <strong>1/OA' − 1/OA = 1/f'</strong>. Le <strong>grandissement</strong> vaut γ = A'B'/AB = OA'/OA.</div>"},{"t":"Exemple","verrou":true},{"t":"Construction","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"physique","rang":11,"apc":{"module":"Optique et lumière","famille":"Protection et amélioration de la vision","agir":"Choisir et utiliser des instruments d'optique","situation":"Un photographe de Douala place un sujet à 30 cm d'un objectif de distance focale 10 cm.","tache":"Où mettre le capteur ?"},"verrou":true,"nq":4,"labo":true});
VRT_L("1re-d-physique-r12",{"duree":20,"titre":"L'œil et ses défauts","accroche":"Accommoder, corriger.","intro":"L'œil se comporte comme une lentille convergente de vergence variable devant un écran, la rétine.","objectifs":["décrire l'œil réduit","définir PP et PR","corriger myopie et hypermétropie"],"parties":[{"t":"L'œil réduit","html":"<div class='def'><b>Définition</b>L'<strong>œil réduit</strong> est modélisé par une lentille convergente (cristallin) placée devant un écran fixe (rétine). L'<strong>accommodation</strong> modifie sa vergence pour garder l'image nette.</div>"},{"t":"Défauts","verrou":true},{"t":"Exemple","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"physique","rang":12,"apc":{"module":"Optique et lumière","famille":"Protection et amélioration de la vision","agir":"Choisir et utiliser des instruments d'optique","situation":"Un élève de Bertoua voit mal le tableau du fond de la classe ; l'ophtalmologue mesure son PR à 2 m.","tache":"Identifie le défaut et propose une correction."},"verrou":true,"nq":4,"labo":true});
VRT_L("1re-d-physique-r13",{"duree":20,"titre":"La loupe","accroche":"Voir plus grand ce qui est petit.","intro":"La loupe est une lentille convergente de courte distance focale.","objectifs":["expliquer le fonctionnement","définir puissance et grossissement","calculer"],"parties":[{"t":"Principe","html":"<div class='def'><b>Définition</b>La <strong>loupe</strong> est une lentille convergente de petite distance focale. L'objet placé entre le foyer F et O en donne une image <strong>virtuelle, droite et agrandie</strong>.</div>"},{"t":"Puissance et grossissement","verrou":true},{"t":"Usage","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"physique","rang":13,"apc":{"module":"Optique et lumière","famille":"Protection et amélioration de la vision","agir":"Choisir et utiliser des instruments d'optique","situation":"Un horloger du marché de Mokolo utilise une loupe de distance focale 5 cm.","tache":"Calcule sa puissance intrinsèque et son grossissement commercial."},"verrou":true,"nq":4,"labo":true});
VRT_L("1re-d-physique-r14",{"duree":20,"titre":"Le microscope","accroche":"Voir une cellule de 10 µm.","intro":"Le microscope associe deux lentilles convergentes pour un fort grossissement.","objectifs":["décrire le microscope","définir l'intervalle optique","calculer puissance et grossissement"],"parties":[{"t":"Description","html":"<div class='def'><b>Définition</b>Le <strong>microscope</strong> comporte un objectif de très petite distance focale f₁ et un oculaire de petite distance focale f₂. L'<strong>intervalle optique</strong> Δ est la distance F₁'F₂.</div>"},{"t":"Formules","verrou":true},{"t":"Utilisation","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"physique","rang":14,"apc":{"module":"Optique et lumière","famille":"Protection et amélioration de la vision","agir":"Choisir et utiliser des instruments d'optique","situation":"Au laboratoire d'analyses d'un hôpital de Bafoussam, un microscope a f₁ = 0,4 cm, f₂ = 5 cm et O₁O₂ = 25,4 cm.","tache":"Calcule son grossissement commercial."},"verrou":true,"nq":4,"labo":true});
VRT_L("1re-d-physique-r15",{"duree":20,"titre":"Puissance et grossissement d'un instrument","accroche":"Comparer des instruments d'optique.","intro":"Puissance et grossissement permettent de comparer les instruments.","objectifs":["définir la puissance","définir le grossissement","calculer le diamètre apparent"],"parties":[{"t":"Définitions","html":"<div class='def'><b>Définition</b>La <strong>puissance</strong> d'un instrument est P = α'/AB (δ), α' étant l'angle sous lequel on voit l'image. Le <strong>grossissement</strong> est G = α'/α, α étant l'angle sous lequel on verrait l'objet à l'œil nu.</div>"},{"t":"Grossissement commercial","verrou":true},{"t":"Diamètre apparent","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"physique","rang":15,"apc":{"module":"Optique et lumière","famille":"Protection et amélioration de la vision","agir":"Choisir et utiliser des instruments d'optique","situation":"Un vendeur du marché Mboppi propose deux loupes : 10 δ et 20 δ.","tache":"Laquelle grossit le plus ? Justifie."},"verrou":true,"nq":4,"labo":true});
VRT_L("1re-d-physique-r16",{"duree":20,"titre":"Spectres lumineux","accroche":"La lumière blanche contient toutes les couleurs.","intro":"Un prisme décompose la lumière ; le spectre renseigne sur la source et sur la matière traversée.","objectifs":["décrire le spectre de la lumière blanche","distinguer émission et absorption","situer le visible parmi les ondes"],"parties":[{"t":"Spectres","html":"<div class='def'><b>Définition</b>Un <strong>spectre d'émission</strong> est formé de raies colorées sur fond noir ; un <strong>spectre d'absorption</strong>, de raies noires sur le fond coloré du spectre continu.</div>"},{"t":"Ondes électromagnétiques","verrou":true},{"t":"Température et couleur","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"physique","rang":16,"apc":{"module":"Optique et lumière","famille":"Protection et amélioration de la vision","agir":"Choisir et utiliser des instruments d'optique","situation":"Un forgeron de Bamessing chauffe une barre d'acier jusqu'à ce qu'elle devienne orange (λ ≈ 600 nm).","tache":"Estime sa température."},"verrou":true,"nq":4,"labo":true});
VRT_L("1re-d-physique-r17",{"duree":20,"titre":"Interaction lumière-matière","accroche":"Un photon, un saut d'énergie.","intro":"La lumière échange de l'énergie avec la matière par paquets : les photons.","objectifs":["calculer l'énergie d'un photon","interpréter une transition","distinguer émission et absorption"],"parties":[{"t":"Le photon","html":"<div class='def'><b>Définition</b>La lumière de fréquence ν est formée de <strong>photons</strong> d'énergie <strong>E = hν = hc/λ</strong>, h = 6,62 × 10⁻³⁴ J·s. En pratique : E (eV) ≈ 1 240/λ (nm).</div>"},{"t":"Transitions","verrou":true},{"t":"Exemple","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"physique","rang":17,"apc":{"module":"Optique et lumière","famille":"Protection et amélioration de la vision","agir":"Choisir et utiliser des instruments d'optique","situation":"Les lampes à vapeur de sodium des carrefours de Douala émettent une lumière jaune-orange de 589 nm.","tache":"Calcule l'énergie d'un photon émis."},"verrou":true,"nq":4,"labo":true});
VRT_L("1re-d-physique-r18",{"duree":20,"titre":"Les générateurs électriques","accroche":"La pile ne délivre pas toute sa f.é.m.","intro":"Un générateur réel a une force électromotrice et une résistance interne.","objectifs":["schématiser un générateur","appliquer U = E − rI","associer des générateurs"],"parties":[{"t":"Caractéristique","html":"<div class='def'><b>Définition</b>Un générateur linéaire a pour caractéristique <strong>U = E − rI</strong>, E étant sa force électromotrice (V) et r sa résistance interne (Ω).</div>"},{"t":"Associations","verrou":true},{"t":"Exemple","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"physique","rang":18,"apc":{"module":"Électricité et électromagnétisme","famille":"Utilisation rationnelle de l'énergie électrique","agir":"Exploiter des générateurs et des récepteurs avec un bon rendement","situation":"Un réparateur de radios de Bafang associe 4 piles de 1,5 V en série pour un poste.","tache":"Calcule la f.é.m. obtenue."},"verrou":true,"nq":4,"labo":true});
VRT_L("1re-d-physique-r19",{"duree":20,"titre":"Les récepteurs électriques","accroche":"Moteurs et électrolyseurs ont une f.c.é.m.","intro":"Un récepteur actif convertit l'énergie électrique en une autre forme que la chaleur.","objectifs":["schématiser un récepteur","appliquer U = E' + r'I","distinguer récepteurs passifs et actifs"],"parties":[{"t":"Caractéristique","html":"<div class='def'><b>Définition</b>Un récepteur actif linéaire (moteur, électrolyseur) vérifie <strong>U = E' + r'I</strong>, E' étant sa force contre-électromotrice.</div>"},{"t":"Récepteurs passifs","verrou":true},{"t":"Exemple","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"physique","rang":19,"apc":{"module":"Électricité et électromagnétisme","famille":"Utilisation rationnelle de l'énergie électrique","agir":"Exploiter des générateurs et des récepteurs avec un bon rendement","situation":"Un ventilateur alimenté par un panneau solaire à Maroua a une f.c.é.m. de 6 V et une résistance interne de 2 Ω.","tache":"Calcule la tension à ses bornes pour 0,5 A."},"verrou":true,"nq":4,"labo":true});
VRT_L("1re-d-physique-r20",{"duree":20,"titre":"Point de fonctionnement d'un circuit","accroche":"Là où générateur et récepteur s'accordent.","intro":"Le point de fonctionnement est l'intersection des caractéristiques du générateur et du récepteur.","objectifs":["trouver graphiquement le point","appliquer la loi de Pouillet","exploiter la caractéristique d'une diode"],"parties":[{"t":"Définition","html":"<div class='def'><b>Définition</b>Le <strong>point de fonctionnement</strong> d'un circuit est le point (I ; U) commun aux caractéristiques du générateur et du récepteur.</div>"},{"t":"Loi de Pouillet","html":"<p class='formule'>I = (E − E') / (R + r + r')</p><p>E = 12 V, r = 2 Ω, résistor R = 10 Ω : I = 1 A et U = 10 V.</p>","labo":{"type":"fonctionnement","e":12,"r":2,"rc":10}},{"t":"Diode","html":"<p>Avec une diode de seuil 0,6 V en série avec R : I = (E − 0,6)/(R + r) si E > 0,6 V.</p>","retenir":"Pouillet : courant d'un circuit série."},{"t":"Entraînement au format de l'examen","html":"<div class='integ'><h3>Partie A : évaluation des ressources</h3><p><strong>Vérification des savoirs.</strong> Le point de fonctionnement est :</p><ol type='a'><li>le maximum de U</li><li>l'intersection des caractéristiques</li><li>le zéro</li></ol><details><summary>Voir la réponse</summary><p><strong>l'intersection des caractéristiques</strong>. Définition.</p></details><p><strong>Application directe des savoirs.</strong></p><p>E = 9 V, r = 1 Ω, R = 8 Ω : I ?</p><details><summary>Voir la réponse</summary><p>(Réponse : 1 A.)</p></details><h3>Partie B : évaluation des compétences</h3><p><strong>Situation.</strong> Une batterie (E = 12 V, r = 0,5 Ω) alimente en série un moteur (E' = 8 V, r' = 1,5 Ω) et un rhéostat de 2 Ω, dans un atelier de Limbé.</p><p><strong>Consigne 1.</strong> Calcule l'intensité du courant.</p><p><strong>Consigne 2.</strong> Calcule la tension aux bornes de la batterie et du moteur.</p><details><summary>Voir une réponse attendue</summary><p>I = (12 − 8)/(0,5 + 1,5 + 2) = 1 A. U(batterie) = 12 − 0,5 = 11,5 V ; U(moteur) = 8 + 1,5 = 9,5 V.</p></details></div>","retenir":"Savoir-être mobilisé : Rigueur dans la démarche expérimentale."}],"revision":["Intersection.","Pouillet.","Diode."],"exo":"<p>E = 9 V, r = 1 Ω, R = 8 Ω : I ? <em>(Réponse : 1 A.)</em></p>","quiz":[{"q":"Le point de fonctionnement est :","r":["le maximum de U","l'intersection des caractéristiques","le zéro"],"b":1,"e":"Définition."},{"q":"La loi de Pouillet donne :","r":["I","E","r"],"b":0,"e":"Intensité."},{"q":"Pour E = 12 V, r = 2 Ω, R = 10 Ω, U vaut :","r":["12 V","2 V","10 V"],"b":2,"e":"RI."},{"q":"Une diode en sens bloquant donne :","r":["I maximal","I nul","U nul"],"b":1,"e":"Pas de courant."}],"c":"1re D","m":"physique","rang":20,"apc":{"module":"Électricité et électromagnétisme","famille":"Utilisation rationnelle de l'énergie électrique","agir":"Exploiter des générateurs et des récepteurs avec un bon rendement","situation":"Une lampe de chantier à Edéa, de résistance 10 Ω, est branchée sur une batterie de 12 V et 2 Ω.","tache":"Détermine le point de fonctionnement."},"gratuit":true});
VRT_L("1re-d-physique-r21",{"duree":20,"titre":"Champ magnétique et flux magnétique","accroche":"Compter les lignes de champ qui traversent une bobine.","intro":"Le flux magnétique mesure la quantité de champ qui traverse une surface.","objectifs":["décrire un champ magnétique","calculer le champ d'un solénoïde","calculer un flux"],"parties":[{"t":"Champ magnétique","html":"<div class='def'><b>Définition</b>Le <strong>champ magnétique</strong> B⃗ se mesure en teslas (T) au teslamètre. Dans un solénoïde long : B = μ₀NI/L, μ₀ = 4π × 10⁻⁷ SI.</div>"},{"t":"Flux","verrou":true},{"t":"Exemple","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"physique","rang":21,"apc":{"module":"Électricité et électromagnétisme","famille":"Utilisation rationnelle de l'énergie électrique","agir":"Exploiter des générateurs et des récepteurs avec un bon rendement","situation":"Un électricien de Douala étudie une bobine de 100 spires de 50 cm² placée dans un champ de 0,2 T.","tache":"Calcule le flux maximal."},"verrou":true,"nq":4,"labo":true});
VRT_L("1re-d-physique-r22",{"duree":20,"titre":"Induction et auto-induction","accroche":"Un flux qui varie crée une tension.","intro":"Toute variation de flux à travers un circuit y fait naître une force électromotrice induite.","objectifs":["énoncer la loi de Faraday","appliquer la loi de Lenz","décrire l'auto-induction"],"parties":[{"t":"Loi de Faraday","html":"<div class='def'><b>Définition</b>Une variation de flux crée une <strong>f.é.m. induite</strong> e = −ΔΦ/Δt. Le courant induit s'oppose, par ses effets, à la cause qui lui donne naissance (<strong>loi de Lenz</strong>).</div>"},{"t":"Exemple","verrou":true},{"t":"Auto-induction","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"physique","rang":22,"apc":{"module":"Électricité et électromagnétisme","famille":"Utilisation rationnelle de l'énergie électrique","agir":"Exploiter des générateurs et des récepteurs avec un bon rendement","situation":"Une lampe de vélo d'un élève de Bamenda s'allume grâce à une dynamo.","tache":"Explique l'origine du courant."},"verrou":true,"nq":4,"labo":true});
VRT_L("1re-d-physique-r23",{"duree":20,"titre":"Les générateurs électromagnétiques","accroche":"De Song Loulou à la dynamo de vélo.","intro":"L'alternateur transforme une énergie mécanique de rotation en énergie électrique alternative.","objectifs":["décrire un alternateur","relier fréquence et vitesse de rotation","citer des exemples"],"parties":[{"t":"Principe","html":"<div class='def'><b>Définition</b>Un <strong>alternateur</strong> comprend un rotor (aimant ou électroaimant) qui tourne devant un stator (bobines). La variation de flux crée une tension alternative.</div>"},{"t":"Fréquence","verrou":true},{"t":"Exemples","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"physique","rang":23,"apc":{"module":"Électricité et électromagnétisme","famille":"Utilisation rationnelle de l'énergie électrique","agir":"Exploiter des générateurs et des récepteurs avec un bon rendement","situation":"Un groupe électrogène d'un quartier de Bertoua doit fournir du 50 Hz avec un alternateur à 2 paires de pôles.","tache":"À quelle vitesse le moteur doit-il tourner ?"},"verrou":true,"nq":4,"labo":true});
VRT_L("1re-d-physique-r24",{"duree":20,"titre":"Énergie, puissance et rendement électriques","accroche":"Toute l'énergie n'arrive pas à destination.","intro":"Dans une chaîne énergétique, chaque convertisseur perd une partie de l'énergie, surtout en chaleur.","objectifs":["faire le bilan d'un générateur","faire le bilan d'un récepteur","calculer le rendement d'une chaîne"],"parties":[{"t":"Générateur","html":"<div class='def'><b>Définition</b>Un générateur fournit la puissance totale EI, en perd rI² par effet Joule et délivre UI. Son <strong>rendement</strong> vaut ρ = UI/EI = U/E.</div>"},{"t":"Récepteur","verrou":true},{"t":"Chaîne énergétique","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"physique","rang":24,"apc":{"module":"Électricité et électromagnétisme","famille":"Utilisation rationnelle de l'énergie électrique","agir":"Exploiter des générateurs et des récepteurs avec un bon rendement","situation":"Un kit solaire d'une école de Kousseri alimente une pompe : batterie de rendement 83 %, moteur de rendement 86 %.","tache":"Calcule le rendement global et propose une amélioration."},"verrou":true,"nq":4,"labo":true});
VRT_L("1re-d-svt-r01",{"duree":20,"titre":"Cellules animale et végétale au microscope optique","accroche":"Deux cellules, des points communs et des différences.","intro":"La cellule est l'unité de base du vivant ; le microscope optique révèle son organisation.","objectifs":["décrire les deux types de cellules","les comparer","calculer une taille réelle"],"parties":[{"t":"La cellule","html":"<div class='def'><b>Définition</b>La <strong>cellule</strong> est l'unité structurale et fonctionnelle du vivant : une membrane plasmique, un cytoplasme et un noyau.</div>"},{"t":"Comparaison","html":"<p>La cellule végétale possède en plus une paroi pectocellulosique, une grande vacuole et, dans les parties vertes, des chloroplastes.</p>","retenir":"Paroi, vacuole, chloroplastes : cellule végétale.","labo":{"type":"osmose","c":9,"veg":true}},{"t":"Taille réelle","html":"<p class='formule'>taille réelle = taille sur l'image / grossissement</p>"},{"t":"Entraînement au format de l'examen","html":"<div class='integ'><h3>Partie A : évaluation des ressources</h3><p><strong>Évaluation des savoirs (QCM).</strong> La paroi est propre à :</p><ol type='a'><li>la cellule animale</li><li>la cellule végétale</li><li>aucune</li></ol><details><summary>Voir la réponse</summary><p><strong>la cellule végétale</strong>. Pectocellulose.</p></details><p><strong>Évaluation des savoir-faire.</strong></p><p>Image de 15 mm au grossissement × 600 : taille réelle ?</p><details><summary>Voir la réponse</summary><p>(Réponse : 25 µm.)</p></details><h3>Partie B : évaluation des compétences</h3><p><strong>Compétence visée.</strong> Exploiter les connaissances sur la cellule et les gènes pour améliorer la production.</p><p><strong>Situation.</strong> Au laboratoire d'un lycée de Bafia, un élève observe au grossissement × 400 deux préparations : la première montre des cellules polygonales jointives, avec une grande vacuole ; la seconde des cellules arrondies, isolées, sans paroi. Sur la photo, une cellule mesure 16 mm.</p><p><strong>Consigne 1.</strong> Identifie l'origine de chaque préparation et justifie.</p><p><strong>Consigne 2.</strong> Calcule la taille réelle de la cellule photographiée.</p><details><summary>Voir une réponse attendue</summary><p>La première est végétale (paroi, grande vacuole, cellules jointives), par exemple l'épiderme d'oignon ; la seconde animale, par exemple la muqueuse buccale. Taille réelle : 16 mm/400 = 0,04 mm = 40 µm.</p></details></div>","retenir":"Savoir-être mobilisé : Rigueur dans l'analyse."}],"revision":["Membrane, cytoplasme, noyau.","Spécificités végétales."],"exo":"<p>Image de 15 mm au grossissement × 600 : taille réelle ? <em>(Réponse : 25 µm.)</em></p>","quiz":[{"q":"La paroi est propre à :","r":["la cellule animale","la cellule végétale","aucune"],"b":1,"e":"Pectocellulose."},{"q":"Toutes les cellules ont :","r":["une membrane plasmique","une paroi","des chloroplastes"],"b":0,"e":"Point commun."},{"q":"Les chloroplastes se trouvent :","r":["dans les globules rouges","dans les racines","dans les parties vertes des plantes"],"b":2,"e":"Photosynthèse."},{"q":"Taille réelle = taille image :","r":["× grossissement","/ grossissement","+ grossissement"],"b":1,"e":"Formule."}],"c":"1re D","m":"svt","rang":1,"apc":{"module":"Identité biologique, code génétique et enzymes","famille":"Recherche d'un meilleur équilibre de vie","agir":"Exploiter les connaissances sur la cellule et les gènes pour améliorer la production","situation":"Au laboratoire d'un lycée de Bafia, un élève compare une cellule d'épiderme d'oignon et une cellule de sa muqueuse buccale.","tache":"Présente trois différences."},"gratuit":true});
VRT_L("1re-d-svt-r02",{"duree":20,"titre":"TP 1 : préparations microscopiques","accroche":"De l'oignon et la joue sous l'objectif.","intro":"Cette séance de travaux pratiques met en œuvre la démarche expérimentale : protocole, observation, interprétation et compte rendu.","objectifs":["suivre un protocole","observer et schématiser","interpréter un résultat"],"parties":[{"t":"Le but","html":"<div class='def'><b>Définition</b>Réaliser une <strong>préparation microscopique</strong> : un échantillon mince entre lame et lamelle, éventuellement coloré, pour l'observer au microscope.</div>"},{"t":"Matériel et protocole","verrou":true},{"t":"Observation et sécurité","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"svt","rang":2,"apc":{"module":"Identité biologique, code génétique et enzymes","famille":"Recherche d'un meilleur équilibre de vie","agir":"Exploiter les connaissances sur la cellule et les gènes pour améliorer la production","situation":"Le professeur d'un lycée de Mbouda demande un compte rendu de la préparation d'épiderme d'oignon.","tache":"Rédige le protocole en quatre étapes."},"verrou":true,"nq":4,"labo":true});
VRT_L("1re-d-svt-r03",{"duree":20,"titre":"Ultrastructure et rôles des organites","accroche":"Au microscope électronique, la cellule est une usine.","intro":"Le microscope électronique révèle les organites et leurs fonctions.","objectifs":["identifier les organites","associer organite et fonction","relier structure et fonction"],"parties":[{"t":"Les organites","html":"<div class='def'><b>Définition</b>Un <strong>organite</strong> est une structure cellulaire spécialisée : noyau, mitochondrie, chloroplaste, réticulum endoplasmique, appareil de Golgi, ribosome, vacuole, lysosome.</div>"},{"t":"Fonctions","verrou":true},{"t":"Reconnaître","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"svt","rang":3,"apc":{"module":"Identité biologique, code génétique et enzymes","famille":"Recherche d'un meilleur équilibre de vie","agir":"Exploiter les connaissances sur la cellule et les gènes pour améliorer la production","situation":"Sur une électronographie fournie au Probatoire, une cellule de pancréas présente beaucoup de réticulum granuleux et de Golgi.","tache":"Que peux-tu en déduire sur son activité ?"},"verrou":true,"nq":4,"labo":true});
VRT_L("1re-d-svt-r04",{"duree":20,"titre":"TP 2 : électronographies des organites","accroche":"Reconnaître un organite à sa silhouette.","intro":"Cette séance de travaux pratiques met en œuvre la démarche expérimentale : protocole, observation, interprétation et compte rendu.","objectifs":["suivre un protocole","observer et schématiser","interpréter un résultat"],"parties":[{"t":"Le but","html":"<div class='def'><b>Définition</b>Une <strong>électronographie</strong> est une image obtenue au microscope électronique ; elle montre l'ultrastructure.</div>"},{"t":"Matériel et protocole","verrou":true},{"t":"Observation et sécurité","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"svt","rang":4,"apc":{"module":"Identité biologique, code génétique et enzymes","famille":"Recherche d'un meilleur équilibre de vie","agir":"Exploiter les connaissances sur la cellule et les gènes pour améliorer la production","situation":"Un élève de Bamenda doit légender une électronographie de cellule de feuille.","tache":"Donne trois critères pour reconnaître le chloroplaste."},"verrou":true,"nq":4,"labo":true});
VRT_L("1re-d-svt-r05",{"duree":20,"titre":"Structure et composition d'un chromosome","accroche":"De l'ADN enroulé autour de protéines.","intro":"Les chromosomes portent l'information génétique ; ils se condensent pendant la division.","objectifs":["décrire un chromosome","donner sa composition","lire un caryotype"],"parties":[{"t":"Composition","html":"<div class='def'><b>Définition</b>Un <strong>chromosome</strong> est formé d'<strong>ADN</strong> associé à des protéines (histones). Hors division, il forme la chromatine dispersée.</div>"},{"t":"Structure","verrou":true},{"t":"Caryotype","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"svt","rang":5,"apc":{"module":"Identité biologique, code génétique et enzymes","famille":"Recherche d'un meilleur équilibre de vie","agir":"Exploiter les connaissances sur la cellule et les gènes pour améliorer la production","situation":"Un laboratoire de Yaoundé établit le caryotype d'un enfant présentant des signes de trisomie.","tache":"Explique ce que montrera le caryotype."},"verrou":true,"nq":4,"labo":true});
VRT_L("1re-d-svt-r06",{"duree":20,"titre":"L'ADN, support de l'information génétique","accroche":"Une expérience sur des bactéries l'a prouvé.","intro":"Des expériences de transformation bactérienne ont montré que l'ADN porte l'information héréditaire.","objectifs":["décrire l'expérience de Griffith","interpréter Avery","décrire la molécule d'ADN"],"parties":[{"t":"Les expériences","html":"<div class='def'><b>Définition</b>La <strong>transformation bactérienne</strong> est l'acquisition d'un caractère héréditaire par une bactérie à partir de l'ADN d'une autre bactérie.</div>"},{"t":"Griffith et Avery","verrou":true},{"t":"La molécule","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"svt","rang":6,"apc":{"module":"Identité biologique, code génétique et enzymes","famille":"Recherche d'un meilleur équilibre de vie","agir":"Exploiter les connaissances sur la cellule et les gènes pour améliorer la production","situation":"Lors d'une conférence au lycée de Garoua, un élève demande comment on sait que l'ADN porte les gènes.","tache":"Résume l'argument expérimental."},"verrou":true,"nq":4,"labo":true});
VRT_L("1re-d-svt-r07",{"duree":20,"titre":"TP 3 : maquette de l'ADN","accroche":"Des capsules et des pailles.","intro":"Cette séance de travaux pratiques met en œuvre la démarche expérimentale : protocole, observation, interprétation et compte rendu.","objectifs":["suivre un protocole","observer et schématiser","interpréter un résultat"],"parties":[{"t":"Le but","html":"<div class='def'><b>Définition</b>Une <strong>maquette</strong> est un modèle concret qui représente la structure d'une molécule.</div>"},{"t":"Matériel et protocole","verrou":true},{"t":"Observation et sécurité","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"svt","rang":7,"apc":{"module":"Identité biologique, code génétique et enzymes","famille":"Recherche d'un meilleur équilibre de vie","agir":"Exploiter les connaissances sur la cellule et les gènes pour améliorer la production","situation":"Un club scientifique de Kribi prépare une maquette d'ADN pour la journée portes ouvertes.","tache":"Donne les règles à respecter."},"verrou":true,"nq":4,"labo":true});
VRT_L("1re-d-svt-r08",{"duree":20,"titre":"La division cellulaire : la mitose","accroche":"Une cellule devient deux cellules identiques.","intro":"La mitose répartit équitablement les chromosomes entre deux cellules filles.","objectifs":["décrire les phases","reconnaître une phase sur un document","expliquer la conservation de l'information"],"parties":[{"t":"Définition","html":"<div class='def'><b>Définition</b>La <strong>mitose</strong> est la division d'une cellule en deux cellules filles génétiquement identiques entre elles et à la cellule mère.</div>"},{"t":"Les phases","verrou":true},{"t":"Conservation","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"svt","rang":8,"apc":{"module":"Identité biologique, code génétique et enzymes","famille":"Recherche d'un meilleur équilibre de vie","agir":"Exploiter les connaissances sur la cellule et les gènes pour améliorer la production","situation":"Une élève de Dschang observe une racine d'oignon et compte beaucoup de cellules en division près de la pointe.","tache":"Explique pourquoi."},"verrou":true,"nq":4,"labo":true});
VRT_L("1re-d-svt-r09",{"duree":20,"titre":"TP 4 : observation des cellules en division","accroche":"Les mitoses de la pointe de racine.","intro":"Cette séance de travaux pratiques met en œuvre la démarche expérimentale : protocole, observation, interprétation et compte rendu.","objectifs":["suivre un protocole","observer et schématiser","interpréter un résultat"],"parties":[{"t":"Le but","html":"<div class='def'><b>Définition</b>Observer les <strong>phases de la mitose</strong> sur des cellules en division, réelles ou en images.</div>"},{"t":"Matériel et protocole","verrou":true},{"t":"Observation et sécurité","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"svt","rang":9,"apc":{"module":"Identité biologique, code génétique et enzymes","famille":"Recherche d'un meilleur équilibre de vie","agir":"Exploiter les connaissances sur la cellule et les gènes pour améliorer la production","situation":"En TP à Limbé, un groupe ne voit aucune cellule en division sur sa préparation.","tache":"Propose deux explications."},"verrou":true,"nq":4,"labo":true});
VRT_L("1re-d-svt-r10",{"duree":20,"titre":"Cycle cellulaire et rôles de la mitose","accroche":"Doubler l'ADN, puis le partager.","intro":"Entre deux mitoses, la cellule réplique son ADN pendant l'interphase.","objectifs":["décrire le cycle cellulaire","interpréter une courbe de quantité d'ADN","citer les rôles de la mitose"],"parties":[{"t":"Le cycle","html":"<div class='def'><b>Définition</b>Le <strong>cycle cellulaire</strong> comprend l'interphase (G1, S, G2) et la mitose. La quantité d'ADN double pendant la phase S.</div>"},{"t":"Courbe","verrou":true},{"t":"Rôles","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"svt","rang":10,"apc":{"module":"Identité biologique, code génétique et enzymes","famille":"Recherche d'un meilleur équilibre de vie","agir":"Exploiter les connaissances sur la cellule et les gènes pour améliorer la production","situation":"Un agriculteur de Bertoua multiplie son manioc par boutures et obtient des plants identiques.","tache":"Explique cette ressemblance."},"verrou":true,"nq":4,"labo":true});
VRT_L("1re-d-svt-r11",{"duree":20,"titre":"Intégration : multiplier une variété performante","accroche":"Cloner pour conserver.","intro":"Un producteur veut multiplier une variété sans perdre ses qualités.","objectifs":["mobiliser la mitose","argumenter","proposer une technique"],"parties":[{"t":"Notion","html":"<div class='def'><b>Définition</b>La <strong>multiplication végétative</strong> produit des individus génétiquement identiques grâce à la mitose.</div>"},{"t":"Démarche","verrou":true},{"t":"Production attendue","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"svt","rang":11,"apc":{"module":"Identité biologique, code génétique et enzymes","famille":"Recherche d'un meilleur équilibre de vie","agir":"Exploiter les connaissances sur la cellule et les gènes pour améliorer la production","situation":"Une coopérative de Mbalmayo possède un plant de manioc très productif et résistant à la mosaïque.","tache":"Propose comment le multiplier sans perdre ses qualités."},"verrou":true,"nq":4,"labo":true});
VRT_L("1re-d-svt-r12",{"duree":20,"titre":"Le renouvellement permanent des molécules","accroche":"Nos protéines se refont sans cesse.","intro":"Les molécules de la cellule sont constamment détruites et resynthétisées.","objectifs":["définir le renouvellement moléculaire","interpréter une expérience de marquage","citer les molécules organiques"],"parties":[{"t":"Définition","html":"<div class='def'><b>Définition</b>Le <strong>renouvellement moléculaire</strong> est la destruction et la synthèse permanentes des molécules de la cellule : glucides, lipides, protides, acides nucléiques.</div>"},{"t":"Marquage","verrou":true},{"t":"Intérêt","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"svt","rang":12,"apc":{"module":"Identité biologique, code génétique et enzymes","famille":"Recherche d'un meilleur équilibre de vie","agir":"Exploiter les connaissances sur la cellule et les gènes pour améliorer la production","situation":"Une infirmière de Ngaoundéré explique qu'un enfant mal nourri cicatrise lentement.","tache":"Relie cette observation au renouvellement moléculaire."},"verrou":true,"nq":4,"labo":true});
VRT_L("1re-d-svt-r13",{"duree":20,"titre":"TP 5 : tests des molécules organiques","accroche":"Eau iodée, Fehling, biuret.","intro":"Cette séance de travaux pratiques met en œuvre la démarche expérimentale : protocole, observation, interprétation et compte rendu.","objectifs":["suivre un protocole","observer et schématiser","interpréter un résultat"],"parties":[{"t":"Le but","html":"<div class='def'><b>Définition</b>Des <strong>réactifs</strong> mettent en évidence les molécules organiques des aliments et des cellules.</div>"},{"t":"Matériel et protocole","verrou":true},{"t":"Observation et sécurité","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"svt","rang":13,"apc":{"module":"Identité biologique, code génétique et enzymes","famille":"Recherche d'un meilleur équilibre de vie","agir":"Exploiter les connaissances sur la cellule et les gènes pour améliorer la production","situation":"Une ménagère de Bafoussam veut savoir si sa pâte d'arachide contient surtout des lipides.","tache":"Propose un test simple."},"verrou":true,"nq":4,"labo":true});
VRT_L("1re-d-svt-r14",{"duree":20,"titre":"Biosynthèse des protéines : la transcription","accroche":"Copier un gène en ARN messager.","intro":"La transcription produit dans le noyau une copie d'un gène : l'ARN messager.","objectifs":["définir la transcription","décrire son mécanisme","écrire un ARNm"],"parties":[{"t":"Définition","html":"<div class='def'><b>Définition</b>La <strong>transcription</strong> est la synthèse d'un ARN messager à partir d'un brin d'ADN, dans le noyau, par l'ARN polymérase.</div>"},{"t":"Complémentarité","verrou":true},{"t":"Sortie","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"svt","rang":14,"apc":{"module":"Identité biologique, code génétique et enzymes","famille":"Recherche d'un meilleur équilibre de vie","agir":"Exploiter les connaissances sur la cellule et les gènes pour améliorer la production","situation":"Pour une maquette au lycée de Kumba, un élève doit transcrire le brin TACGGATTC.","tache":"Écris l'ARNm correspondant."},"verrou":true,"nq":4,"labo":true});
