VRT_L("1re-d-svt-r16",{"duree":20,"titre":"Biosynthèse des protéines : la traduction","accroche":"Lire l'ARN trois lettres à la fois.","intro":"Au niveau des ribosomes, la séquence de l'ARNm est traduite en une chaîne d'acides aminés.","objectifs":["définir codon et anticodon","utiliser le code génétique","décrire les étapes"],"parties":[{"t":"Définition","html":"<div class='def'><b>Définition</b>La <strong>traduction</strong> est la synthèse d'une protéine à partir de l'ARNm, au niveau des ribosomes, grâce aux ARN de transfert.</div>"},{"t":"Le code génétique","verrou":true},{"t":"Les étapes","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"svt","rang":16,"apc":{"module":"Identité biologique, code génétique et enzymes","famille":"Recherche d'un meilleur équilibre de vie","agir":"Exploiter les connaissances sur la cellule et les gènes pour améliorer la production","situation":"Un sujet de Probatoire donne un ARNm et un tableau du code génétique.","tache":"Indique la méthode pour trouver la protéine."},"verrou":true,"nq":4,"labo":true});
VRT_L("1re-d-svt-r17",{"duree":20,"titre":"TP 7 : maquette de la traduction","accroche":"Un ribosome en carton.","intro":"Cette séance de travaux pratiques met en œuvre la démarche expérimentale : protocole, observation, interprétation et compte rendu.","objectifs":["suivre un protocole","observer et schématiser","interpréter un résultat"],"parties":[{"t":"Le but","html":"<div class='def'><b>Définition</b>Modéliser la <strong>traduction</strong> : ribosome, ARNm, ARNt et chaîne d'acides aminés.</div>"},{"t":"Matériel et protocole","verrou":true},{"t":"Observation et sécurité","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"svt","rang":17,"apc":{"module":"Identité biologique, code génétique et enzymes","famille":"Recherche d'un meilleur équilibre de vie","agir":"Exploiter les connaissances sur la cellule et les gènes pour améliorer la production","situation":"Un élève de Garoua termine sa maquette au premier codon UAA rencontré.","tache":"A-t-il raison ?"},"verrou":true,"nq":4,"labo":true});
VRT_L("1re-d-svt-r18",{"duree":20,"titre":"Le devenir des protéines synthétisées","accroche":"Du ribosome à l'extérieur de la cellule.","intro":"Les protéines sécrétées suivent un trajet précis dans la cellule.","objectifs":["décrire le trajet des protéines sécrétées","citer des exemples","interpréter une expérience de marquage"],"parties":[{"t":"Le trajet","html":"<div class='def'><b>Définition</b>Les <strong>protéines sécrétées</strong> passent du réticulum endoplasmique granuleux à l'appareil de Golgi, puis sont libérées par exocytose.</div>"},{"t":"Exemples","verrou":true},{"t":"Marquage","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"svt","rang":18,"apc":{"module":"Identité biologique, code génétique et enzymes","famille":"Recherche d'un meilleur équilibre de vie","agir":"Exploiter les connaissances sur la cellule et les gènes pour améliorer la production","situation":"Un document de Probatoire montre la radioactivité successive du REG, du Golgi puis des vésicules d'une cellule pancréatique.","tache":"Interprète-le."},"verrou":true,"nq":4,"labo":true});
VRT_L("1re-d-svt-r19",{"duree":20,"titre":"Intégration : du gène à la maladie","accroche":"La drépanocytose expliquée par la biosynthèse.","intro":"Une mutation modifie l'ARNm, puis la protéine, puis le caractère.","objectifs":["mobiliser transcription et traduction","expliquer une maladie génétique","sensibiliser"],"parties":[{"t":"Notion","html":"<div class='def'><b>Définition</b>Une <strong>mutation</strong> d'un gène peut changer un codon, donc un acide aminé, donc la forme et la fonction de la protéine.</div>"},{"t":"La drépanocytose","verrou":true},{"t":"Production","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"svt","rang":19,"apc":{"module":"Identité biologique, code génétique et enzymes","famille":"Recherche d'un meilleur équilibre de vie","agir":"Exploiter les connaissances sur la cellule et les gènes pour améliorer la production","situation":"Une association de Douala organise une journée de dépistage de la drépanocytose.","tache":"Rédige un texte d'information expliquant le lien entre gène et maladie."},"verrou":true,"nq":4,"labo":true});
VRT_L("1re-d-svt-r20",{"duree":20,"titre":"Génie génétique : les plantes transgéniques","accroche":"Un gène venu d'ailleurs.","intro":"Le génie génétique transfère un gène d'un organisme à un autre pour lui donner un caractère nouveau.","objectifs":["définir un OGM","citer des caractéristiques","discuter des enjeux"],"parties":[{"t":"Définition","html":"<div class='def'><b>Définition</b>Un <strong>organisme génétiquement modifié</strong> (OGM) a reçu un gène étranger, le <strong>transgène</strong>, qui lui confère un caractère nouveau.</div>"},{"t":"Exemples","verrou":true},{"t":"Enjeux","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"svt","rang":20,"apc":{"module":"Identité biologique, code génétique et enzymes","famille":"Recherche d'un meilleur équilibre de vie","agir":"Exploiter les connaissances sur la cellule et les gènes pour améliorer la production","situation":"Dans un débat à la radio de Maroua, des cultivateurs discutent d'un coton résistant aux insectes.","tache":"Présente un avantage et une précaution."},"verrou":true,"nq":4,"labo":true});
VRT_L("1re-d-svt-r21",{"duree":20,"titre":"Génie génétique : obtenir une plante transgénique","accroche":"Une bactérie comme taxi.","intro":"Une bactérie du sol, Agrobacterium, sert de vecteur pour introduire un gène dans une plante.","objectifs":["citer les outils","décrire les étapes","expliquer le rôle du vecteur"],"parties":[{"t":"Les outils","html":"<div class='def'><b>Définition</b>Les <strong>enzymes de restriction</strong> coupent l'ADN à des sites précis ; la <strong>ligase</strong> recolle les fragments ; le <strong>plasmide Ti</strong> d'Agrobacterium sert de vecteur.</div>"},{"t":"Les étapes","verrou":true},{"t":"Contrôle","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"svt","rang":21,"apc":{"module":"Identité biologique, code génétique et enzymes","famille":"Recherche d'un meilleur équilibre de vie","agir":"Exploiter les connaissances sur la cellule et les gènes pour améliorer la production","situation":"Un chercheur d'un institut agronomique de Yaoundé veut introduire un gène de résistance dans une variété de cacaoyer.","tache":"Présente les étapes de la technique."},"verrou":true,"nq":4,"labo":true});
