VRT_L("1re-d-svt-r23",{"duree":20,"titre":"Intégration : un OGM pour nos champs ?","accroche":"Débattre avec des arguments scientifiques.","intro":"Le génie génétique soulève des espoirs et des inquiétudes : il faut argumenter.","objectifs":["présenter la technique","peser avantages et risques","proposer une position argumentée"],"parties":[{"t":"Notion","html":"<div class='def'><b>Définition</b>La <strong>biosécurité</strong> regroupe les règles qui encadrent l'utilisation des OGM pour protéger la santé et l'environnement.</div>"},{"t":"Arguments","verrou":true},{"t":"Production","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"svt","rang":23,"apc":{"module":"Identité biologique, code génétique et enzymes","famille":"Recherche d'un meilleur équilibre de vie","agir":"Exploiter les connaissances sur la cellule et les gènes pour améliorer la production","situation":"Un groupement paysan de l'Extrême-Nord hésite à adopter un coton transgénique.","tache":"Rédige un texte argumenté pour l'éclairer."},"verrou":true,"nq":4,"labo":true});
VRT_L("1re-d-svt-r24",{"duree":20,"titre":"Équipement enzymatique et réactions cellulaires","accroche":"Chaque réaction a son enzyme.","intro":"Les réactions chimiques de la cellule sont catalysées par des enzymes spécifiques.","objectifs":["définir une enzyme","relier équipement enzymatique et métabolisme","expliquer une intolérance"],"parties":[{"t":"Définition","html":"<div class='def'><b>Définition</b>Une <strong>enzyme</strong> est une protéine qui accélère une réaction chimique sans être consommée : c'est un <strong>biocatalyseur</strong>.</div>"},{"t":"Équipement enzymatique","verrou":true},{"t":"Déficit","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"svt","rang":24,"apc":{"module":"Identité biologique, code génétique et enzymes","famille":"Recherche d'un meilleur équilibre de vie","agir":"Exploiter les connaissances sur la cellule et les gènes pour améliorer la production","situation":"Un élève de Bamenda a des ballonnements chaque fois qu'il boit du lait.","tache":"Propose une explication."},"verrou":true,"nq":4,"labo":true});
VRT_L("1re-d-svt-r25",{"duree":20,"titre":"Caractéristiques de l'activité enzymatique","accroche":"Spécifique, sensible à la chaleur et au pH.","intro":"L'activité d'une enzyme dépend du substrat, de la température et du pH.","objectifs":["définir la spécificité","décrire l'effet de la température","décrire l'effet du pH"],"parties":[{"t":"Spécificité","html":"<div class='def'><b>Définition</b>Une enzyme a une <strong>double spécificité</strong> : de substrat (elle reconnaît une molécule) et d'action (elle catalyse une réaction précise).</div>"},{"t":"Température","verrou":true},{"t":"pH","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"svt","rang":25,"apc":{"module":"Identité biologique, code génétique et enzymes","famille":"Recherche d'un meilleur équilibre de vie","agir":"Exploiter les connaissances sur la cellule et les gènes pour améliorer la production","situation":"Une vendeuse de Kumba garde ses fruits au réfrigérateur pour qu'ils mûrissent moins vite.","tache":"Explique le principe."},"verrou":true,"nq":4,"labo":true});
