VRT_L("1re-d-svt-r29",{"duree":20,"titre":"Applications de la catalyse enzymatique dans l'agroalimentaire","accroche":"Pain, bière, fromage, jus.","intro":"Les enzymes et les micro-organismes transforment les aliments.","objectifs":["citer des applications","expliquer leur principe","respecter l'hygiène"],"parties":[{"t":"Définition","html":"<div class='def'><b>Définition</b>Les <strong>biotechnologies alimentaires</strong> utilisent des enzymes ou des micro-organismes pour transformer des matières premières.</div>"},{"t":"Exemples","verrou":true},{"t":"Conditions","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"svt","rang":29,"apc":{"module":"Identité biologique, code génétique et enzymes","famille":"Recherche d'un meilleur équilibre de vie","agir":"Exploiter les connaissances sur la cellule et les gènes pour améliorer la production","situation":"Une brasseuse de bil-bil de Maroua fait germer le sorgho avant de préparer sa boisson.","tache":"Explique l'intérêt de la germination."},"verrou":true,"nq":4,"labo":true});
VRT_L("1re-d-svt-r30",{"duree":20,"titre":"Intégration : améliorer une production artisanale","accroche":"Des enzymes au service d'une coopérative.","intro":"Une transformation artisanale réussit mieux quand on maîtrise les conditions de l'activité enzymatique.","objectifs":["mobiliser les caractéristiques des enzymes","proposer des améliorations","rédiger un protocole"],"parties":[{"t":"Notion","html":"<div class='def'><b>Définition</b>L'activité d'une enzyme est maximale à sa <strong>température et à son pH optimaux</strong> ; la chaleur excessive la détruit.</div>"},{"t":"Démarche","verrou":true},{"t":"Production","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"svt","rang":30,"apc":{"module":"Identité biologique, code génétique et enzymes","famille":"Recherche d'un meilleur équilibre de vie","agir":"Exploiter les connaissances sur la cellule et les gènes pour améliorer la production","situation":"Une coopérative de Garoua produit du bil-bil de qualité irrégulière.","tache":"Propose un protocole amélioré en quatre étapes."},"verrou":true,"nq":4,"labo":true});
VRT_L("1re-d-svt-r31",{"duree":20,"titre":"Évaluer la dépense énergétique","accroche":"Combien d'énergie dépense ton corps ?","intro":"La dépense énergétique se mesure par la chaleur produite ou par le dioxygène consommé.","objectifs":["définir la dépense énergétique","utiliser le coefficient thermique de l'O₂","calculer le quotient respiratoire"],"parties":[{"t":"Définition","html":"<div class='def'><b>Définition</b>La <strong>dépense énergétique</strong> est la quantité d'énergie utilisée par l'organisme par unité de temps. On l'évalue par <strong>calorimétrie directe</strong> (chaleur) ou <strong>indirecte</strong> (dioxygène consommé).</div>"},{"t":"Calcul","verrou":true},{"t":"Quotient respiratoire","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"svt","rang":31,"apc":{"module":"Énergétique biologique et écosystèmes","famille":"Recherche d'un meilleur équilibre de vie","agir":"Améliorer la production d'énergie par l'organisme et préserver les écosystèmes","situation":"Un entraîneur de Garoua mesure qu'un athlète consomme 120 L de dioxygène en une heure d'effort.","tache":"Calcule sa dépense énergétique."},"verrou":true,"nq":4,"labo":true});
VRT_L("1re-d-svt-r32",{"duree":20,"titre":"TP 13 : intensité respiratoire d'un mammifère","accroche":"Un respiromètre et une souris.","intro":"Cette séance de travaux pratiques met en œuvre la démarche expérimentale : protocole, observation, interprétation et compte rendu.","objectifs":["suivre un protocole","observer et mesurer","interpréter un résultat"],"parties":[{"t":"Le but","html":"<div class='def'><b>Définition</b>L'<strong>intensité respiratoire</strong> est le volume de dioxygène consommé par unité de masse et de temps.</div>"},{"t":"Matériel et protocole","verrou":true},{"t":"Observation et sécurité","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"svt","rang":32,"apc":{"module":"Énergétique biologique et écosystèmes","famille":"Recherche d'un meilleur équilibre de vie","agir":"Améliorer la production d'énergie par l'organisme et préserver les écosystèmes","situation":"Au laboratoire d'un lycée de Dschang, une souris de 20 g consomme 12 mL d'O₂ en 10 minutes.","tache":"Calcule son intensité respiratoire."},"verrou":true,"nq":4,"labo":true});
VRT_L("1re-d-svt-r33",{"duree":20,"titre":"Facteurs de variation de la dépense énergétique","accroche":"Effort, froid, croissance.","intro":"La dépense énergétique varie selon l'activité et l'état de l'organisme.","objectifs":["citer les facteurs","interpréter un tableau","adapter la ration"],"parties":[{"t":"Définition","html":"<div class='def'><b>Définition</b>La <strong>dépense énergétique</strong> totale comprend le métabolisme de base et les dépenses liées à l'activité, à la thermorégulation, à la croissance et à la digestion.</div>"},{"t":"Facteurs","verrou":true},{"t":"Conséquence","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"svt","rang":33,"apc":{"module":"Énergétique biologique et écosystèmes","famille":"Recherche d'un meilleur équilibre de vie","agir":"Améliorer la production d'énergie par l'organisme et préserver les écosystèmes","situation":"Un docker du port de Douala et un employé de bureau mangent la même ration.","tache":"Lequel risque un déficit énergétique ? Justifie."},"verrou":true,"nq":4,"labo":true});
VRT_L("1re-d-svt-r34",{"duree":20,"titre":"Le métabolisme de base","accroche":"L'énergie dépensée sans rien faire.","intro":"Même au repos complet, l'organisme dépense de l'énergie pour vivre.","objectifs":["définir le métabolisme de base","connaître les conditions de mesure","citer des valeurs"],"parties":[{"t":"Définition","html":"<div class='def'><b>Définition</b>Le <strong>métabolisme de base</strong> est la dépense énergétique minimale d'un sujet au repos, à jeun depuis 12 h, à la neutralité thermique et éveillé.</div>"},{"t":"Valeurs","verrou":true},{"t":"Utilité","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"svt","rang":34,"apc":{"module":"Énergétique biologique et écosystèmes","famille":"Recherche d'un meilleur équilibre de vie","agir":"Améliorer la production d'énergie par l'organisme et préserver les écosystèmes","situation":"Un médecin de Yaoundé mesure le métabolisme de base d'un patient soupçonné de trouble thyroïdien.","tache":"Indique les conditions de mesure."},"verrou":true,"nq":4,"labo":true});
VRT_L("1re-d-svt-r35",{"duree":20,"titre":"Les apports énergétiques des repas","accroche":"17, 38, 17 : les nombres de l'énergie.","intro":"L'énergie des aliments se calcule à partir de leur composition en nutriments.","objectifs":["connaître les valeurs énergétiques","calculer l'apport d'un repas","comparer apport et dépense"],"parties":[{"t":"Valeurs","html":"<div class='def'><b>Définition</b>La <strong>valeur énergétique</strong> d'un nutriment est l'énergie libérée par 1 g : glucides 17 kJ/g, lipides 38 kJ/g, protides 17 kJ/g.</div>"},{"t":"Calcul","verrou":true},{"t":"Équilibre","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"svt","rang":35,"apc":{"module":"Énergétique biologique et écosystèmes","famille":"Recherche d'un meilleur équilibre de vie","agir":"Améliorer la production d'énergie par l'organisme et préserver les écosystèmes","situation":"Un élève de Limbé mange au déjeuner 150 g de riz cuit (40 g de glucides), 20 g d'huile et 30 g de poisson (protides).","tache":"Calcule l'énergie apportée."},"verrou":true,"nq":4,"labo":true});
VRT_L("1re-d-svt-r36",{"duree":20,"titre":"Dépenses énergétiques de la respiration","accroche":"Brûler le glucose avec le dioxygène.","intro":"La respiration cellulaire oxyde complètement le glucose et libère beaucoup d'énergie.","objectifs":["écrire l'équation de la respiration","relier énergie et ATP","citer les conditions"],"parties":[{"t":"Définition","html":"<div class='def'><b>Définition</b>La <strong>respiration cellulaire</strong> est l'oxydation complète des métabolites (glucose) en présence de dioxygène : C₆H₁₂O₆ + 6O₂ → 6CO₂ + 6H₂O + énergie.</div>"},{"t":"Énergie","verrou":true},{"t":"ATP","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"svt","rang":36,"apc":{"module":"Énergétique biologique et écosystèmes","famille":"Recherche d'un meilleur équilibre de vie","agir":"Améliorer la production d'énergie par l'organisme et préserver les écosystèmes","situation":"Un sportif de Bamenda demande pourquoi il respire plus vite pendant l'effort.","tache":"Explique-le."},"verrou":true,"nq":4,"labo":true});
VRT_L("1re-d-svt-r37",{"duree":20,"titre":"TP 14 : mise en évidence de la respiration","accroche":"L'eau de chaux se trouble.","intro":"Cette séance de travaux pratiques met en œuvre la démarche expérimentale : protocole, observation, interprétation et compte rendu.","objectifs":["suivre un protocole","observer et mesurer","interpréter un résultat"],"parties":[{"t":"Le but","html":"<div class='def'><b>Définition</b>Montrer qu'un être vivant <strong>consomme du dioxygène</strong> et <strong>rejette du dioxyde de carbone</strong>.</div>"},{"t":"Matériel et protocole","verrou":true},{"t":"Observation et sécurité","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"svt","rang":37,"apc":{"module":"Énergétique biologique et écosystèmes","famille":"Recherche d'un meilleur équilibre de vie","agir":"Améliorer la production d'énergie par l'organisme et préserver les écosystèmes","situation":"Au lycée de Mbalmayo, un groupe oublie le bocal témoin.","tache":"Pourquoi le résultat est-il discutable ?"},"verrou":true,"nq":4,"labo":true});
VRT_L("1re-d-svt-r38",{"duree":20,"titre":"Mécanisme et localisation de la respiration","accroche":"Du cytoplasme à la mitochondrie.","intro":"La respiration se déroule en trois grandes étapes dans deux compartiments de la cellule.","objectifs":["décrire la glycolyse","décrire le cycle de Krebs","localiser la chaîne respiratoire"],"parties":[{"t":"Les étapes","html":"<div class='def'><b>Définition</b>La respiration comprend la <strong>glycolyse</strong> (cytoplasme : glucose → 2 pyruvates + 2 ATP), le <strong>cycle de Krebs</strong> (matrice mitochondriale : CO₂ libéré) et la <strong>chaîne respiratoire</strong> (membrane interne : O₂ consommé, ATP produit).</div>"},{"t":"Localisation","verrou":true},{"t":"Bilan","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"svt","rang":38,"apc":{"module":"Énergétique biologique et écosystèmes","famille":"Recherche d'un meilleur équilibre de vie","agir":"Améliorer la production d'énergie par l'organisme et préserver les écosystèmes","situation":"Un document de Probatoire montre que des mitochondries isolées consomment de l'O₂ avec du pyruvate, mais pas avec du glucose.","tache":"Interprète."},"verrou":true,"nq":4,"labo":true});
VRT_L("1re-d-svt-r39",{"duree":20,"titre":"Dépenses énergétiques de la fermentation","accroche":"Sans dioxygène, un peu d'énergie quand même.","intro":"La fermentation dégrade incomplètement le glucose en l'absence de dioxygène.","objectifs":["écrire la fermentation alcoolique","comparer l'énergie libérée","citer les produits"],"parties":[{"t":"Définition","html":"<div class='def'><b>Définition</b>La <strong>fermentation</strong> est une dégradation incomplète du glucose sans dioxygène. Alcoolique : C₆H₁₂O₆ → 2C₂H₅OH + 2CO₂ + énergie.</div>"},{"t":"Énergie","verrou":true},{"t":"Exemples","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"svt","rang":39,"apc":{"module":"Énergétique biologique et écosystèmes","famille":"Recherche d'un meilleur équilibre de vie","agir":"Améliorer la production d'énergie par l'organisme et préserver les écosystèmes","situation":"Une productrice de vin de palme de Bandjoun constate que la sève mousse et devient alcoolisée en quelques heures.","tache":"Explique ce phénomène."},"verrou":true,"nq":4,"labo":true});
VRT_L("1re-d-svt-r40",{"duree":20,"titre":"TP 15 : mise en évidence des fermentations","accroche":"Mousse, odeur d'alcool, goût de vinaigre.","intro":"Cette séance de travaux pratiques met en œuvre la démarche expérimentale : protocole, observation, interprétation et compte rendu.","objectifs":["suivre un protocole","observer et mesurer","interpréter un résultat"],"parties":[{"t":"Le but","html":"<div class='def'><b>Définition</b>Mettre en évidence les <strong>fermentations alcoolique et acétique</strong> et leurs produits.</div>"},{"t":"Matériel et protocole","verrou":true},{"t":"Observation et sécurité","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"svt","rang":40,"apc":{"module":"Énergétique biologique et écosystèmes","famille":"Recherche d'un meilleur équilibre de vie","agir":"Améliorer la production d'énergie par l'organisme et préserver les écosystèmes","situation":"Au club scientifique de Bafang, l'eau de chaux ne se trouble pas.","tache":"Propose deux causes possibles."},"verrou":true,"nq":4,"labo":true});
VRT_L("1re-d-svt-r41",{"duree":20,"titre":"TP : boissons fermentées, vinaigre et biogaz","accroche":"Trois productions locales.","intro":"Cette séance de travaux pratiques met en œuvre la démarche expérimentale : protocole, observation, interprétation et compte rendu.","objectifs":["suivre un protocole","observer et mesurer","interpréter un résultat"],"parties":[{"t":"Le but","html":"<div class='def'><b>Définition</b>Réaliser des <strong>productions utiles</strong> grâce aux fermentations : boisson, vinaigre, biogaz.</div>"},{"t":"Matériel et protocole","verrou":true},{"t":"Observation et sécurité","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"svt","rang":41,"apc":{"module":"Énergétique biologique et écosystèmes","famille":"Recherche d'un meilleur équilibre de vie","agir":"Améliorer la production d'énergie par l'organisme et préserver les écosystèmes","situation":"Un éleveur de porcs de Mbouda veut valoriser le lisier de sa porcherie.","tache":"Propose une production et son principe."},"verrou":true,"nq":4,"labo":true});
VRT_L("1re-d-svt-r42",{"duree":20,"titre":"Mécanismes et localisation de la fermentation","accroche":"Tout se passe dans le cytoplasme.","intro":"La fermentation commence comme la respiration, par la glycolyse, mais s'arrête dans le cytoplasme.","objectifs":["décrire les étapes","localiser la fermentation","comparer les types de fermentation"],"parties":[{"t":"Mécanisme","html":"<div class='def'><b>Définition</b>La <strong>fermentation</strong> comprend la glycolyse (glucose → 2 pyruvates + 2 ATP), puis la transformation du pyruvate en éthanol et CO₂ (alcoolique) ou en lactate (lactique), dans le <strong>cytoplasme</strong>.</div>"},{"t":"Rôle de la seconde étape","verrou":true},{"t":"Exemples","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"svt","rang":42,"apc":{"module":"Énergétique biologique et écosystèmes","famille":"Recherche d'un meilleur équilibre de vie","agir":"Améliorer la production d'énergie par l'organisme et préserver les écosystèmes","situation":"Une fabricante de yaourts de Ngaoundéré ensemence le lait avec des bactéries lactiques.","tache":"Explique la transformation."},"verrou":true,"nq":4,"labo":true});
VRT_L("1re-d-svt-r43",{"duree":20,"titre":"Comparer respiration et fermentation","accroche":"38 contre 2.","intro":"Respiration et fermentation diffèrent par leurs conditions, leurs produits et leur rendement.","objectifs":["comparer les deux voies","calculer les rendements","expliquer la différence"],"parties":[{"t":"Comparaison","html":"<div class='def'><b>Définition</b>La <strong>respiration</strong> est une oxydation complète en présence d'O₂ (38 ATP, rendement environ 40 %) ; la <strong>fermentation</strong> est une dégradation incomplète sans O₂ (2 ATP, rendement environ 2 %).</div>"},{"t":"Explication","verrou":true},{"t":"Conséquence","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"svt","rang":43,"apc":{"module":"Énergétique biologique et écosystèmes","famille":"Recherche d'un meilleur équilibre de vie","agir":"Améliorer la production d'énergie par l'organisme et préserver les écosystèmes","situation":"Un boulanger de Yaoundé laisse sa pâte lever dans un récipient fermé.","tache":"Explique pourquoi la pâte gonfle et pourquoi elle ne s'arrête pas aussitôt."},"verrou":true,"nq":4,"labo":true});
VRT_L("1re-d-svt-r44",{"duree":20,"titre":"Intégration : jus de canne et bâton de manioc","accroche":"Un sujet du Probatoire 2026.","intro":"Une unité locale veut comprendre pourquoi le jus de canne fermente plus vite que le manioc non traité.","objectifs":["mobiliser fermentation et digestion des glucides","proposer des améliorations","rédiger un protocole"],"parties":[{"t":"Notion","html":"<div class='def'><b>Définition</b>Les levures fermentent directement les sucres simples ; les <strong>sucres complexes</strong> (amidon) doivent d'abord être hydrolysés par des enzymes.</div>"},{"t":"Réponse attendue","verrou":true},{"t":"Bâton de manioc","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"svt","rang":44,"apc":{"module":"Énergétique biologique et écosystèmes","famille":"Recherche d'un meilleur équilibre de vie","agir":"Améliorer la production d'énergie par l'organisme et préserver les écosystèmes","situation":"Une unité locale produit des boissons à base de jus de canne et constate que le manioc non traité fermente beaucoup plus lentement.","tache":"Rédige un texte d'une dizaine de lignes expliquant cette différence et propose deux aménagements."},"verrou":true,"nq":4,"labo":true});
VRT_L("1re-d-svt-r45",{"duree":20,"titre":"Le captage de l'énergie lumineuse","accroche":"La chlorophylle absorbe le bleu et le rouge.","intro":"Les pigments chlorophylliens captent la lumière utilisée par la photosynthèse.","objectifs":["citer les pigments","lire un spectre d'absorption","extraire la chlorophylle"],"parties":[{"t":"Pigments","html":"<div class='def'><b>Définition</b>Les <strong>pigments chlorophylliens</strong> (chlorophylles a et b, caroténoïdes), situés dans les thylakoïdes des chloroplastes, absorbent l'énergie lumineuse.</div>"},{"t":"Spectre","verrou":true},{"t":"Extraction","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"svt","rang":45,"apc":{"module":"Énergétique biologique et écosystèmes","famille":"Recherche d'un meilleur équilibre de vie","agir":"Améliorer la production d'énergie par l'organisme et préserver les écosystèmes","situation":"Un maraîcher de Foumbot cultive des légumes sous des filets verts.","tache":"Explique pourquoi un filet vert est un mauvais choix."},"verrou":true,"nq":4,"labo":true});
VRT_L("1re-d-svt-r46",{"duree":20,"titre":"Photosynthèse : la phase chimique","accroche":"Fabriquer du sucre avec le CO₂.","intro":"Dans le stroma, le CO₂ est incorporé dans des molécules organiques.","objectifs":["décrire le cycle de Calvin","localiser la phase chimique","relier aux deux phases"],"parties":[{"t":"Définition","html":"<div class='def'><b>Définition</b>La <strong>phase chimique</strong> (cycle de Calvin), dans le stroma du chloroplaste, fixe le CO₂ sur un accepteur (le ribulose diphosphate) grâce à une enzyme, la RubisCO, et produit des glucides.</div>"},{"t":"Besoins","verrou":true},{"t":"Preuve","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"svt","rang":46,"apc":{"module":"Énergétique biologique et écosystèmes","famille":"Recherche d'un meilleur équilibre de vie","agir":"Améliorer la production d'énergie par l'organisme et préserver les écosystèmes","situation":"Dans un sujet, on fournit du CO₂ marqué à des algues, puis on éteint la lumière.","tache":"Prévois l'évolution de la fixation du CO₂."},"verrou":true,"nq":4,"labo":true});
VRT_L("1re-d-svt-r47",{"duree":20,"titre":"Photosynthèse : la phase photochimique","accroche":"La lumière casse l'eau.","intro":"Dans les thylakoïdes, l'énergie lumineuse est convertie en énergie chimique.","objectifs":["décrire la photolyse de l'eau","localiser la phase photochimique","expliquer l'origine de l'O₂"],"parties":[{"t":"Définition","html":"<div class='def'><b>Définition</b>La <strong>phase photochimique</strong>, dans les thylakoïdes, utilise la lumière pour oxyder l'eau (<strong>photolyse</strong>) : elle libère du dioxygène et produit de l'ATP et du NADPH,H⁺.</div>"},{"t":"Origine de l'O₂","verrou":true},{"t":"Lien","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"svt","rang":47,"apc":{"module":"Énergétique biologique et écosystèmes","famille":"Recherche d'un meilleur équilibre de vie","agir":"Améliorer la production d'énergie par l'organisme et préserver les écosystèmes","situation":"Un élève de Dschang éclaire une plante aquatique (élodée) et voit des bulles se dégager.","tache":"Identifie le gaz et son origine."},"verrou":true,"nq":4,"labo":true});
VRT_L("1re-d-svt-r48",{"duree":20,"titre":"Importance de la photosynthèse","accroche":"Toute la nourriture commence par une feuille.","intro":"La photosynthèse fournit la matière organique et le dioxygène dont dépend presque toute la vie.","objectifs":["écrire l'équation globale","expliquer son importance","relier au programme génétique"],"parties":[{"t":"Équation","html":"<div class='def'><b>Définition</b>La <strong>photosynthèse</strong> : 6CO₂ + 12H₂O → C₆H₁₂O₆ + 6O₂ + 6H₂O, grâce à l'énergie lumineuse captée par la chlorophylle.</div>"},{"t":"Importance","verrou":true},{"t":"Programme génétique","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"svt","rang":48,"apc":{"module":"Énergétique biologique et écosystèmes","famille":"Recherche d'un meilleur équilibre de vie","agir":"Améliorer la production d'énergie par l'organisme et préserver les écosystèmes","situation":"La forêt du bassin du Congo, dont une partie couvre l'Est du Cameroun, est menacée par la déforestation.","tache":"Explique son importance pour l'atmosphère."},"verrou":true,"nq":4,"labo":true});
VRT_L("1re-d-svt-r49",{"duree":20,"titre":"Intégration : réussir une culture sous serre","accroche":"Lumière, CO₂, eau.","intro":"Un maraîcher veut améliorer le rendement de ses tomates en jouant sur les facteurs de la photosynthèse.","objectifs":["identifier les facteurs limitants","proposer des aménagements","argumenter"],"parties":[{"t":"Notion","html":"<div class='def'><b>Définition</b>Un <strong>facteur limitant</strong> est le facteur qui, en quantité insuffisante, limite l'intensité de la photosynthèse.</div>"},{"t":"Facteurs","verrou":true},{"t":"Production","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"svt","rang":49,"apc":{"module":"Énergétique biologique et écosystèmes","famille":"Recherche d'un meilleur équilibre de vie","agir":"Améliorer la production d'énergie par l'organisme et préserver les écosystèmes","situation":"Un maraîcher de Foumbot constate des rendements faibles dans sa serre de tomates mal éclairée et peu aérée.","tache":"Propose des aménagements argumentés."},"verrou":true,"nq":4,"labo":true});
VRT_L("1re-d-svt-r50",{"duree":20,"titre":"Organisation d'un écosystème","accroche":"Qui mange qui dans la forêt ?","intro":"Un écosystème associe des êtres vivants et leur milieu de vie.","objectifs":["définir écosystème, biotope, biocénose","classer les êtres vivants","construire une chaîne alimentaire"],"parties":[{"t":"Définitions","html":"<div class='def'><b>Définition</b>Un <strong>écosystème</strong> est formé d'un <strong>biotope</strong> (milieu physique) et d'une <strong>biocénose</strong> (êtres vivants) en interaction.</div>"},{"t":"Niveaux trophiques","verrou":true},{"t":"Chaînes et réseaux","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"svt","rang":50,"apc":{"module":"Énergétique biologique et écosystèmes","famille":"Recherche d'un meilleur équilibre de vie","agir":"Améliorer la production d'énergie par l'organisme et préserver les écosystèmes","situation":"Au parc national de la Bénoué, des élèves observent herbes, antilopes, lions et vautours.","tache":"Construis une chaîne alimentaire et classe ces êtres vivants."},"verrou":true,"nq":4,"labo":true});
VRT_L("1re-d-svt-r51",{"duree":20,"titre":"Flux et dissipation de l'énergie dans un écosystème","accroche":"Seuls 10 % passent au niveau suivant.","intro":"L'énergie traverse l'écosystème en sens unique et se dissipe à chaque niveau.","objectifs":["décrire le flux d'énergie","calculer un rendement écologique","construire une pyramide"],"parties":[{"t":"Définition","html":"<div class='def'><b>Définition</b>Le <strong>flux d'énergie</strong> part de la lumière captée par les producteurs et passe d'un niveau trophique à l'autre ; à chaque niveau, une grande partie est <strong>dissipée</strong> en chaleur par la respiration.</div>"},{"t":"Rendement","verrou":true},{"t":"Pyramide","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"svt","rang":51,"apc":{"module":"Énergétique biologique et écosystèmes","famille":"Recherche d'un meilleur équilibre de vie","agir":"Améliorer la production d'énergie par l'organisme et préserver les écosystèmes","situation":"Un éleveur de l'Adamaoua se demande pourquoi produire de la viande demande beaucoup plus de surface que produire des céréales.","tache":"Explique avec le flux d'énergie."},"verrou":true,"nq":4,"labo":true});
VRT_L("1re-d-svt-r52",{"duree":20,"titre":"Le cycle naturel du carbone","accroche":"Réservoirs et flux.","intro":"Le carbone circule entre l'atmosphère, les êtres vivants, les océans et les roches.","objectifs":["citer les réservoirs","décrire les flux","construire un schéma du cycle"],"parties":[{"t":"Définition","html":"<div class='def'><b>Définition</b>Le <strong>cycle du carbone</strong> est la circulation du carbone entre des <strong>réservoirs</strong> : atmosphère (CO₂), biomasse, océans, sols, roches carbonatées et combustibles fossiles.</div>"},{"t":"Flux","verrou":true},{"t":"Équilibre","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"svt","rang":52,"apc":{"module":"Énergétique biologique et écosystèmes","famille":"Recherche d'un meilleur équilibre de vie","agir":"Améliorer la production d'énergie par l'organisme et préserver les écosystèmes","situation":"Pour un exposé au lycée de Kribi, un élève doit schématiser le cycle du carbone.","tache":"Liste les réservoirs et les flux à représenter."},"verrou":true,"nq":4,"labo":true});
VRT_L("1re-d-svt-r53",{"duree":20,"titre":"Les modifications du cycle du carbone par l'Homme","accroche":"Trop de CO₂ dans l'air.","intro":"Les activités humaines libèrent du carbone stocké depuis des millions d'années.","objectifs":["citer les activités en cause","interpréter l'augmentation du CO₂","proposer des solutions"],"parties":[{"t":"Définition","html":"<div class='def'><b>Définition</b>Les activités humaines modifient le <strong>cycle du carbone</strong> en transférant le carbone des réservoirs fossiles et forestiers vers l'atmosphère.</div>"},{"t":"Causes","verrou":true},{"t":"Conséquences","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"svt","rang":53,"apc":{"module":"Énergétique biologique et écosystèmes","famille":"Recherche d'un meilleur équilibre de vie","agir":"Améliorer la production d'énergie par l'organisme et préserver les écosystèmes","situation":"Dans l'Adamaoua, les feux de brousse brûlent chaque année de grandes surfaces.","tache":"Explique leur effet sur le cycle du carbone et propose des mesures."},"verrou":true,"nq":4,"labo":true});
VRT_L("1re-d-svt-r54",{"duree":20,"titre":"Le cycle de l'azote","accroche":"Les haricots enrichissent le sol.","intro":"L'azote passe de l'air au sol puis aux êtres vivants grâce à des micro-organismes.","objectifs":["décrire les étapes","expliquer le rôle des légumineuses","raisonner l'usage des engrais"],"parties":[{"t":"Définition","html":"<div class='def'><b>Définition</b>Le <strong>cycle de l'azote</strong> comprend la fixation de l'azote atmosphérique, la nitrification, l'assimilation par les plantes et la dénitrification.</div>"},{"t":"Fixation","verrou":true},{"t":"Pratique agricole","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"svt","rang":54,"apc":{"module":"Énergétique biologique et écosystèmes","famille":"Recherche d'un meilleur équilibre de vie","agir":"Améliorer la production d'énergie par l'organisme et préserver les écosystèmes","situation":"Un cultivateur de la Lékié constate que son maïs pousse mieux après une saison d'arachide.","tache":"Explique cette observation."},"verrou":true,"nq":4,"labo":true});
VRT_L("1re-d-svt-r55",{"duree":20,"titre":"Intégration : préserver la fertilité et le carbone","accroche":"Jachère, légumineuses, reboisement.","intro":"Une communauté rurale veut nourrir sa population sans épuiser le sol ni détruire la forêt.","objectifs":["mobiliser les cycles du carbone et de l'azote","proposer des pratiques","rédiger un texte et un slogan"],"parties":[{"t":"Notion","html":"<div class='def'><b>Définition</b>Une <strong>agriculture durable</strong> maintient la fertilité du sol et le stock de carbone : rotations avec légumineuses, compost, limitation des feux, reboisement.</div>"},{"t":"Arguments","verrou":true},{"t":"Production","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"svt","rang":55,"apc":{"module":"Énergétique biologique et écosystèmes","famille":"Recherche d'un meilleur équilibre de vie","agir":"Améliorer la production d'énergie par l'organisme et préserver les écosystèmes","situation":"Dans un village de l'Est, les rendements baissent et la forêt recule à cause des feux et de l'agriculture itinérante.","tache":"Rédige un texte argumenté et propose un slogan."},"verrou":true,"nq":4,"labo":true});
VRT_L("1re-d-svt-r56",{"duree":20,"titre":"Le soi","accroche":"Une carte d'identité moléculaire.","intro":"Chaque individu porte à la surface de ses cellules des molécules qui le caractérisent.","objectifs":["définir le soi","citer les marqueurs du soi","expliquer la compatibilité"],"parties":[{"t":"Définition","html":"<div class='def'><b>Définition</b>Le <strong>soi</strong> est l'ensemble des molécules propres à un individu, déterminées par ses gènes, et tolérées par son système immunitaire.</div>"},{"t":"Marqueurs","html":"<p>Les molécules du CMH (système HLA chez l'Homme) sont présentes sur presque toutes les cellules ; les marqueurs des groupes sanguins A, B, O sont sur les hématies.</p>","labo":{"type":"abo"}},{"t":"Compatibilité","html":"<p>Une greffe réussit mieux entre personnes de CMH proches ; une transfusion doit respecter la compatibilité des groupes sanguins.</p>","retenir":"Le soi est génétiquement déterminé."},{"t":"Entraînement au format de l'examen","html":"<div class='integ'><h3>Partie A : évaluation des ressources</h3><p><strong>Évaluation des savoirs (QCM).</strong> Le soi est déterminé :</p><ol type='a'><li>par l'alimentation</li><li>par les gènes</li><li>par le climat</li></ol><details><summary>Voir la réponse</summary><p><strong>par les gènes</strong>. Définition.</p></details><p><strong>Évaluation des savoir-faire.</strong></p><p>Qui est donneur universel de globules rouges ?</p><details><summary>Voir la réponse</summary><p>(Réponse : le groupe O.)</p></details><h3>Partie B : évaluation des compétences</h3><p><strong>Compétence visée.</strong> Lutter contre les problèmes liés à la santé reproductive des jeunes et à la malnutrition.</p><p><strong>Situation.</strong> Mme Ngo, du groupe sanguin B, doit être transfusée à l'hôpital de Bafoussam. Les donneurs disponibles sont des groupes A, B, AB et O.</p><p><strong>Consigne 1.</strong> Explique ce qu'est un marqueur du soi sur les hématies.</p><p><strong>Consigne 2.</strong> Quels donneurs conviennent ? Justifie.</p><details><summary>Voir une réponse attendue</summary><p>Les hématies portent des molécules propres à l'individu (A, B ou aucune), déterminées par ses gènes. Elle a des anticorps anti-A : seuls les donneurs B et O conviennent.</p></details></div>","retenir":"Savoir-être mobilisé : Souci de la santé."}],"revision":["Soi.","CMH, groupes sanguins.","Compatibilité."],"exo":"<p>Qui est donneur universel de globules rouges ? <em>(Réponse : le groupe O.)</em></p>","quiz":[{"q":"Le soi est déterminé :","r":["par l'alimentation","par les gènes","par le climat"],"b":1,"e":"Définition."},{"q":"Le CMH est présent :","r":["sur presque toutes les cellules","seulement sur les virus","dans l'air"],"b":0,"e":"Marqueur."},{"q":"Le groupe O est :","r":["receveur universel","incompatible avec tous","donneur universel de globules rouges"],"b":2,"e":"Transfusion."},{"q":"Une greffe réussit mieux si les CMH sont :","r":["très différents","proches","absents"],"b":1,"e":"Compatibilité."}],"c":"1re D","m":"svt","rang":56,"apc":{"module":"Immunité, santé reproductive et nutrition","famille":"Choix et observation de saines habitudes de vie","agir":"Lutter contre les problèmes liés à la santé reproductive des jeunes et à la malnutrition","situation":"À l'hôpital de district de Mbalmayo, un patient du groupe A a besoin d'une transfusion.","tache":"Quels groupes de donneurs conviennent ? Justifie."},"gratuit":true});
VRT_L("1re-d-svt-r57",{"duree":20,"titre":"Le non-soi","accroche":"Tout ce qui est étranger.","intro":"Le système immunitaire reconnaît et combat ce qui n'appartient pas au soi.","objectifs":["définir le non-soi et l'antigène","citer des exemples","expliquer un rejet"],"parties":[{"t":"Définition","html":"<div class='def'><b>Définition</b>Le <strong>non-soi</strong> regroupe les éléments étrangers reconnus par le système immunitaire : microbes, cellules greffées, cellules modifiées. Une molécule qui déclenche une réaction est un <strong>antigène</strong>.</div>"},{"t":"Exemples","verrou":true},{"t":"Rejet","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"svt","rang":57,"apc":{"module":"Immunité, santé reproductive et nutrition","famille":"Choix et observation de saines habitudes de vie","agir":"Lutter contre les problèmes liés à la santé reproductive des jeunes et à la malnutrition","situation":"Un homme de Bafoussam reçoit un rein de son frère jumeau sans traitement antirejet.","tache":"Explique pourquoi la greffe réussit."},"verrou":true,"nq":4,"labo":true});
VRT_L("1re-d-svt-r58",{"duree":20,"titre":"Les principales cellules immunitaires","accroche":"Une armée aux rôles variés.","intro":"Les cellules immunitaires naissent dans la moelle osseuse et coopèrent pour défendre l'organisme.","objectifs":["citer les cellules","préciser leur rôle","situer leur origine"],"parties":[{"t":"Les cellules","html":"<div class='def'><b>Définition</b>Les <strong>leucocytes</strong> (globules blancs) assurent l'immunité : phagocytes (macrophages, granulocytes), lymphocytes B, lymphocytes T4 et T8.</div>"},{"t":"Rôles","verrou":true},{"t":"Origine","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"svt","rang":58,"apc":{"module":"Immunité, santé reproductive et nutrition","famille":"Choix et observation de saines habitudes de vie","agir":"Lutter contre les problèmes liés à la santé reproductive des jeunes et à la malnutrition","situation":"Un laborantin de Limbé observe un frottis sanguin coloré.","tache":"Comment reconnaître un lymphocyte d'un granulocyte ?"},"verrou":true,"nq":4,"labo":true});
VRT_L("1re-d-svt-r59",{"duree":20,"titre":"Le VIH : contamination et mode d'action","accroche":"Un virus qui détruit les défenseurs.","intro":"Le VIH infecte les lymphocytes T4 et affaiblit progressivement les défenses.","objectifs":["citer les voies de transmission","décrire le cycle du virus","décrire le dépistage"],"parties":[{"t":"Le virus","html":"<div class='def'><b>Définition</b>Le <strong>VIH</strong> est un rétrovirus : son information génétique est un ARN, copié en ADN par la <strong>transcriptase inverse</strong>. Sa protéine gp120 se fixe sur le récepteur CD4 des LT4.</div>"},{"t":"Transmission","verrou":true},{"t":"Cycle et dépistage","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"svt","rang":59,"apc":{"module":"Immunité, santé reproductive et nutrition","famille":"Choix et observation de saines habitudes de vie","agir":"Lutter contre les problèmes liés à la santé reproductive des jeunes et à la malnutrition","situation":"Un jeune de Kousseri craint d'avoir été contaminé en partageant le repas d'une personne séropositive.","tache":"Rassure-le avec des arguments scientifiques."},"verrou":true,"nq":4,"labo":true});
VRT_L("1re-d-svt-r60",{"duree":20,"titre":"Multiplication du VIH, conséquences et lutte","accroche":"Freiner le virus, protéger les autres.","intro":"Le VIH se multiplie dans les LT4 et détruit peu à peu l'immunité ; la lutte associe prévention et traitement.","objectifs":["expliquer la chute des LT4","décrire les conséquences","proposer des moyens de lutte"],"parties":[{"t":"Multiplication","html":"<div class='def'><b>Définition</b>Le VIH se <strong>multiplie</strong> dans les LT4 infectés, qui libèrent de nouveaux virus et meurent : le nombre de LT4 diminue progressivement.</div>"},{"t":"Conséquences","verrou":true},{"t":"Lutte","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"svt","rang":60,"apc":{"module":"Immunité, santé reproductive et nutrition","famille":"Choix et observation de saines habitudes de vie","agir":"Lutter contre les problèmes liés à la santé reproductive des jeunes et à la malnutrition","situation":"Une association de Ngaoundéré prépare une campagne de dépistage dans les marchés.","tache":"Propose trois messages clés."},"verrou":true,"nq":4,"labo":true});
VRT_L("1re-d-svt-r61",{"duree":20,"titre":"Intégration : une campagne contre le VIH au lycée","accroche":"Informer sans faire peur.","intro":"Le club santé veut sensibiliser les élèves au VIH.","objectifs":["mobiliser les connaissances sur le VIH","concevoir une affiche","rédiger un slogan"],"parties":[{"t":"Notion","html":"<div class='def'><b>Définition</b>La <strong>sensibilisation</strong> consiste à informer et à encourager des comportements protecteurs, sans stigmatiser.</div>"},{"t":"Contenu","verrou":true},{"t":"Production","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"svt","rang":61,"apc":{"module":"Immunité, santé reproductive et nutrition","famille":"Choix et observation de saines habitudes de vie","agir":"Lutter contre les problèmes liés à la santé reproductive des jeunes et à la malnutrition","situation":"Le club santé d'un lycée de Bamenda veut organiser une semaine de lutte contre le VIH.","tache":"Rédige un texte de dix lignes et un slogan."},"verrou":true,"nq":4,"labo":true});
VRT_L("1re-d-svt-r62",{"duree":20,"titre":"La sexualité précoce et ses conséquences","accroche":"Trop tôt, trop de risques.","intro":"Une sexualité précoce, souvent non protégée, expose les jeunes à de nombreux risques.","objectifs":["définir la sexualité précoce","citer ses conséquences","proposer des moyens de prévention"],"parties":[{"t":"Définition","html":"<div class='def'><b>Définition</b>La <strong>sexualité précoce</strong> désigne des rapports sexuels chez des adolescents qui ne sont pas encore prêts physiquement, psychologiquement et socialement.</div>"},{"t":"Conséquences","verrou":true},{"t":"Prévention","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"svt","rang":62,"apc":{"module":"Immunité, santé reproductive et nutrition","famille":"Choix et observation de saines habitudes de vie","agir":"Lutter contre les problèmes liés à la santé reproductive des jeunes et à la malnutrition","situation":"Une élève de 15 ans à Bertoua subit la pression de son copain.","tache":"Donne-lui des conseils argumentés."},"verrou":true,"nq":4,"labo":true});
VRT_L("1re-d-svt-r63",{"duree":20,"titre":"Les mutilations génitales et leurs conséquences","accroche":"Une pratique dangereuse et interdite.","intro":"Les mutilations génitales féminines portent gravement atteinte à la santé.","objectifs":["définir les mutilations","citer leurs conséquences","proposer des moyens de lutte"],"parties":[{"t":"Définition","html":"<div class='def'><b>Définition</b>Les <strong>mutilations génitales féminines</strong> sont toutes les interventions qui lèsent ou enlèvent une partie des organes génitaux externes féminins sans raison médicale.</div>"},{"t":"Conséquences","verrou":true},{"t":"Lutte","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"svt","rang":63,"apc":{"module":"Immunité, santé reproductive et nutrition","famille":"Choix et observation de saines habitudes de vie","agir":"Lutter contre les problèmes liés à la santé reproductive des jeunes et à la malnutrition","situation":"Dans le sujet du Probatoire blanc 2026, on demande une affiche contre les mutilations génitales avec trois conséquences.","tache":"Propose le contenu de l'affiche."},"verrou":true,"nq":4,"labo":true});
VRT_L("1re-d-svt-r64",{"duree":20,"titre":"Les stupéfiants et la santé reproductive","accroche":"Tramadol, cannabis, alcool.","intro":"La prise de stupéfiants augmente les comportements à risque et nuit à la fertilité et au fœtus.","objectifs":["citer des stupéfiants","décrire leurs effets","proposer des moyens de prévention"],"parties":[{"t":"Définition","html":"<div class='def'><b>Définition</b>Un <strong>stupéfiant</strong> est une substance qui agit sur le système nerveux et crée une dépendance : cannabis, tramadol détourné, cocaïne ; l'alcool a des effets comparables à forte dose.</div>"},{"t":"Effets sur la reproduction","verrou":true},{"t":"Prévention","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"svt","rang":64,"apc":{"module":"Immunité, santé reproductive et nutrition","famille":"Choix et observation de saines habitudes de vie","agir":"Lutter contre les problèmes liés à la santé reproductive des jeunes et à la malnutrition","situation":"Dans un quartier de Maroua, des jeunes consomment du tramadol mélangé à des boissons sucrées.","tache":"Rédige un message de prévention."},"verrou":true,"nq":4,"labo":true});
VRT_L("1re-d-svt-r65",{"duree":20,"titre":"Intégration : sensibiliser à la santé reproductive","accroche":"Affiche et slogan du Probatoire.","intro":"Les sujets demandent souvent des outils de sensibilisation sur la santé reproductive des jeunes.","objectifs":["exploiter des données","concevoir une affiche","rédiger un slogan"],"parties":[{"t":"Notion","html":"<div class='def'><b>Définition</b>Un <strong>outil de sensibilisation</strong> (affiche, slogan, causerie) informe et incite à adopter des comportements protecteurs.</div>"},{"t":"Démarche","verrou":true},{"t":"Production","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"svt","rang":65,"apc":{"module":"Immunité, santé reproductive et nutrition","famille":"Choix et observation de saines habitudes de vie","agir":"Lutter contre les problèmes liés à la santé reproductive des jeunes et à la malnutrition","situation":"Le tableau du Probatoire blanc 2026 montre une baisse des IVG, des mutilations et des mariages précoces en Afrique centrale.","tache":"Conçois une affiche sur la baisse des IVG et rédige un slogan."},"verrou":true,"nq":4,"labo":true});
VRT_L("1re-d-svt-r66",{"duree":20,"titre":"L'alimentation équilibrée","accroche":"Manger de tout, en bonnes proportions.","intro":"Une alimentation équilibrée couvre les besoins en énergie et en nutriments.","objectifs":["définir l'alimentation équilibrée","citer les groupes d'aliments","répartir les apports"],"parties":[{"t":"Définition","html":"<div class='def'><b>Définition</b>Une <strong>alimentation équilibrée</strong> apporte, en quantité et en qualité, l'énergie et les nutriments nécessaires : environ 50 à 55 % de glucides, 30 à 35 % de lipides et 12 à 15 % de protides.</div>"},{"t":"Groupes d'aliments","verrou":true},{"t":"Répartition","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"svt","rang":66,"apc":{"module":"Immunité, santé reproductive et nutrition","famille":"Choix et observation de saines habitudes de vie","agir":"Lutter contre les problèmes liés à la santé reproductive des jeunes et à la malnutrition","situation":"Une mère de Bafia sert à ses enfants du manioc matin, midi et soir.","tache":"Explique pourquoi ce régime est déséquilibré et propose des compléments."},"verrou":true,"nq":4,"labo":true});
VRT_L("1re-d-svt-r67",{"duree":20,"titre":"Composer un menu équilibré","accroche":"Du ndolé, du plantain, un fruit.","intro":"Composer un menu, c'est associer plusieurs groupes d'aliments dans chaque repas.","objectifs":["composer un menu","vérifier son équilibre","adapter aux besoins"],"parties":[{"t":"Définition","html":"<div class='def'><b>Définition</b>Un <strong>menu équilibré</strong> associe à chaque repas un féculent, une source de protides, des légumes ou des fruits, un produit laitier si possible, et de l'eau.</div>"},{"t":"Exemple","verrou":true},{"t":"Adapter","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"svt","rang":67,"apc":{"module":"Immunité, santé reproductive et nutrition","famille":"Choix et observation de saines habitudes de vie","agir":"Lutter contre les problèmes liés à la santé reproductive des jeunes et à la malnutrition","situation":"La cantine d'un lycée de Douala sert souvent du riz blanc à l'huile.","tache":"Propose un menu équilibré à coût modéré."},"verrou":true,"nq":4,"labo":true});
VRT_L("1re-d-svt-r68",{"duree":20,"titre":"TP 16 : choix et composition de menus équilibrés","accroche":"Calculer l'énergie d'un menu.","intro":"Ce TP met en œuvre le calcul des apports et la composition d'un menu à partir d'une table de composition des aliments.","objectifs":["utiliser une table de composition","calculer l'apport énergétique","corriger un menu"],"parties":[{"t":"Le but","html":"<div class='def'><b>Définition</b>Une <strong>table de composition</strong> donne, pour 100 g d'aliment, les masses de glucides, lipides et protides.</div>"},{"t":"Protocole","verrou":true},{"t":"Résultat","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"svt","rang":68,"apc":{"module":"Immunité, santé reproductive et nutrition","famille":"Choix et observation de saines habitudes de vie","agir":"Lutter contre les problèmes liés à la santé reproductive des jeunes et à la malnutrition","situation":"Un groupe de 1re D de Bafoussam calcule que son menu tire 50 % de son énergie des lipides.","tache":"Propose une correction."},"verrou":true,"nq":4,"labo":true});
VRT_L("1re-d-svt-r69",{"duree":20,"titre":"Conséquences de la mauvaise alimentation et de l'inactivité","accroche":"Kwashiorkor ou obésité.","intro":"Une alimentation déséquilibrée et l'inactivité physique favorisent de nombreuses maladies.","objectifs":["citer les maladies par carence","citer les maladies par excès","proposer une prévention"],"parties":[{"t":"Carences","html":"<div class='def'><b>Définition</b>Une <strong>carence</strong> est un manque d'un nutriment : protides (kwashiorkor), énergie globale (marasme), fer (anémie), iode (goitre), vitamine A (troubles de la vision).</div>"},{"t":"Excès et inactivité","verrou":true},{"t":"Prévention","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"svt","rang":69,"apc":{"module":"Immunité, santé reproductive et nutrition","famille":"Choix et observation de saines habitudes de vie","agir":"Lutter contre les problèmes liés à la santé reproductive des jeunes et à la malnutrition","situation":"Un médecin de Yaoundé constate de plus en plus de jeunes obèses qui passent leurs journées devant les écrans.","tache":"Propose des conseils argumentés."},"verrou":true,"nq":4,"labo":true});
VRT_L("1re-d-svt-r70",{"duree":20,"titre":"Intégration : une cantine équilibrée","accroche":"Bien nourrir sans trop dépenser.","intro":"Le responsable d'une cantine doit proposer des repas équilibrés avec un budget limité.","objectifs":["mobiliser les règles de l'équilibre","composer des menus locaux","argumenter"],"parties":[{"t":"Notion","html":"<div class='def'><b>Définition</b>Un <strong>repas équilibré</strong> associe féculent, protides, légumes ou fruits, et apporte une énergie adaptée.</div>"},{"t":"Ressources locales","verrou":true},{"t":"Production","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"svt","rang":70,"apc":{"module":"Immunité, santé reproductive et nutrition","famille":"Choix et observation de saines habitudes de vie","agir":"Lutter contre les problèmes liés à la santé reproductive des jeunes et à la malnutrition","situation":"L'intendant d'un internat de Bafang dispose d'un budget limité pour 200 élèves.","tache":"Propose un menu équilibré pour un déjeuner et justifie-le."},"verrou":true,"nq":4,"labo":true});
VRT_L("1re-d-svt-r71",{"duree":20,"titre":"L'origine de l'énergie solaire","accroche":"Le Soleil, un réacteur de fusion.","intro":"L'énergie reçue par la Terre provient de réactions nucléaires au cœur du Soleil.","objectifs":["expliquer l'origine de l'énergie solaire","décrire son transfert","citer ses usages"],"parties":[{"t":"Origine","html":"<div class='def'><b>Définition</b>Au cœur du Soleil, la <strong>fusion nucléaire</strong> transforme l'hydrogène en hélium et libère une énergie considérable, émise sous forme de <strong>rayonnement électromagnétique</strong>.</div>"},{"t":"Transfert","html":"<p>Le rayonnement traverse le vide spatial et atteint la Terre en environ 8 minutes ; il comprend de l'ultraviolet, du visible et de l'infrarouge.</p>","labo":{"type":"etapes","items":[["Fusion","cœur du Soleil."],["Rayonnement","à travers l'espace."],["Terre","réception."],["Usages","photosynthèse, panneaux."]]}},{"t":"Usages","html":"<p>Photosynthèse, climat, cycle de l'eau, énergie solaire photovoltaïque et thermique.</p>","retenir":"Fusion de l'hydrogène en hélium."},{"t":"Entraînement au format de l'examen","html":"<div class='integ'><h3>Partie A : évaluation des ressources</h3><p><strong>Évaluation des savoirs (QCM).</strong> L'énergie solaire provient :</p><ol type='a'><li>de combustion de charbon</li><li>de la fusion nucléaire</li><li>de l'électricité</li></ol><details><summary>Voir la réponse</summary><p><strong>de la fusion nucléaire</strong>. Origine.</p></details><p><strong>Évaluation des savoir-faire.</strong></p><p>En combien de temps la lumière du Soleil atteint-elle la Terre ?</p><details><summary>Voir la réponse</summary><p>(Réponse : environ 8 minutes.)</p></details><h3>Partie B : évaluation des compétences</h3><p><strong>Compétence visée.</strong> Limiter les effets des phénomènes naturels et préserver son environnement.</p><p><strong>Situation.</strong> Une école de Kousseri s'équipe de panneaux solaires. Un élève affirme que le Soleil « brûle du charbon » pour produire sa lumière.</p><p><strong>Consigne 1.</strong> Corrige cette affirmation en expliquant l'origine de l'énergie solaire.</p><p><strong>Consigne 2.</strong> Explique comment cette énergie parvient jusqu'aux panneaux.</p><details><summary>Voir une réponse attendue</summary><p>L'énergie solaire provient de la fusion nucléaire de l'hydrogène en hélium au cœur du Soleil. Elle est émise sous forme de rayonnement électromagnétique qui traverse le vide et atteint la Terre en environ 8 minutes.</p></details></div>","retenir":"Savoir-être mobilisé : Souci de l'environnement."}],"revision":["Fusion.","Rayonnement.","Usages."],"exo":"<p>En combien de temps la lumière du Soleil atteint-elle la Terre ? <em>(Réponse : environ 8 minutes.)</em></p>","quiz":[{"q":"L'énergie solaire provient :","r":["de combustion de charbon","de la fusion nucléaire","de l'électricité"],"b":1,"e":"Origine."},{"q":"La fusion transforme l'hydrogène en :","r":["hélium","oxygène","carbone"],"b":0,"e":"Réaction."},{"q":"Le rayonnement solaire traverse :","r":["uniquement l'air","uniquement l'eau","le vide spatial"],"b":2,"e":"Transfert."},{"q":"Un usage de l'énergie solaire est :","r":["le charbon","la photosynthèse","le pétrole"],"b":1,"e":"Exemple."}],"c":"1re D","m":"svt","rang":71,"apc":{"module":"Énergie solaire, structure de la Terre et roches sédimentaires","famille":"Préservation de l'environnement","agir":"Limiter les effets des phénomènes naturels et préserver son environnement","situation":"Une école de Kousseri installe des panneaux solaires pour s'éclairer.","tache":"Explique l'origine de l'énergie captée."},"gratuit":true});
VRT_L("1re-d-svt-r72",{"duree":20,"titre":"La Terre ne reçoit qu'une partie du rayonnement","accroche":"Un tiers repart vers l'espace.","intro":"Une partie du rayonnement solaire est réfléchie, une autre absorbée par l'atmosphère et la surface.","objectifs":["définir l'albédo","décrire le devenir du rayonnement","comparer des surfaces"],"parties":[{"t":"Albédo","html":"<div class='def'><b>Définition</b>L'<strong>albédo</strong> est la fraction du rayonnement réfléchie par une surface. L'albédo moyen de la Terre est d'environ 30 %.</div>"},{"t":"Devenir","verrou":true},{"t":"Surfaces","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"svt","rang":72,"apc":{"module":"Énergie solaire, structure de la Terre et roches sédimentaires","famille":"Préservation de l'environnement","agir":"Limiter les effets des phénomènes naturels et préserver son environnement","situation":"Dans le Nord, la déforestation remplace la forêt par des sols nus et clairs.","tache":"Comment évolue l'albédo de la région ?"},"verrou":true,"nq":4,"labo":true});
VRT_L("1re-d-svt-r73",{"duree":20,"titre":"Constante solaire et bilan radiatif","accroche":"Ce qui entre doit ressortir.","intro":"La Terre reçoit et émet de l'énergie : l'équilibre de ces flux fixe sa température moyenne.","objectifs":["définir la constante solaire","établir le bilan radiatif","expliquer l'équilibre"],"parties":[{"t":"Constante solaire","html":"<div class='def'><b>Définition</b>La <strong>constante solaire</strong> est la puissance reçue par 1 m² placé perpendiculairement aux rayons, au sommet de l'atmosphère : environ 1 361 W/m².</div>"},{"t":"Puissance moyenne","verrou":true},{"t":"Bilan radiatif","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"svt","rang":73,"apc":{"module":"Énergie solaire, structure de la Terre et roches sédimentaires","famille":"Préservation de l'environnement","agir":"Limiter les effets des phénomènes naturels et préserver son environnement","situation":"Un élève de Garoua mesure qu'un panneau solaire reçoit beaucoup plus à midi qu'au lever du Soleil.","tache":"Explique cette différence."},"verrou":true,"nq":4,"labo":true});
VRT_L("1re-d-svt-r74",{"duree":20,"titre":"L'effet de serre","accroche":"Sans lui, il ferait −18 °C.","intro":"Certains gaz de l'atmosphère retiennent une partie de l'infrarouge émis par la Terre.","objectifs":["définir l'effet de serre","citer les gaz à effet de serre","distinguer effet naturel et renforcé"],"parties":[{"t":"Définition","html":"<div class='def'><b>Définition</b>L'<strong>effet de serre</strong> est le réchauffement de la surface dû à des gaz atmosphériques (vapeur d'eau, CO₂, méthane) qui absorbent l'infrarouge émis par la Terre et en renvoient une partie vers le sol.</div>"},{"t":"Importance","verrou":true},{"t":"Effet renforcé","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"svt","rang":74,"apc":{"module":"Énergie solaire, structure de la Terre et roches sédimentaires","famille":"Préservation de l'environnement","agir":"Limiter les effets des phénomènes naturels et préserver son environnement","situation":"Les pêcheurs de Kribi observent que la mer gagne sur la plage d'année en année.","tache":"Relie cette observation à l'effet de serre."},"verrou":true,"nq":4,"labo":true});
VRT_L("1re-d-svt-r75",{"duree":20,"titre":"Intégration : un climat qui change au Nord","accroche":"Des pluies irrégulières.","intro":"Les agriculteurs du Nord observent des saisons des pluies plus courtes et plus irrégulières.","objectifs":["mobiliser bilan radiatif et effet de serre","proposer des actions d'adaptation","rédiger un texte"],"parties":[{"t":"Notion","html":"<div class='def'><b>Définition</b>Le <strong>réchauffement climatique</strong> modifie la répartition des pluies et accroît les sécheresses dans les régions sahéliennes.</div>"},{"t":"Actions","verrou":true},{"t":"Production","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"svt","rang":75,"apc":{"module":"Énergie solaire, structure de la Terre et roches sédimentaires","famille":"Préservation de l'environnement","agir":"Limiter les effets des phénomènes naturels et préserver son environnement","situation":"Dans la région de Maroua, les pluies commencent plus tard et s'arrêtent plus tôt qu'autrefois.","tache":"Rédige des conseils argumentés pour les agriculteurs."},"verrou":true,"nq":4,"labo":true});
VRT_L("1re-d-svt-r76",{"duree":20,"titre":"L'inégale répartition de l'énergie solaire","accroche":"Pourquoi l'équateur est plus chaud que les pôles.","intro":"La quantité d'énergie reçue dépend de la latitude et des saisons.","objectifs":["expliquer l'effet de la latitude","expliquer les saisons","relier aux climats"],"parties":[{"t":"Latitude","html":"<div class='def'><b>Définition</b>Plus la latitude augmente, plus les rayons arrivent <strong>obliquement</strong> : la même énergie se répartit sur une plus grande surface et chaque m² reçoit moins.</div>"},{"t":"Saisons","verrou":true},{"t":"Conséquences","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"svt","rang":76,"apc":{"module":"Énergie solaire, structure de la Terre et roches sédimentaires","famille":"Préservation de l'environnement","agir":"Limiter les effets des phénomènes naturels et préserver son environnement","situation":"Un élève de Yaoundé se demande pourquoi il n'y a pas d'hiver froid au Cameroun.","tache":"Explique-le."},"verrou":true,"nq":4,"labo":true});
VRT_L("1re-d-svt-r77",{"duree":20,"titre":"Les mouvements atmosphériques","accroche":"Harmattan et mousson.","intro":"Les différences de température créent des différences de pression qui mettent l'air en mouvement.","objectifs":["expliquer la naissance des vents","décrire la circulation générale","relier aux saisons du Cameroun"],"parties":[{"t":"Principe","html":"<div class='def'><b>Définition</b>L'air chauffé s'élève et crée une zone de <strong>basse pression</strong> ; l'air froid descend et crée une <strong>haute pression</strong>. Le <strong>vent</strong> souffle des hautes vers les basses pressions.</div>"},{"t":"Circulation générale","verrou":true},{"t":"Au Cameroun","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"svt","rang":77,"apc":{"module":"Énergie solaire, structure de la Terre et roches sédimentaires","famille":"Préservation de l'environnement","agir":"Limiter les effets des phénomènes naturels et préserver son environnement","situation":"Le long de la côte de Limbé, les pirogues rentrent facilement à la plage en fin de journée.","tache":"Explique ce phénomène."},"verrou":true,"nq":4,"labo":true});
VRT_L("1re-d-svt-r78",{"duree":20,"titre":"Les mouvements océaniques","accroche":"Des fleuves dans la mer.","intro":"Les vents et les différences de densité mettent en mouvement les eaux océaniques.","objectifs":["décrire les courants de surface","décrire la circulation profonde","expliquer le rôle climatique"],"parties":[{"t":"Courants de surface","html":"<div class='def'><b>Définition</b>Les <strong>courants de surface</strong> sont entraînés par les vents ; le courant de Guinée longe la côte du golfe de Guinée.</div>"},{"t":"Circulation profonde","verrou":true},{"t":"Rôle","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"svt","rang":78,"apc":{"module":"Énergie solaire, structure de la Terre et roches sédimentaires","famille":"Préservation de l'environnement","agir":"Limiter les effets des phénomènes naturels et préserver son environnement","situation":"Les pêcheurs du golfe de Guinée remarquent des saisons où le poisson abonde près des côtes.","tache":"Propose une explication."},"verrou":true,"nq":4,"labo":true});
VRT_L("1re-d-svt-r79",{"duree":20,"titre":"Intégration : pêche et vents de la côte","accroche":"Lire le ciel et la mer.","intro":"Une coopérative de pêcheurs veut organiser ses sorties en tenant compte des vents et des courants.","objectifs":["mobiliser brises et courants","proposer un calendrier","argumenter"],"parties":[{"t":"Notion","html":"<div class='def'><b>Définition</b>Les <strong>brises</strong> et les <strong>courants</strong> résultent de l'inégal réchauffement de la terre et de la mer.</div>"},{"t":"Conseils","verrou":true},{"t":"Production","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"svt","rang":79,"apc":{"module":"Énergie solaire, structure de la Terre et roches sédimentaires","famille":"Préservation de l'environnement","agir":"Limiter les effets des phénomènes naturels et préserver son environnement","situation":"La coopérative des pêcheurs de Limbé veut réduire le carburant de ses pirogues à moteur.","tache":"Propose une organisation des sorties."},"verrou":true,"nq":4,"labo":true});
VRT_L("1re-d-svt-r86",{"duree":20,"titre":"Altération et érosion des roches","accroche":"La roche devient sol.","intro":"Sous l'action de l'eau, de la chaleur et des êtres vivants, les roches se dégradent.","objectifs":["distinguer altération et érosion","décrire l'altération physique et chimique","relier aux sols tropicaux"],"parties":[{"t":"Définitions","html":"<div class='def'><b>Définition</b>L'<strong>altération</strong> est la dégradation des roches sur place ; l'<strong>érosion</strong> est l'enlèvement des produits de cette dégradation par l'eau, le vent ou la glace.</div>"},{"t":"Deux types d'altération","verrou":true},{"t":"En milieu tropical","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"svt","rang":86,"apc":{"module":"Énergie solaire, structure de la Terre et roches sédimentaires","famille":"Préservation de l'environnement","agir":"Limiter les effets des phénomènes naturels et préserver son environnement","situation":"Sur une route de l'Ouest, un talus de granite est devenu une terre rouge friable.","tache":"Explique cette transformation."},"verrou":true,"nq":4,"labo":true});
VRT_L("1re-d-svt-r87",{"duree":20,"titre":"Transport des produits d'altération et d'érosion","accroche":"Les rivières trient les grains.","intro":"Les produits de l'érosion sont transportés par l'eau et le vent, puis triés selon leur taille.","objectifs":["citer les modes de transport","expliquer le tri","relier énergie et transport"],"parties":[{"t":"Modes de transport","html":"<div class='def'><b>Définition</b>Les particules sont transportées par <strong>roulement</strong>, <strong>saltation</strong>, <strong>suspension</strong> ou en <strong>solution</strong> (ions dissous).</div>"},{"t":"Tri","verrou":true},{"t":"Exemples","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"svt","rang":87,"apc":{"module":"Énergie solaire, structure de la Terre et roches sédimentaires","famille":"Préservation de l'environnement","agir":"Limiter les effets des phénomènes naturels et préserver son environnement","situation":"Après une forte pluie à Bafoussam, la rivière est boueuse et roule des cailloux.","tache":"Explique ce que transporte la rivière."},"verrou":true,"nq":4,"labo":true});
VRT_L("1re-d-svt-r88",{"duree":20,"titre":"Sédimentation et diagenèse","accroche":"Du sable au grès.","intro":"Les sédiments se déposent puis se transforment lentement en roches.","objectifs":["définir sédimentation et diagenèse","décrire les étapes de la diagenèse","citer des exemples"],"parties":[{"t":"Définitions","html":"<div class='def'><b>Définition</b>La <strong>sédimentation</strong> est le dépôt des particules dans un bassin (lac, mer, delta). La <strong>diagenèse</strong> est l'ensemble des transformations qui changent un sédiment meuble en roche sédimentaire.</div>"},{"t":"Étapes","verrou":true},{"t":"Exemples","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"svt","rang":88,"apc":{"module":"Énergie solaire, structure de la Terre et roches sédimentaires","famille":"Préservation de l'environnement","agir":"Limiter les effets des phénomènes naturels et préserver son environnement","situation":"Au bord du lac Tchad, des couches de boue s'accumulent chaque année.","tache":"Que deviendront-elles dans des millions d'années ?"},"verrou":true,"nq":4,"labo":true});
VRT_L("1re-d-svt-r89",{"duree":20,"titre":"Diagenèse et roches sédimentaires","accroche":"Grès, calcaire, charbon, pétrole.","intro":"Les roches sédimentaires se classent selon leur origine.","objectifs":["classer les roches sédimentaires","reconnaître quelques roches","expliquer leur intérêt"],"parties":[{"t":"Classification","html":"<div class='def'><b>Définition</b>Les <strong>roches sédimentaires</strong> sont détritiques (grès, argile, conglomérat), chimiques ou biochimiques (calcaire, sel) ou organiques (charbon, pétrole).</div>"},{"t":"Reconnaître","verrou":true},{"t":"Intérêt","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"svt","rang":89,"apc":{"module":"Énergie solaire, structure de la Terre et roches sédimentaires","famille":"Préservation de l'environnement","agir":"Limiter les effets des phénomènes naturels et préserver son environnement","situation":"Une cimenterie au Cameroun utilise du calcaire extrait d'une carrière du Nord.","tache":"Comment le géologue vérifie-t-il qu'il s'agit bien de calcaire ?"},"verrou":true,"nq":4,"labo":true});
VRT_L("1re-d-svt-r90",{"duree":20,"titre":"Séries et cycles sédimentaires","accroche":"Quand la mer avance et recule.","intro":"La succession des couches enregistre les variations du niveau marin.","objectifs":["définir une série sédimentaire","reconnaître transgression et régression","lire une colonne stratigraphique"],"parties":[{"t":"Définition","html":"<div class='def'><b>Définition</b>Une <strong>série sédimentaire</strong> est une succession de couches déposées dans un même bassin. Un <strong>cycle sédimentaire</strong> comprend une transgression puis une régression.</div>"},{"t":"Transgression et régression","verrou":true},{"t":"Lecture","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"svt","rang":90,"apc":{"module":"Énergie solaire, structure de la Terre et roches sédimentaires","famille":"Préservation de l'environnement","agir":"Limiter les effets des phénomènes naturels et préserver son environnement","situation":"Dans le bassin sédimentaire de Douala, un forage traverse de bas en haut : grès, argiles, calcaires.","tache":"Interprète cette succession."},"verrou":true,"nq":4,"labo":true});
VRT_L("1re-d-svt-r91",{"duree":20,"titre":"La chronologie relative et ses principes","accroche":"Plus bas, plus ancien.","intro":"Des principes simples permettent d'ordonner les événements géologiques.","objectifs":["énoncer les principes","les appliquer à une coupe","dater relativement un événement"],"parties":[{"t":"Définition","html":"<div class='def'><b>Définition</b>La <strong>chronologie relative</strong> ordonne les événements géologiques les uns par rapport aux autres, sans donner d'âge en années.</div>"},{"t":"Principes","verrou":true},{"t":"Application","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"svt","rang":91,"apc":{"module":"Énergie solaire, structure de la Terre et roches sédimentaires","famille":"Préservation de l'environnement","agir":"Limiter les effets des phénomènes naturels et préserver son environnement","situation":"Une coupe géologique près de Garoua montre trois couches traversées par un filon de basalte.","tache":"Ordonne les événements."},"verrou":true,"nq":4,"labo":true});
VRT_L("1re-d-svt-r92",{"duree":20,"titre":"Reconstitution des milieux sédimentaires","accroche":"Lire le passé dans une roche.","intro":"Les caractères d'une roche et ses fossiles renseignent sur le milieu où elle s'est formée.","objectifs":["utiliser le principe d'actualisme","exploiter les fossiles","reconstituer un milieu"],"parties":[{"t":"Actualisme","html":"<div class='def'><b>Définition</b>Le <strong>principe d'actualisme</strong> : les phénomènes qui ont agi dans le passé sont les mêmes que ceux observés aujourd'hui.</div>"},{"t":"Indices","verrou":true},{"t":"Reconstitution","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"svt","rang":92,"apc":{"module":"Énergie solaire, structure de la Terre et roches sédimentaires","famille":"Préservation de l'environnement","agir":"Limiter les effets des phénomènes naturels et préserver son environnement","situation":"Des élèves de Kumba découvrent des coquillages fossiles dans une roche loin de la mer.","tache":"Que peux-tu en déduire ?"},"verrou":true,"nq":4,"labo":true});
VRT_L("1re-d-svt-r93",{"duree":20,"titre":"Intégration : lutter contre le ravinement","accroche":"Des ravines menacent le quartier.","intro":"Les pluies violentes creusent des ravines dans les sols nus et menacent les habitations.","objectifs":["mobiliser altération, érosion et transport","proposer des solutions","rédiger un texte et un slogan"],"parties":[{"t":"Notion","html":"<div class='def'><b>Définition</b>Le <strong>ravinement</strong> est une forme d'érosion due à l'eau qui ruisselle et creuse des sillons dans un sol nu.</div>"},{"t":"Solutions","verrou":true},{"t":"Production","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"svt","rang":93,"apc":{"module":"Énergie solaire, structure de la Terre et roches sédimentaires","famille":"Préservation de l'environnement","agir":"Limiter les effets des phénomènes naturels et préserver son environnement","situation":"À Maroua, des ravines profondes se forment après chaque saison des pluies et menacent des maisons.","tache":"Rédige un texte argumenté et propose un slogan."},"verrou":true,"nq":4,"labo":true});
VRT_L("1re-d-svt-r80",{"duree":20,"titre":"Les ondes sismiques","accroche":"Un séisme fait vibrer toute la Terre.","intro":"Les séismes produisent des ondes qui traversent le globe et renseignent sur sa structure.","objectifs":["distinguer ondes P, S et L","lire un sismogramme","localiser un épicentre"],"parties":[{"t":"Les ondes","html":"<div class='def'><b>Définition</b>Un séisme émet des <strong>ondes P</strong> (longitudinales, les plus rapides, traversent solides et liquides), des <strong>ondes S</strong> (transversales, ne traversent pas les liquides) et des <strong>ondes L</strong> (de surface, les plus destructrices).</div>"},{"t":"Le sismogramme","verrou":true},{"t":"Localisation","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"svt","rang":80,"apc":{"module":"Énergie solaire, structure de la Terre et roches sédimentaires","famille":"Préservation de l'environnement","agir":"Limiter les effets des phénomènes naturels et préserver son environnement","situation":"Une station sismique de Yaoundé enregistre les ondes P puis, 40 secondes plus tard, les ondes S d'un séisme.","tache":"Que permet de calculer ce retard ?"},"verrou":true,"nq":4,"labo":true});
VRT_L("1re-d-svt-r81",{"duree":20,"titre":"Comportement des ondes sismiques dans le globe","accroche":"Des zones où les ondes disparaissent.","intro":"Les ondes changent de vitesse et de direction à certaines profondeurs : ces anomalies révèlent la structure interne.","objectifs":["décrire réfraction et réflexion","interpréter la zone d'ombre","déduire l'état du noyau externe"],"parties":[{"t":"Réfraction","html":"<div class='def'><b>Définition</b>À chaque changement de milieu (discontinuité), les ondes sont <strong>réfractées</strong> (déviées) et partiellement <strong>réfléchies</strong>.</div>"},{"t":"Zone d'ombre","verrou":true},{"t":"Noyau externe liquide","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"svt","rang":81,"apc":{"module":"Énergie solaire, structure de la Terre et roches sédimentaires","famille":"Préservation de l'environnement","agir":"Limiter les effets des phénomènes naturels et préserver son environnement","situation":"Un réseau de stations sur tout le globe enregistre un séisme survenu en Indonésie.","tache":"Explique pourquoi certaines stations ne reçoivent pas d'ondes P directes."},"verrou":true,"nq":4,"labo":true});
VRT_L("1re-d-svt-r82",{"duree":20,"titre":"Les enveloppes internes du globe","accroche":"Croûte, manteau, noyau.","intro":"La sismologie a permis de découvrir les grandes enveloppes de la Terre et leurs limites.","objectifs":["nommer les enveloppes","nommer les discontinuités","distinguer lithosphère et asthénosphère"],"parties":[{"t":"Les enveloppes","html":"<div class='def'><b>Définition</b>La Terre comprend la <strong>croûte</strong>, le <strong>manteau</strong> et le <strong>noyau</strong> (externe liquide, interne solide), séparés par des discontinuités : Moho, Gutenberg (2 900 km), Lehmann (5 150 km).</div>"},{"t":"Croûtes","verrou":true},{"t":"Lithosphère et asthénosphère","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"svt","rang":82,"apc":{"module":"Énergie solaire, structure de la Terre et roches sédimentaires","famille":"Préservation de l'environnement","agir":"Limiter les effets des phénomènes naturels et préserver son environnement","situation":"Un élève de Bamenda fabrique une maquette en coupe de la Terre.","tache":"Liste les enveloppes et les discontinuités à représenter."},"verrou":true,"nq":4,"labo":true});
VRT_L("1re-d-svt-r83",{"duree":20,"titre":"Composition et propriétés des enveloppes","accroche":"Plus on descend, plus c'est dense et chaud.","intro":"Chaque enveloppe a une composition, une densité et une température propres.","objectifs":["donner la composition des enveloppes","décrire l'évolution de la densité","décrire l'évolution de la température"],"parties":[{"t":"Composition","html":"<div class='def'><b>Définition</b>La croûte est riche en silicium, oxygène et aluminium ; le <strong>manteau</strong> est formé de <strong>péridotite</strong> ; le <strong>noyau</strong> est surtout fait de <strong>fer et de nickel</strong>.</div>"},{"t":"Densité","verrou":true},{"t":"Température","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"svt","rang":83,"apc":{"module":"Énergie solaire, structure de la Terre et roches sédimentaires","famille":"Préservation de l'environnement","agir":"Limiter les effets des phénomènes naturels et préserver son environnement","situation":"Un élève de Kumba se demande pourquoi la Terre est plus dense en moyenne que les roches de surface.","tache":"Explique-le."},"verrou":true,"nq":4,"labo":true});
VRT_L("1re-d-svt-r84",{"duree":20,"titre":"L'énergie interne de la Terre","accroche":"Une chaleur venue de l'intérieur.","intro":"La Terre produit de la chaleur qui s'évacue par le volcanisme, les séismes et la convection.","objectifs":["citer l'origine de l'énergie interne","décrire sa dissipation","citer des usages"],"parties":[{"t":"Origine","html":"<div class='def'><b>Définition</b>L'<strong>énergie interne</strong> de la Terre provient surtout de la <strong>désintégration d'éléments radioactifs</strong> (uranium, thorium, potassium) et de la chaleur primitive.</div>"},{"t":"Dissipation","verrou":true},{"t":"Usages","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"svt","rang":84,"apc":{"module":"Énergie solaire, structure de la Terre et roches sédimentaires","famille":"Préservation de l'environnement","agir":"Limiter les effets des phénomènes naturels et préserver son environnement","situation":"Des habitants de Buea s'interrogent sur l'origine des éruptions du mont Cameroun.","tache":"Explique l'origine de l'énergie qui les provoque."},"verrou":true,"nq":4,"labo":true});
VRT_L("1re-d-svt-r85",{"duree":20,"titre":"Intégration : se préparer aux séismes","accroche":"Savoir où et comment agir.","intro":"La région du mont Cameroun connaît une activité sismique et volcanique : la population doit s'y préparer.","objectifs":["mobiliser les connaissances sur les séismes","proposer des consignes","rédiger un texte et une affiche"],"parties":[{"t":"Notion","html":"<div class='def'><b>Définition</b>Un <strong>séisme</strong> libère brutalement de l'énergie accumulée dans les roches ; ses ondes de surface causent l'essentiel des dégâts.</div>"},{"t":"Consignes","verrou":true},{"t":"Production","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"svt","rang":85,"apc":{"module":"Énergie solaire, structure de la Terre et roches sédimentaires","famille":"Préservation de l'environnement","agir":"Limiter les effets des phénomènes naturels et préserver son environnement","situation":"Le lycée de Buea prépare un exercice d'alerte sismique.","tache":"Rédige les consignes à afficher."},"verrou":true,"nq":4,"labo":true});
